// بيانات السور
Object.assign(quranData, {
    6: { // سورة الأنعام
        name: "الأنعام",
        basmalaTafsir: ``,
        verses: [
            { text: "ٱلْحَمْدُ لِلَّهِ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَ ثُمَّ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ يَعْدِلُونَ", tafsir: `` },
            { text: "هُوَ ٱلَّذِى خَلَقَكُم مِّن طِينٍ ثُمَّ قَضَىٰٓ أَجَلًا وَأَجَلٌ مُّسَمًّى عِندَهُۥ ثُمَّ أَنتُمْ تَمْتَرُونَ", tafsir: `` },
            { text: "وَهُوَ ٱللَّهُ فِى ٱلسَّمَٰوَٰتِ وَفِى ٱلْأَرْضِ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَ", tafsir: `لا إله غيره ( فِي السَّماواتِ وَفِي الْأَرْضِ ) أي أن الخالق والمتصرف في هذا الكون ليس إلا الله ، خلافا لمن كان يجعل للسماء إلها خاصا ، وللأرض إلها غيره. ومعنى « في » الظرفية المجازية ، وإلا فليس لله سبحانه مكان ، إذ المكان يوجب التحديد ، والتحديد يوجب التجزئة ، والتجزئة من صفات المصنوع لا الصانع ( يَعْلَمُ سِرَّكُمْ ) الخفي المكتوم ، أعم مما في الصدور ، أو من الأسرار ( وَجَهْرَكُمْ ) مقابل ذلك بالمعنيين ( وَيَعْلَمُ ما تَكْسِبُونَ ) أي ما تعملون من الأعمال ، فإن العمل من كسب الإنسان. وفي هذه الآيات ردّ على وَما تَأْتِيهِمْ مِنْ آيَةٍ مِنْ آياتِ رَبِّهِمْ إِلاَّ كانُوا عَنْها مُعْرِضِينَ ( 5 ) فَقَدْ كَذَّبُوا بِالْحَقِّ لَمَّا جاءَهُمْ فَسَوْفَ يَأْتِيهِمْ أَنْباءُ ما كانُوا بِهِ يَسْتَهْزِؤُنَ ( 6 ) أَ لَمْ يَرَوْا كَمْ أَهْلَكْنا مِنْ قَبْلِهِمْ مِنْ قَرْنٍ الدهرية القائلين بقدم السماوات والأرض ، والثنوية القائلين بإلهين : نور وظلمة ، والمشركين الذين يجعلون له سبحانه شريكا ، والجهّال من الفلاسفة الذين يقولون بعدم عموم علمه أو قدرته ، ومن أشبههم من أصحاب العقائد الزائفة حول إله الكون. [5] ثم أخبر سبحانه عن الكفار الذين تقدم ذكرهم في أول السورة ، قال : ( وَما تَأْتِيهِمْ مِنْ آيَةٍ ) أي معجزة ودليل وبرهان وحجة ( مِنْ آياتِ رَبِّهِمْ ) الدالة على وجوده وصدق رسالتك يا رسول الله ( إِلَّا كانُوا عَنْها مُعْرِضِينَ ) لا يقبلونها ولا ينظرون إليها نظر منصف معتبر.` },
            { text: "وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ", tafsir: `` },
            { text: "فَقَدْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ فَسَوْفَ يَأْتِيهِمْ أَنۢبَٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ", tafsir: `أي الكفار ( بِالْحَقِّ لَمَّا جاءَهُمْ ) من القرآن والرسول وسائر الآيات ( فَسَوْفَ ) في القيامة ، أو في الدنيا حين ظهور الرسول ووضوح صدقه بالسيطرة والغلبة ـ كما أخبر ـ ( يَأْتِيهِمْ أَنْباءُ ) أي أخبار ( ما كانُوا بِهِ يَسْتَهْزِؤُنَ ) من الحق. وفي الآية تهديد ، كما تقول للمجرم : « سوف تعلم إجرامك » تريد أنه يلاقي جزاءه ، إن كان المراد ب « سوف » القيامة. [7] ثم حذرهم سبحانه أن يصيبهم ما أصاب الأمم السالفة حيث كذبوا وعصوا وعتوا عن أمر ربهم ( أَ لَمْ يَرَوْا ) استفهام تذكيري توبيخي ، أي « ألم يعلموا » ـ فإن الرؤية تستعمل بمعنى العلم ـ ( كَمْ أَهْلَكْنا مِنْ قَبْلِهِمْ مِنْ قَرْنٍ ) أي من الأمم ، و « القرن » أهل كل عصر ، وسمّوا بذلك لأن مَكَّنَّاهُمْ فِي الْأَرْضِ ما لَمْ نُمَكِّنْ لَكُمْ وَأَرْسَلْنَا السَّماءَ عَلَيْهِمْ مِدْراراً وَجَعَلْنَا الْأَنْهارَ تَجْرِي مِنْ تَحْتِهِمْ فَأَهْلَكْناهُمْ بِذُنُوبِهِمْ بعضهم يقترن ببعض ، ولذا اختلف في المدة المراد به ، لاختلاف الاعتبار ( مَكَّنَّاهُمْ ) أي تلك الأمم ( فِي الْأَرْضِ ) بأن جعلناهم ملوكا وقادة وساسة ذا عدد وعدد وإمكانيات ( ما لَمْ نُمَكِّنْ لَكُمْ ) حيث كانوا هم أكثر تمكنا منكم. والظاهر أن الخطاب خاص بالكفار في زمن الرسول صلى‌الله‌عليه‌وآله‌وسلم حيث كان السابقون أكثر تمكنا منهم. لا يقال : إن من المحتمل كون بعض الأمم السالفة أكثر تمكنا من جميع من يأتي إلى يوم القيامة حتى يكون الخطاب عاما ؟ لأن الجواب ظاهر ، إذ قوله : « ألم يروا » ينافي ذلك فإن الناس لم يعلموا أخبار هكذا أمة ـ كما تقولون ـ بل ما رواه إنما هو أخبار الأمم التي كانت أقوى من الكفار في زمانه صلى‌الله‌عليه‌وآله‌وسلم ( وَأَرْسَلْنَا السَّماءَ عَلَيْهِمْ مِدْراراً ) هو من « درّ إذا هطل » ، و « مدرار » صيغة مبالغة ، أي كثيرة الهطول ، حتّى عمّهم الخير والبركة والثروة. والمراد بالسماء : المطر ، بعلاقة الحال والمحل ، كما قال الشاعر : إذا نزل السماء بأرض قوم رعيناه وإن كانوا غضابا ( وَجَعَلْنَا الْأَنْهارَ ) أي مياهها بعلاقة الحال والمحل ( تَجْرِي مِنْ تَحْتِهِمْ ) أي تحت قصورهم وأشجارهم ، أو باعتبار أن الماء تحت سطح الأرض التي يمشون عليها. وكل ذلك لم يفدهم في بقائهم وحسن ذكرهم ( فَأَهْلَكْناهُمْ بِذُنُوبِهِمْ ) والمراد : هلاكهم بذهاب أثرهم وانقطاع نسلهم وعقبهم ، وفناء حضارتهم ، بسبب عصيانهم وكفرهم مقابل الأنبياء عليهم‌السلام والصالحين الذين بقوا إلى يوم الناس هذا ، وإن وَأَنْشَأْنا مِنْ بَعْدِهِمْ قَرْناً آخَرِينَ ( 7 ) وَلَوْ نَزَّلْنا عَلَيْكَ كِتاباً فِي قِرْطاسٍ فَلَمَسُوهُ بِأَيْدِيهِمْ لَقالَ الَّذِينَ كَفَرُوا إِنْ هذا إِلاَّ سِحْرٌ مُبِينٌ ( 8 ) وَقالُوا لَوْ لا أُنْزِلَ عَلَيْهِ مَلَكٌ وَلَوْ أَنْزَلْنا مَلَكاً لَقُضِيَ الْأَمْرُ ثُمَّ لا يُنْظَرُونَ ( 9 ) صلاحهم وحسن أعمالهم سبب بقاء آثارهم وبقاء ذكرهم وبقاء مناهجهم ( وَأَنْشَأْنا مِنْ بَعْدِهِمْ قَرْناً آخَرِينَ ) أي خلّفنا من بعدهم أمة أخرى وجماعة آخرين. [8] ثم بيّن سبحانه أن هؤلاء الكفار معاندون في كفرهم ، لا لأنهم لم يعملوا الحق ( وَلَوْ نَزَّلْنا عَلَيْكَ ) يا رسول الله ( كِتاباً فِي قِرْطاسٍ ) أي مكتوبا في ورق يشهد لك بصدقك ( فَلَمَسُوهُ بِأَيْدِيهِمْ ) أي مسّوه بيدهم ، حتى يتيقنوا بأن ذلك ليس من الشعوذة وستر العيون ( لَقالَ الَّذِينَ كَفَرُوا إِنْ هذا ) أي ما هذا الكتاب ( إِلَّا سِحْرٌ مُبِينٌ ) أي سحر ظاهر ، فلا يصدقونك. قالوا : نزلت هذه الآية في جماعة من الكفار قالوا : يا محمد لا نؤمن لك حتى تأتينا بكتاب من عند الله معه أربعة من الملائكة يشهدون عليه أنه من عند الله وأنك رسوله.` },
            { text: "أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ مَّكَّنَّٰهُمْ فِى ٱلْأَرْضِ مَا لَمْ نُمَكِّن لَّكُمْ وَأَرْسَلْنَا ٱلسَّمَآءَ عَلَيْهِم مِّدْرَارًا وَجَعَلْنَا ٱلْأَنْهَٰرَ تَجْرِى مِن تَحْتِهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ وَأَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ", tafsir: `` },
            { text: "وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَٰبًا فِى قِرْطَاسٍ فَلَمَسُوهُ بِأَيْدِيهِمْ لَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ", tafsir: `` },
            { text: "وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ مَلَكٌ وَلَوْ أَنزَلْنَا مَلَكًا لَّقُضِىَ ٱلْأَمْرُ ثُمَّ لَا يُنظَرُونَ", tafsir: `أي قال هؤلاء الكفار ( لَوْ لا ) أي هلّا ، ولماذا ما ( أُنْزِلَ عَلَيْهِ مَلَكٌ ) أي على الرسول ، ملك نشاهده فنصدق به ، ثم رد الله عليهم مقالتهم بأنه ( وَلَوْ أَنْزَلْنا مَلَكاً ) كما اقترحوه ( لَقُضِيَ الْأَمْرُ ) أي انتهى أمدهم وأجلهم ( ثُمَّ لا يُنْظَرُونَ ) أي يهلكون ويموتون ، وذلك لما جرت سنة الله أن لا تنزل الملائكة بالنسبة إلى المعاندين ، إلا وقت موتهم. وَلَوْ جَعَلْناهُ مَلَكاً لَجَعَلْناهُ رَجُلاً وهنا سؤال : إن هذا لا يكون جوابا للكفار ـ على هذا المعنى ـ إذ لهم أن يقولوا : فليغيّر الله سنته ، بأن ينزل الملك ويبقينا حتى نؤمن ؟ وسؤال ثان : لماذا جرت سنة الله على ذلك ، أليس هداية الناس غاية الخلقة ، فما المانع من توفر أسباب الهداية بإنزال الملك ؟ والجواب عن الأول : إن سنة الله جرت على الهلاك عقب مجيء الملائكة ، كما جرت سنته على الإحراق عقيب الإلقاء في النار ، وليس للكفار أن يشكلوا بهذا الإشكال ، إذ يقول النبي : ولماذا تريدون نزول الملائكة ؟ أ للعناد ؟ فلا داعي إلى إجابتكم ، أم لأنه خارق والإتيان بالخارق موجب للتصديق ؟ فقد أتيت بالخوارق ، أم لأنه خارق خاص ؟ فالخارق الخاص لا يلزم إجابته لدى العقل والعقلاء ، وهذا كما إذا حمل الطبيب شهادة الكلية فيقول له المريض : ائتني بشهادة رئيس الحكومة ، إنه سؤال سخيف لدى العقلاء .. والجواب عن الثاني : إنه سبحانه علم عنادهم وأنه لا يفيد معهم إنزال الملك ، كما بيّن ذلك في قوله ( وَلَوْ نَزَّلْنا عَلَيْكَ كِتاباً ) (1) ، وما كان يمنعهم أن يقولوا أن ما يشاهدونه من صورة الملك إنما هو سحر مبين ! [10] ثم بيّن سبحانه وجها آخر لعدم إجابة اقتراحهم ( وَلَوْ جَعَلْناهُ ) أي الرسول صلى‌الله‌عليه‌وآله‌وسلم ( مَلَكاً ) منزلا من السماء ( لَجَعَلْناهُ رَجُلاً ) أي في صورة رجل ، فإن خلقة البشر غير مستعدة لرؤية الملك في صورته ، إلا إذا بدّلت صورته إلى صورة إنسان وواقع ملك ، وذلك لا يفيد اقتراحهم ، فإن الملك جرم لطيف لا تراه أعين البشر ، كما لا يرى ( 1) الأنعام : 8. وَلَلَبَسْنا عَلَيْهِمْ ما يَلْبِسُونَ (9) وَلَقَدِ اسْتُهْزِئَ بِرُسُلٍ مِنْ قَبْلِكَ فَحاقَ بِالَّذِينَ سَخِرُوا مِنْهُمْ ما كانُوا بِهِ يَسْتَهْزِؤُنَ (10) قُلْ سِيرُوا فِي الْأَرْضِ ثُمَّ انْظُرُوا كَيْفَ الإنسان الهواء ( وَلَلَبَسْنا ) من اللبس بمعنى الاشتباه ( عَلَيْهِمْ ) أي على هؤلاء المقترحين إنزال الملك ( ما يَلْبِسُونَ ) أي كما يلبسون اليوم على أنفسهم أمر النبي لأنه إنسان مثلهم ، فكان إنزال الملائكة في صورة بشر موجبا لأن نلبس نحن عليهم الأمر ـ مثل لبسهم هذا اليوم ـ وحاصل جواب الاقتراح : أولا : أن الملك لا ينزل إلا لأمور خاصة ، كما نزل في قصة إبراهيم عليه‌السلام ولوط عليه‌السلام . ثانيا : إن الملك إذا نزل ، نزل في صورة بشر ، فيبقى شكّهم على حاله. [11] ثم قال سبحانه على سبيل التسلية للنبي صلى‌الله‌عليه‌وآله‌وسلم : ( وَلَقَدِ اسْتُهْزِئَ بِرُسُلٍ مِنْ قَبْلِكَ ) استهزأت بهم أممهم وسخروا منهم ، فلست أنت بأول رسول يستهزأ بك ويقترح عليك اقتراحات عن عناد وسخرية ( فَحاقَ بِالَّذِينَ سَخِرُوا مِنْهُمْ ) أي : فحلّ وأحاط بالساخرين بالرسل ( ما كانُوا بِهِ يَسْتَهْزِؤُنَ ) أي أحاط بهم العذاب الذي هو جزاء سخريتهم ، أو المراد أن الأنبياء كانوا يتوعدونهم بالعذاب فكانوا يسخرون بوعيدهم ، فحاق بهم العذاب المستهزأ به.` },
            { text: "وَلَوْ جَعَلْنَٰهُ مَلَكًا لَّجَعَلْنَٰهُ رَجُلًا وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُونَ", tafsir: `` },
            { text: "وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ", tafsir: `` },
            { text: "قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ ثُمَّ ٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ", tafsir: `يا رسول الله لهؤلاء الكفار : ( سِيرُوا فِي الْأَرْضِ ) أي سافروا فيها ( ثُمَّ انْظُرُوا ) إذا مررتم ببلدان الأنبياء ، وتفكروا ( كَيْفَ كانَ عاقِبَةُ الْمُكَذِّبِينَ (11) قُلْ لِمَنْ ما فِي السَّماواتِ وَالْأَرْضِ قُلْ لِلَّهِ كَتَبَ عَلى نَفْسِهِ الرَّحْمَةَ لَيَجْمَعَنَّكُمْ إِلى يَوْمِ الْقِيامَةِ لا رَيْبَ فِيهِ كانَ عاقِبَةُ الْمُكَذِّبِينَ ) أي الأمم التي كذبت أنبياءهم ، كيف أبيدت ولم تبق منهم باقية ، فإن ديار الأمم السابقة حوالي سوريا ولبنان والأردن وفلسطين ومصر كانت باقية وآثار الخسف والهلاك على بعضها ، وأخبار الهلاك والتدمير كانت عند الناس مشهورة ، فإذا سافروا وسألوا علموا ذلك ، وكان ذلك سببا لردعهم عن تكذيب الرسول صلى‌الله‌عليه‌وآله‌وسلم والاستهزاء بالقرآن. [13] ثم احتج سبحانه على المكذبين بحجة أخرى فقال : ( قُلْ ) يا رسول الله لهؤلاء المكذبين : ( لِمَنْ ما فِي السَّماواتِ وَالْأَرْضِ ) إذ لا يتمكنون أن يجيبوا بأنها لهم ، ولا أنها لأصنامهم ، وإذ يتحيرون بالجواب ( قُلْ ) أنت : إنما هي كلها ( لِلَّهِ ) فلما ذا تتخذون إلها غيره ؟ وإذ سبق التهديد والوعيد جاء هنا بالتبشير كي تلين القلوب القاسية بالتهديد مرة والتبشير أخرى ( كَتَبَ ) أي أوجب سبحانه ( عَلى نَفْسِهِ الرَّحْمَةَ ) على الخلق واللطف بهم ، وإيجاب ذلك من مقتضيات الحكمة لكي تطلبوا أيها الناس رحمته الواسعة بالإطاعة والامتثال ، لأنه إله الكون وراحمهم في هذه النشأة و ( لَيَجْمَعَنَّكُمْ إِلى يَوْمِ الْقِيامَةِ ) أي جمعا ينتهي إلى ذلك اليوم ، فإن الناس يجتمعون تدريجا لا دفعة ، فكل إنسان يولد فولادته مقدمة للموت الذي ـ بدوره ـ يجمع الناس فردا فردا حتى ينتهي الجمع في يوم القيامة ، فبيده سبحانه المعاد أيضا ( لا رَيْبَ فِيهِ ) أي محل ريب ، وإن ارتاب المبطلون. الَّذِينَ خَسِرُوا أَنْفُسَهُمْ فَهُمْ لا يُؤْمِنُونَ (12) وَلَهُ ما سَكَنَ فِي اللَّيْلِ وَالنَّهارِ وَهُوَ السَّمِيعُ الْعَلِيمُ (13) قُلْ أَ غَيْرَ اللهِ أَتَّخِذُ وَلِيًّا فاطِرِ السَّماواتِ وَالْأَرْضِ وَهُوَ يُطْعِمُ وَلا يُطْعَمُ وإذا كان المبدأ والوسط والمعاد بيده تعالى ف ( الَّذِينَ خَسِرُوا أَنْفُسَهُمْ فَهُمْ لا يُؤْمِنُونَ ) أي أن غير المؤمنين يكونون قد خسروا أنفسهم حيث باعوها واشتروا عوضها العذاب ، بينما باع المؤمنون أنفسهم واشتروا بها الجنة والثواب.` },
            { text: "قُل لِّمَن مَّا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قُل لِّلَّهِ كَتَبَ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ", tafsir: `` },
            { text: "وَلَهُۥ مَا سَكَنَ فِى ٱلَّيْلِ وَٱلنَّهَارِ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ", tafsir: `أي الله سبحانه ( ما سَكَنَ ) وهدأ ( فِي اللَّيْلِ وَالنَّهارِ ) أو المراد ب « ما سكن » مطلق الأشياء الساكنة والمتحركة ، من قولهم : فلان يسكن بلد كذا ، أي يستقر فيه ، فلله كل ما استقر وحلّ في هذين الزمانين « الليل والنهار » ، أما على الثاني فوجه الكلام واضح ، وأما على الأول فلعل التخصيص بالساكن ـ مقابل المتحرك ـ لإلقاء الرهبة في النفس حيث أن الساكن يلقي ظلال الموت الرهيب ، ولذا يرى الإنسان نفسه تهدأ وتسكن إذا صار في محل ساكن لا حسّ فيه ولا حركة ( وَهُوَ السَّمِيعُ ) لأقوال العباد ولكل صوت ( الْعَلِيمُ ) بكل شيء.` },
            { text: "قُلْ أَغَيْرَ ٱللَّهِ أَتَّخِذُ وَلِيًّا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ يُطْعِمُ وَلَا يُطْعَمُ قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَكُونَ أَوَّلَ مَنْ أَسْلَمَ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ", tafsir: `يا رسول الله لهؤلاء الكفار : ( أَ غَيْرَ اللهِ ) أي هل غير الله سبحانه ( أَتَّخِذُ وَلِيًّا ) أي مالكا ومولى وربا ؟! وهو المتصف بكونه ( فاطِرِ السَّماواتِ وَالْأَرْضِ ) أي خالقهما ومبدعهما ومنشئهما ، إنه من السخافة أن يترك الإنسان الخالق ويتمسك بذيل المخلوق ( وَهُوَ ) أي الله سبحانه ( يُطْعِمُ ) فإن الأطعمة والأرزاق من عنده ( وَلا يُطْعَمُ ) أي لا يرزقه أحد ، فهل من المنطق أن يترك الإنسان الخالق الرازق ويتخذ قُلْ إِنِّي أُمِرْتُ أَنْ أَكُونَ أَوَّلَ مَنْ أَسْلَمَ وَلا تَكُونَنَّ مِنَ الْمُشْرِكِينَ (14) قُلْ إِنِّي أَخافُ إِنْ عَصَيْتُ رَبِّي عَذابَ يَوْمٍ عَظِيمٍ (15) مَنْ يُصْرَفْ عَنْهُ يَوْمَئِذٍ فَقَدْ رَحِمَهُ وَذلِكَ المخلوق المرزوق وليا من دون الله ، الذي ليس بيده أي شيء ؟ ( قُلْ ) يا رسول الله هؤلاء الكفار : ( إِنِّي أُمِرْتُ ) أمرني الله ( أَنْ أَكُونَ أَوَّلَ مَنْ أَسْلَمَ ) لله وصدّق بكلماته واتبع أوامره ، وكوني أول من أسلم لعلمي التّام بالخالق سبحانه ، كما قال : « إني أول من يجاهد » ، « وإني أول من يسافر » دلالة لامتلاء النفس بذلك الشيء ( وَ ) أمرني الله بأن ( لا تَكُونَنَ ) التأكيد للنفي ( مِنَ الْمُشْرِكِينَ ) الذين يجعلون مع الله شريكا. والظاهر أن المراد بالشرك أعم ممن يجعل مع الله شريكا مع الاعتقاد به سبحانه ، أو بدون الاعتقاد به ، والمعنى : إني أمرت بالأمرين ، الإسلام ، وعدم الشرك.` },
            { text: "قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ", tafsir: `يا رسول الله لهؤلاء المشركين : ( إِنِّي أَخافُ إِنْ عَصَيْتُ رَبِّي ) بمخالفة أوامره ( عَذابَ يَوْمٍ عَظِيمٍ ) أي عذاب يوم القيامة ، وإنما قال « أخاف » مع أنه متيقن إما من جهة التعبير بالخوف حتى عن المتيقن ، كما يقول من حكم عليه بالإعدام : « إني أخاف الموت » أي أرهبه ، وإما لاحتمال النجاة لأن رحمته وسعت كل شيء ، فمعنى الخوف على هذا الاحتمال رجاء العفو والرحمة.` },
            { text: "مَّن يُصْرَفْ عَنْهُ يَوْمَئِذٍ فَقَدْ رَحِمَهُۥ وَذَٰلِكَ ٱلْفَوْزُ ٱلْمُبِينُ", tafsir: `العذاب ( عَنْهُ يَوْمَئِذٍ ) أي في ذلك اليوم العظيم ( فَقَدْ رَحِمَهُ ) إذ لا أحد ـ باستثناء المعصومين ـ إلا ويكون مستحقا للعذاب ، ولذا كان الصرف عنه بمقتضى الرحمة ( وَذلِكَ ) الصرف ، أو الرحمة الْفَوْزُ الْمُبِينُ (16) وَإِنْ يَمْسَسْكَ اللهُ بِضُرٍّ فَلا كاشِفَ لَهُ إِلاَّ هُوَ وَإِنْ يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (17) وَهُوَ الْقاهِرُ فَوْقَ عِبادِهِ وَهُوَ الْحَكِيمُ الْخَبِيرُ (18) ( الْفَوْزُ ) والفلاح ( الْمُبِينُ ) الواضح الذي لا فوز مثله. [18] ويستطرد السياق بذكر بعض صفاته سبحانه في مقابل المعاندين المنكرين ( وَإِنْ يَمْسَسْكَ اللهُ بِضُرٍّ ) من « مسّ أي أمسك » بما هو ضرر من فقر أو مرض أو ما أشبههما ( فَلا كاشِفَ لَهُ ) أي دافع له ( إِلَّا هُوَ ) فلا أحد مؤثر في الكون ، وإنما العلل تؤثر في المعلولات بإذن الله سبحانه ( وَإِنْ يَمْسَسْكَ بِخَيْرٍ ) غنى أو صحة أو ما أشبههما ( فَهُوَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) إنه القادر المطلق على الخير والشر ، أما من سواه فقدرته من قدرته ، مع أنه ليس له إلا قدرة ناقصة لبعض الأشياء.` },
            { text: "وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ وَإِن يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `` },
            { text: "وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ", tafsir: `تعالى ( الْقاهِرُ ) أي الذي يقهر ويغلب ( فَوْقَ عِبادِهِ ) أي الجميع تحت تسخيره وسيطرته ، لا الفوقية المكانية ، فإنه أجل من الزمان والمكان ( وَهُوَ الْحَكِيمُ ) في أعماله ، فليس كونه قاهرا موجبا للخوف من ظلمه ، كسائر الجبابرة القاهرين ( الْخَبِيرُ ) بما يصدر من العباد ، فلا يأخذ أحدا بجرم أحد كما هو شأن القاهرين من البشر ، حيث يشتبهون كثيرا لجهلهم. [20] في بعض التفاسير : أن أهل مكة أتوا الرسول صلى‌الله‌عليه‌وآله‌وسلم فقالوا : أما وجد الله رسولا غيرك ، ما نرى أحدا يصدقك فيما تقول ، ولقد سألنا عنك اليهود والنصارى فزعموا أنه ليس لك عندهم ذكر ، فأرنا من يشهد قُلْ أَيُّ شَيْءٍ أَكْبَرُ شَهادَةً قُلِ اللهُ شَهِيدٌ بَيْنِي وَبَيْنَكُمْ وَأُوحِيَ إِلَيَّ هذَا الْقُرْآنُ لِأُنْذِرَكُمْ بِهِ وَمَنْ بَلَغَ أَ إِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ اللهِ آلِهَةً أُخْرى أنك رسول الله كما تزعم (1) ، فنزلت هذه الآية : ( قُلْ ) يا رسول الله لهؤلاء الكفار : ( أَيُّ شَيْءٍ أَكْبَرُ شَهادَةً ) أي أعظم من حيث الشهادة ، حتى آتيكم به دليلا على صدقي وصحة نبوتي ، إنهم يتحيرون في الجواب طبعا ، ويفكرون في الناس العظماء بنظرهم ليقولوا : « فلان » ، لكن الرسول صلى‌الله‌عليه‌وآله‌وسلم يقطع تحيرهم وتفكرهم بما علمه الله سبحانه ( قُلْ ) يا رسول الله : ( اللهُ شَهِيدٌ بَيْنِي وَبَيْنَكُمْ ) أي هو شاهد يشهد بصدق نبوتي. وقد مرّ سابقا أن شهادة الله هي إجراء الإعجاز على يده الكريمة ( وَأُوحِيَ إِلَيَّ هذَا الْقُرْآنُ ) أنزله تعالى عليّ ( لِأُنْذِرَكُمْ بِهِ ) أي لأخوفكم بهذا العقاب ، وأخوّف من كفر وعصى ( وَمَنْ بَلَغَ ) عطف على « كم » أي أنذر به من بلغه هذا القرآن إلى يوم القيامة. و روي عن الباقر والصادق عليه‌السلام : أن « من بلغ » معناه : من بلغ أن يكون إماما من آل محمد فهو ينذر بالقرآن كما أنذر به رسول الله (2) . وعليه فهو عطف على الضمير المرفوع في « أنذر » أي أنذر أنا الرسول والأئمة ـ الذين هم مصداق « من بلغ » ـ الناس ( أَ إِنَّكُمْ ) أي : هل إنكم أيها السامعون الكفار ( لَتَشْهَدُونَ أَنَّ مَعَ اللهِ آلِهَةً أُخْرى ) ؟ استفهام إنكاري ، أي : كيف تشهدون بذلك بعد وضوح أدلة التوحيد وقيام ( 1) مجمع البيان : ج 4 ص 22 وتفسير القمي : ج 1 ص 195. ( 2) الكافي : ج 1 ص 416. قُلْ لا أَشْهَدُ قُلْ إِنَّما هُوَ إِلهٌ واحِدٌ وَإِنَّنِي بَرِيءٌ مِمَّا تُشْرِكُونَ (19) الَّذِينَ آتَيْناهُمُ الْكِتابَ يَعْرِفُونَهُ كَما يَعْرِفُونَ أَبْناءَهُمُ الَّذِينَ خَسِرُوا أَنْفُسَهُمْ فَهُمْ لا يُؤْمِنُونَ (20) وَمَنْ أَظْلَمُ مِمَّنِ افْتَرى عَلَى اللهِ كَذِباً الحجة والبرهان على بطلان كل شريك ؟ والمراد الشريك مطلقا ولو كان واحدا ، وذكر « آلهة » من باب المورد ( قُلْ ) أنت يا رسول الله ، إذا لم يعترف أولئك بالتوحيد : ( لا أَشْهَدُ ) أنا بمثل شهادتكم بالشريك ، وإنما أنا لا أعتقد إلا إلها واحدا ( قُلْ ) يا رسول الله : ( إِنَّما هُوَ إِلهٌ واحِدٌ ) لا شريك له ( وَإِنَّنِي بَرِيءٌ مِمَّا تُشْرِكُونَ ) أي من الأوثان التي تشركون بسببها ، وتدخلون أنفسكم في زمرة المشركين من أجلها. [21] ثم ذكر سبحانه أن أهل الكتاب كسائر المشركين يعلمون الحق لكنهم يتجاهلونه ( الَّذِينَ آتَيْناهُمُ ) أي أعطيناهم ( الْكِتابَ ) يراد به جنس الكتاب الأعم من التوراة والإنجيل وغيرهما ( يَعْرِفُونَهُ ) أي يعرفون الرسول ( كَما يَعْرِفُونَ أَبْناءَهُمُ ) فكما يعرف الشخص ابنه بحيث لا يمكن أن يشتبه بغيره ، كذلك لا يشتبه أهل الكتاب بمعرفة الرسول بوصفه ومزاياه الموجودة في كتبهم ( الَّذِينَ خَسِرُوا أَنْفُسَهُمْ ) بأن باعوها بالكفر ، الذي عاقبته ( فَهُمْ لا يُؤْمِنُونَ ) إن عدم الإيمان مترتب على الخسران ، فالخاسر لا يؤمن والرابح يؤمن.` },
            { text: "قُلْ أَىُّ شَىْءٍ أَكْبَرُ شَهَٰدَةً قُلِ ٱللَّهُ شَهِيدٌۢ بَيْنِى وَبَيْنَكُمْ وَأُوحِىَ إِلَىَّ هَٰذَا ٱلْقُرْءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَ أَئِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخْرَىٰ قُل لَّآ أَشْهَدُ قُلْ إِنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ وَإِنَّنِى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ", tafsir: `` },
            { text: "ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمُ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ", tafsir: `` },
            { text: "وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ", tafsir: `أي من يكون أكثر ظلما وتعديا عن الحق ( مِمَّنِ افْتَرى عَلَى اللهِ كَذِباً ) ؟! بأن جعل له شريكا وزعم أن الله أمره بذلك ، كأهل الكتاب وقسم من المشركين الذين كانوا يقولون : إن الله أمرنا باتخاذ أَوْ كَذَّبَ بِآياتِهِ إِنَّهُ لا يُفْلِحُ الظَّالِمُونَ (21) وَيَوْمَ نَحْشُرُهُمْ جَمِيعاً ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا أَيْنَ شُرَكاؤُكُمُ الَّذِينَ كُنْتُمْ تَزْعُمُونَ (22) ثُمَّ لَمْ تَكُنْ فِتْنَتُهُمْ إِلاَّ أَنْ قالُوا وَاللهِ رَبِّنا ما كُنَّا مُشْرِكِينَ (23) الأنداد والشركاء ( أَوْ كَذَّبَ بِآياتِهِ ) كما لو كذب بالقرآن أو بالرسول أو بالمعجزات ، فإنها كلها من آيات الله سبحانه ، لكن الكتاب آية صامتة ، والرسول آية ناطقة ( إِنَّهُ لا يُفْلِحُ الظَّالِمُونَ ) إنهم لا يفوزون بخير الدنيا ، ولا سعادة الآخرة.` },
            { text: "وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوٓا۟ أَيْنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ", tafsir: `اذكر يا رسول الله ( يَوْمَ نَحْشُرُهُمْ جَمِيعاً ) وهو يوم القيامة الذي يجمع فيه هؤلاء المشركون وسائر المكذبين ( ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا ) وجعلوا لله شريكا ( أَيْنَ شُرَكاؤُكُمُ ) أي الشركاء لله الذين زعمتم أنهم كذلك. والإضافة إلى « كم » باعتبار أنهم اتخذوها ، كما تضاف إلى « الله » باعتبار أنه سبحانه المجعول في رديفهم فيقال « شركائي » ( الَّذِينَ كُنْتُمْ تَزْعُمُونَ ) أنهم شركاء الله سبحانه ؟ والاستفهام إنكاري للتوبيخ والتقريع.` },
            { text: "ثُمَّ لَمْ تَكُن فِتْنَتُهُمْ إِلَّآ أَن قَالُوا۟ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ", tafsir: `بعد هذا السؤال منهم ( لَمْ تَكُنْ فِتْنَتُهُمْ ) أي معذرتهم ، فإن الفتنة على معان ، منها : المعذرة ، أو هو على سبيل المجاز ، أي : لم تكن نتيجة فتنتهم بالأصنام ، إلا التبرؤ منها ، كما يقال : « لم يكن درسهم وقضاؤهم إلا رشوة وخيانة » يراد أن عاقبتهما كانت الرشوة والخيانة ( إِلَّا أَنْ قالُوا وَاللهِ رَبِّنا ما كُنَّا مُشْرِكِينَ ) فيحلفون بالله كذبا أنهم ما كانوا مشركين ، كما اعتادوا في الدنيا أن يحلفوا كذبا حينما يقعون في المشاكل. انْظُرْ كَيْفَ كَذَبُوا عَلى أَنْفُسِهِمْ وَضَلَّ عَنْهُمْ ما كانُوا يَفْتَرُونَ (24) وَمِنْهُمْ مَنْ يَسْتَمِعُ إِلَيْكَ وَجَعَلْنا عَلى قُلُوبِهِمْ أَكِنَّةً أَنْ يَفْقَهُوهُ وَفِي آذانِهِمْ وَقْراً وَإِنْ يَرَوْا كُلَّ آيَةٍ لا يُؤْمِنُوا بِها` },
            { text: "ٱنظُرْ كَيْفَ كَذَبُوا۟ عَلَىٰٓ أَنفُسِهِمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ", tafsir: `يا رسول الله إلى حلف هؤلاء ( كَيْفَ كَذَبُوا عَلى أَنْفُسِهِمْ ) بأنهم ما كانوا مشركين ، وهذا أمر يقصد به التعجّب والاستغراب ( وَضَلَّ عَنْهُمْ ما كانُوا يَفْتَرُونَ ) أي ضلت عنهم أوثانهم التي كانوا يعبدونها من دون الله ، ويفترون الكذب على الله بقولهم : هذه شفعاؤنا عند الله ، فلم يجدوها ولم ينتفعوا بها وإنما الأمر لله وحده. [26] قيل : إن نفرا من مشركي مكة جلسوا إلى رسول الله صلى‌الله‌عليه‌وآله‌وسلم وهو يقرأ القرآن ، فقال بعضهم لبعض : ما يقول محمد ؟ قال : أساطير الأولين مثل ما كنت أحدثكم عن القرون الماضية. فنزلت هذه الآية ( وَمِنْهُمْ ) أي من الكفار والمشركين ( مَنْ يَسْتَمِعُ إِلَيْكَ ) أي إلى كلامك يا رسول الله ( وَ ) لكن حيث أنهم أعرضوا عن الحجة بعد ما بيّنت لهم ( جَعَلْنا عَلى قُلُوبِهِمْ أَكِنَّةً ) هي جمع « كنان » وهي ما ستر شيئا ، فإن الإنسان إذا أعرض عن الحق غشيت على قلبه غشاوة ، إذ صار الإعراض له ملكة وعادة ، ونسبته إلى الله سبحانه باعتبار أنه سبحانه هو الذي جعل الإنسان هكذا ، فإنه علة كل شيء ، وإن كان السبب المباشر هو الشخص ( أَنْ يَفْقَهُوهُ ) أي حتى لا يفقهوه بمعنى لا يفهموه ( وَ ) جعلنا ( فِي آذانِهِمْ وَقْراً ) « الوقر » هو الثقل في الأذن ، فهم كمن لا يسمع ، حيث أنهم لا يستفيدون من سماعهم ( وَإِنْ يَرَوْا كُلَّ آيَةٍ ) ومعجزة خارقة على نبوتك وصدقك ( لا يُؤْمِنُوا بِها ) أي بتلك حَتَّى إِذا جاؤُكَ يُجادِلُونَكَ يَقُولُ الَّذِينَ كَفَرُوا إِنْ هذا إِلاَّ أَساطِيرُ الْأَوَّلِينَ (25) وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْأَوْنَ عَنْهُ وَإِنْ يُهْلِكُونَ إِلاَّ أَنْفُسَهُمْ وَما يَشْعُرُونَ (26) وَلَوْ تَرى إِذْ وُقِفُوا عَلَى النَّارِ فَقالُوا يا لَيْتَنا نُرَدُّ وَلا نُكَذِّبَ بِآياتِ رَبِّنا وَنَكُونَ مِنَ الْمُؤْمِنِينَ (27) الآيات ، إذ قد ران على قلوبهم ما كانوا يعملون ( حَتَّى إِذا جاؤُكَ ) لا يطلبون الحق بل ( يُجادِلُونَكَ ) ويناقشونك ( يَقُولُ الَّذِينَ كَفَرُوا إِنْ هذا ) أي ما هذا القرآن ( إِلَّا أَساطِيرُ الْأَوَّلِينَ ) « أساطير » جمع أسطورة ، بمعنى الخرافة ، من سطر إذا كتب ، يعني : ما في القرآن من القصص والأحكام وغيرها ليست إلا أخبار الأقوام السابقة وترّهاتهم.` },
            { text: "وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ", tafsir: `` },
            { text: "وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْـَٔوْنَ عَنْهُ وَإِن يُهْلِكُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ", tafsir: `أي هؤلاء الكفار الذين سبق ذكرهم ( يَنْهَوْنَ عَنْهُ ) أي عن النبي ، أو القرآن ، يعني : ينهون الناس عن اتباع الرسول صلى‌الله‌عليه‌وآله‌وسلم أو القرآن ، ( وَيَنْأَوْنَ ) من «نأى » بمعنى تباعد ، أي يتباعدون ( عَنْهُ ) أي عن الرسول أو القرآن ، فهم يجمعون بين رذيلتي الكفر والأمر بالمنكر ( وَإِنْ ) أي : وما ( يُهْلِكُونَ إِلَّا أَنْفُسَهُمْ ) فإنهم لا يضرون النبي صلى‌الله‌عليه‌وآله‌وسلم بل يضرون أنفسهم بخزي الدنيا وعذاب الآخرة ( وَما يَشْعُرُونَ ) أي لا يعلمون أنهم بذلك يهلكون أنفسهم.` },
            { text: "وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَى ٱلنَّارِ فَقَالُوا۟ يَٰلَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ", tafsir: `يا رسول الله أحوالهم في الآخرة وكيف أنهم يندمون على ما فرّطوا في دار الدنيا ( إِذْ وُقِفُوا عَلَى النَّارِ ) أي أشرفوا واطلعوا ووقفوا على حافتها لدخولها ( فَقالُوا يا لَيْتَنا نُرَدُّ ) أي يرجعوننا إلى الدنيا ( وَلا نُكَذِّبَ بِآياتِ رَبِّنا ) دلائله وبراهينه ( وَنَكُونَ مِنَ الْمُؤْمِنِينَ ) بالله والرسول وما جاء به. وجملتا « لا نكذب » و « نكون » من مدخول التمني ، بَلْ بَدا لَهُمْ ما كانُوا يُخْفُونَ مِنْ قَبْلُ وَلَوْ رُدُّوا لَعادُوا لِما نُهُوا عَنْهُ وَإِنَّهُمْ لَكاذِبُونَ (28) وَقالُوا إِنْ هِيَ إِلاَّ حَياتُنَا الدُّنْيا وَما نَحْنُ بِمَبْعُوثِينَ (29) وَلَوْ تَرى إِذْ وُقِفُوا والتقدير : « يا ليت لنا انتفاء التكذيب ، والكون من المؤمنين » .` },
            { text: "بَلْ بَدَا لَهُم مَّا كَانُوا۟ يُخْفُونَ مِن قَبْلُ وَلَوْ رُدُّوا۟ لَعَادُوا۟ لِمَا نُهُوا۟ عَنْهُ وَإِنَّهُمْ لَكَٰذِبُونَ", tafsir: `أي ظهر لهؤلاء الكفار الحق جليا بحيث لا مجال لإخفائهم له ( ما كانُوا يُخْفُونَ مِنْ قَبْلُ ) في دار الدنيا حيث كانوا يعرفونه كما يعرفون أبناءهم. ولعل وجه الإضراب ب « بل » بيان أنه ليس الأمر على ما قالوه من أنهم : لو ردّوا إلى الدنيا لآمنوا ، فإن التمني الواقع منهم يوم القيامة ليس لأجل كونهم راغبين في الإيمان ، بل لأجل خوفهم من العقاب الذي يعاينوه ( وَلَوْ رُدُّوا ) إلى الدنيا كما تمنوا ( لَعادُوا لِما نُهُوا عَنْهُ ) أي لرجعوا إلى كفرهم وعصيانهم ( وَإِنَّهُمْ لَكاذِبُونَ ) في أنهم لو ردّوا لعملوا صالحا كما في آية أخرى : ( رَبِّ ارْجِعُونِ* لَعَلِّي أَعْمَلُ صالِحاً فِيما تَرَكْتُ ) (1) ، ولا يخفى أن الإنسان إذا كان ذا طبع عنادي لا ينفك عن طبيعته حتى ولو رأى المشاهد العظيمة من عناده كما هو المشاهد المجرّب. [30] وقد كان هؤلاء الكفار ينكرون المعاد وهم في دار الدنيا ( وَقالُوا إِنْ هِيَ ) أي ما هي ( إِلَّا حَياتُنَا الدُّنْيا ) أي الحياة القريبة التي نحن فيها وليس ورائها شيء ( وَما نَحْنُ بِمَبْعُوثِينَ ) بعد الموت. و « البعث » هو الإرسال والإحياء.` },
            { text: "وَقَالُوٓا۟ إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ", tafsir: `` },
            { text: "وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَىٰ رَبِّهِمْ قَالَ أَلَيْسَ هَٰذَا بِٱلْحَقِّ قَالُوا۟ بَلَىٰ وَرَبِّنَا قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ", tafsir: `يا رسول الله أحوال هؤلاء الكفار يوم القيامة ( إِذْ وُقِفُوا ( 1) سورة المؤمنون : 100 و 101. عَلى رَبِّهِمْ قالَ أَ لَيْسَ هذا بِالْحَقِّ قالُوا بَلى وَرَبِّنا قالَ فَذُوقُوا الْعَذابَ بِما كُنْتُمْ تَكْفُرُونَ (30) قَدْ خَسِرَ الَّذِينَ كَذَّبُوا بِلِقاءِ اللهِ حَتَّى إِذا جاءَتْهُمُ السَّاعَةُ بَغْتَةً عَلى رَبِّهِمْ ) أي في معرض خطابه وحسابه ، كالشخص الذي يقف عند الملك وهو مجرم ، فإنه في حال يأس واضطراب ممّا ينطق الملك في حقه من العقاب. ومن المعلوم أن الله لا يرى ، وليس بجسم ، ولا له مكان ، فالمعنى على سبيل المجاز ( قالَ ) ربهم لهم ( أَ لَيْسَ هذا ) اليوم الذي كان يخبر به الأنبياء وكنتم تنكرونه ( بِالْحَقِ ) وهو استفهام توبيخ وتقريع ( قالُوا ) مقرّين مذعنين ( بَلى ) هو حق ( وَرَبِّنا ) وإنما حلفوا خوفا ، فإن الخائف يردف كلامه بالحلف استمالة لقلب المخوف منه وإظهارا بأنه يوافق كلام المتكلم ( قالَ ) الله سبحانه ( فَذُوقُوا الْعَذابَ ) والمراد ب « الذوق » ليس الذائقة اللسانية ، بل ذوق الجسد فإنه يطلق عليهما ( بِما كُنْتُمْ تَكْفُرُونَ ) أي بسبب كفركم ، وكان السؤال للإهانة والإذلال. [32] ثم أخبر سبحانه عن حال هؤلاء الكفار بقوله : ( قَدْ خَسِرَ الَّذِينَ كَذَّبُوا بِلِقاءِ اللهِ ) المراد ( بِلِقاءِ اللهِ ) جزاؤه وعقابه ، كما يقال : فلان لقي عمله ، أي جزاء عمله ، وإلا فليس لله مكان يرى ( حَتَّى إِذا جاءَتْهُمُ السَّاعَةُ ) أي يوم القيامة ( بَغْتَةً ) أي فجأة من « بغت يبغت » بمعنى فاجأ ، وإنما ذكر ذلك لأنهم في دار الدنيا كانوا لا يحسبون حساب يوم القيامة حتى يستعدوا له. وهل المراد ب « الساعة » الموت ـ كما ورد : من مات قامت قيامته (1) ـ حتى يلائم ما بعده ، أم المراد القيامة ويكون المراد ( 1) بحار الأنوار : ج 58 ص 7. قالُوا يا حَسْرَتَنا عَلى ما فَرَّطْنا فِيها وَهُمْ يَحْمِلُونَ أَوْزارَهُمْ عَلى ظُهُورِهِمْ أَلا ساءَ ما يَزِرُونَ (31) وَمَا الْحَياةُ الدُّنْيا إِلاَّ لَعِبٌ وَلَهْوٌ وَلَلدَّارُ الْآخِرَةُ خَيْرٌ لِلَّذِينَ يَتَّقُونَ العذاب الشديد لأن عذاب الآخرة أشد من عذاب القبر ، احتمالان. ( قالُوا ) أي قال هؤلاء الكفار عند معاينة الأهوال والعذاب : ( يا حَسْرَتَنا ) الحسرة شدة الندم يعني : أيتها الحسرة احضري فهذا وقتك ( عَلى ما فَرَّطْنا فِيها ) أي على ما تركنا وضيّعنا في الدنيا من أعمارنا ولم نقدم عملا صالحا ننتفع به في هذا اليوم ( وَهُمْ ) أي هؤلاء الكفار ( يَحْمِلُونَ أَوْزارَهُمْ ) « الوزر » الثقل ، وحيث إن للذنوب ثقلا تسمى أوزارا ( عَلى ظُهُورِهِمْ ) هذا من باب التشبيه ، فكما أن من يحمل ثقلا على ظهره يكون في تعب وحرج ، كذلك من يحمل ذنبا ، ومنه : « عليه دين » ( أَلا ) للتنبيه ( ساءَ ) أي بئس ( ما يَزِرُونَ ) أي ما يحملون من وزر ، بمعنى : إثم وحمل خطأ.` },
            { text: "قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ حَتَّىٰٓ إِذَا جَآءَتْهُمُ ٱلسَّاعَةُ بَغْتَةً قَالُوا۟ يَٰحَسْرَتَنَا عَلَىٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمْ أَلَا سَآءَ مَا يَزِرُونَ", tafsir: `` },
            { text: "وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَعِبٌ وَلَهْوٌ وَلَلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ أَفَلَا تَعْقِلُونَ", tafsir: `أي ليست الحياة القريبة التي اغتر بها الكفار فعملوا لها وتركوا آخرتهم ( إِلَّا لَعِبٌ وَلَهْوٌ ) « اللهو » هو ما يلهي الإنسان عن الجدّ إلى الهزل ، فإن الدنيا ليست إلّا ألعابا وملهيات وإنما كانت كذلك لأنه لا حقيقة لأعمالها فهي فانية زائلة ، وإذا بالإنسان يرى نفسه ولم يحصّل شيئا. وغير خاف أن ذلك بالنسبة إلى الأعمال التي لا تعقب ثمرة صالحة ، وإلّا فالدنيا مزرعة الآخرة. ونعم متجر العقلاء ( وَلَلدَّارُ الْآخِرَةُ ) «اللّام » للتأكيد ، أي أن الدار الثانية التي هي الجنة ونعيمها ( خَيْرٌ لِلَّذِينَ يَتَّقُونَ ) معاصي الله ، وقد جرد « خير » عن معنى التفضيل ، أو بملاحظة أن في الدنيا أيضا خيرا في الجملة ، ثم إنها خير أَفَلا تَعْقِلُونَ (32) قَدْ نَعْلَمُ إِنَّهُ لَيَحْزُنُكَ الَّذِي يَقُولُونَ فَإِنَّهُمْ لا يُكَذِّبُونَكَ للمتقين ، أما غيرهم فالدنيا خير لهم. ولذا ورد : « إن الدنيا سجن المؤمن وجنة الكافر » (1) ( أَ فَلا تَعْقِلُونَ ) أيها البشر ، فإن من عقل وأدرك علم أن الباقي السرمدي الذي لا يشوبه حزن وهمّ خير من الفاني الممزوج بأنواع المصائب والرزايا. [34] ثم سلّى سبحانه نبيه على تكذيبهم إياه وعدم انصياعهم لأوامره وإرشاده بقوله : ( قَدْ نَعْلَمُ ) يا رسول الله ، و « قد » تستعمل في المضارع للتحقيق إلّا أن الغالب أنها فيه للتقليل ( إِنَّهُ لَيَحْزُنُكَ الَّذِي يَقُولُونَ ) مما ينسبونه إليك من أنك شاعر وكاهن ومجنون ، وما أشبه ذلك من السباب والاستهزاء الذي كانوا يكيلونه للرسول صلى‌الله‌عليه‌وآله‌وسلم ( فَإِنَّهُمْ ) أي الكفار ( لا يُكَذِّبُونَكَ ) يا رسول الله في قرارة نفوسهم ، لعلمهم أنك صادق ، وهذا نوع من التسلية إذ الإنسان إذا علم أن عدوه يجلّه في قرارة نفسه ، كان ذلك سلوة له لما علمه من الاحترام الكامن. قالوا التقى الأخنس بن شريف وأبو جهل بن هشام فقال الأخنس : يا أبا الحكم أخبرني عن محمد أصادق هو أم كاذب ؟ فإنه ليس هاهنا أحد غيري وغيرك يسمع كلامنا فقال أبو جهل : ويحك ! والله إن محمدا لصادق وما كذب قط ، ولكن إذا ذهب بنو قصي باللواء والحجابة والسقاية والندوة والنبوة فما ذا يكون لسائر قريش ؟ فنزلت هذه الآية. ( 1) وسائل الشيعة : ج 16 ص 17. وَلكِنَّ الظَّالِمِينَ بِآياتِ اللهِ يَجْحَدُونَ (33) وَلَقَدْ كُذِّبَتْ رُسُلٌ مِنْ قَبْلِكَ فَصَبَرُوا عَلى ما كُذِّبُوا وَأُوذُوا حَتَّى أَتاهُمْ نَصْرُنا وَلا مُبَدِّلَ لِكَلِماتِ اللهِ و روي عن الإمام أمير المؤمنين عليه‌السلام معنى آخر للآية حاصله : « إنهم لا يكذبونك بحجة ولا يتمكنون من إبطال ما جئت به من برهان » (1) . ( وَلكِنَّ الظَّالِمِينَ ) وهم الكفار الذين ظلموا أنفسهم بالكفر ، وغيرهم بالمنع عن الإسلام ( بِآياتِ اللهِ يَجْحَدُونَ ) أي ينكرون آيات الله ، كما قال سبحانه ( وَجَحَدُوا بِها وَاسْتَيْقَنَتْها أَنْفُسُهُمْ ) (2) . [35] ثم ذكر سبحانه تسلية للنبي أنه ليس بأول رسول يكذّب ، بقوله : ( وَلَقَدْ كُذِّبَتْ رُسُلٌ مِنْ قَبْلِكَ ) ليس تنكير « الرسل » لأنه ليس هناك رسول يكذّب ، حتّى ينافي قوله : ( يا حَسْرَةً عَلَى الْعِبادِ ما يَأْتِيهِمْ مِنْ رَسُولٍ إِلَّا كانُوا بِهِ يَسْتَهْزِؤُنَ ) (3) ، المفيد لتكذيب كل رسول ، وإنما الكلام حيث جرى مجرى التسلية كان يكفي ذلك الإلماع إلى أن هذا الجنس أيضا في معرض التكذيب والازدراء ( فَصَبَرُوا عَلى ما كُذِّبُوا ) أي على تكذيب الناس لهم ( وَأُوذُوا ) إما عطف على « كذبوا » أو على « كذبت » ( حَتَّى أَتاهُمْ ) أي جاءهم ( نَصْرُنا ) إياهم على المكذبين ، فاصبر أنت يا رسول الله حتّى يأتيك النّصر ( وَلا مُبَدِّلَ لِكَلِماتِ اللهِ ) أي لا أحد يقدر على تغيير ما أخبر الله به من نصر الرسل ، وإهلاك ( 1) بحار الأنوار : ج 9 ص 86. ( 2) النمل : 15. ( 3) يس : 31. وَلَقَدْ جاءَكَ مِنْ نَبَإِ الْمُرْسَلِينَ (34) أعدائهم ( وَلَقَدْ جاءَكَ ) يا رسول الله ( مِنْ نَبَإِ الْمُرْسَلِينَ ) أي بعض أخبار الرسل السّابقين كيف نصرناهم على أعدائهم. [36] ثمّ بيّن سبحانه أنّ هؤلاء الكفّار لا يؤمنون فلا تتعب نفسك لأجلهم ، ولا تحزن. وهنا نكتة بلاغيّة لا بأس ببيانها ، وهي أنّ الألفاظ والجمل وضعت للمعاني الخاصّة ، لكنّها كثيرا ما تستعمل لإنشاء مفهومها الموضوع له ، لكن يراد غير ذلك ، كما يستعمل الاستفهام والتعجّب بالنّسبة إليه سبحانه ، مع العلم أنه لا يجهل شيئا ، ولا يتعجب من شيء ، وإنما استعمال الاستفهام والتعجب بداعي التحريض أو الردع أو نحوهما ، وهكذا الخطاب الغليظ أو الرقيق لأحد ، قد يراد به المعنى الموضوع له ، وقد يراد به داع آخر يفرغ في مثل هذا القالب ، فإنك إذا أردت تنبيه أحد من جيرانك ، تغلظ لولدك في الخطاب مع أنك لا تريده بالذات ، فمثلا تقول : « لو أنك ألقيت النفاية بباب الدار لحبستك » فإنك لا تريده بل تنشئ هذا الكلام بداعي زجر الجار عن القيام بمثل هذا العمل ، بل قد يكون عمل يستفاد منه شيء ـ حسب المتعارف ـ يأتي به الإنسان لغرض آخر ، كما لو أردت تأديب ولدك لما اقترفه من عمل سيئ ، فإنك تعمل إلى خادمك وترفسه برجلك ـ في هدوء ـ قائلا : لماذا فعلت هذا الفعل ، وإنك لا تريده إطلاقا ، وإنما تريد إفهام ولدك أن هذا العمل له هذا الجزاء. وعلى هذا الوجه جرى الكلام في هذه الآية الكريمة ( وَإِنْ كانَ كَبُرَ ) إنه سبحانه يريد بيان غلظة قلوب الكفار وعنادهم ، لكنه يصوغه في أسلوب خطاب للنبي ، بأنك توسلت بكل الوسائل من الصعود في السماء ، وجعل النفق في الأرض ـ مما يتوسل الناس بهما في مآربهم ـ وَإِنْ كانَ كَبُرَ عَلَيْكَ إِعْراضُهُمْ فَإِنِ اسْتَطَعْتَ أَنْ تَبْتَغِيَ نَفَقاً فِي الْأَرْضِ أَوْ سُلَّماً فِي السَّماءِ فَتَأْتِيَهُمْ بِآيَةٍ وَلَوْ شاءَ اللهُ لَجَمَعَهُمْ عَلَى الْهُدى فَلا تَكُونَنَّ مِنَ الْجاهِلِينَ (35) فإن الكفار لا يؤمنون .. كما أن قصة موسى عليه‌السلام ( وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُ إِلَيْهِ ) (1) ، من هذا القبيل أيضا. ( وَإِنْ كانَ ) يا رسول الله ( كَبُرَ ) أي عظم واشتد ( عَلَيْكَ إِعْراضُهُمْ ) أي إعراض هؤلاء الكفار عن الإسلام ( فَإِنِ اسْتَطَعْتَ ) أي قدرت ( أَنْ تَبْتَغِيَ ) أي تطلب وتتخذ ( نَفَقاً ) أي سربا ( فِي الْأَرْضِ ) تشبيه للمعقول بالمحسوس ، فكما أن من يريد فتح مدينة ، يتخذ الإنفاق من خارج المدينة إلى داخلها ثم يدخلها فجأة ليستولي عليها ، فكذلك إن تمكنت أن تصنع مثل ذلك للسيطرة على أرواح هؤلاء وقلوبهم ( أَوْ ) تبتغي وتطلب ( سُلَّماً ) أي مصعدا ومرقاة ( فِي السَّماءِ ) لتصعد عليه ( فَتَأْتِيَهُمْ بِآيَةٍ ) أي حجة وبرهان ، غير ما أنزلنا عليك. وجواب « إن » محذوف ، أي « فافعل » حذف لدلالة الكلام عليه ، كما تقول : « إن تمكنت أن تتصدق » وتحذف قولك : « فافعل » . ( وَلَوْ شاءَ اللهُ لَجَمَعَهُمْ ) أي الناس ( عَلَى الْهُدى ) بأن يلجئهم إلى قبول الإيمان ، لكنه لا يشاء ذلك لأنه حينئذ يبطل الامتحان والاختبار ( فَلا تَكُونَنَّ مِنَ الْجاهِلِينَ ) فإنّ الجاهل هو الّذي يظنّ أنّ بالإمكان العادي اجتماع النّاس كلّهم على أمر ، أمّا العاقل المجرّب فيعلم أنّه ما من شيء إلا وفيه خلاف وخصام حتّى البديهيّات الأوليّة ( 1) الأعراف : 151. إِنَّما يَسْتَجِيبُ الَّذِينَ يَسْمَعُونَ وَالْمَوْتى يَبْعَثُهُمُ اللهُ ثُمَّ إِلَيْهِ يُرْجَعُونَ (36) كنور الشّمس ، فإنّ السفسطائيين ينكرونه ، ولم يكن النبيّ صلى‌الله‌عليه‌وآله‌وسلم في معرض الجهل حتّى يكون الكلام ردعا له ، وإنما صيغ الكلام لداعي تأنيب الكفّار حتّى أن قصد هدايتهم يكون من أعمال الجاهلين. وهنا سؤال : كيف تقولون في الآيات النازلة بالنسبة إلى النبي صلى‌الله‌عليه‌وآله‌وسلم بمثل هذه المحامل ، ولا تقولون في ما أشبهها من الآيات في غيره صلى‌الله‌عليه‌وآله‌وسلم بمثل ذلك ؟ والجواب : القرينة الخارجية ـ وهي أن النبي معصوم ـ أوجبت ذلك ، كما أن القرينة الخارجية أوجبت حمل « الاستفهام » من الله تعالى على معنى آخر ، بينما الاستفهام من غيره سبحانه يحمل على معناه الحقيقي. [37] إن الذين يستجيبون لك يا رسول الله هم الأحياء الذين لم يمت الضمير في جوفهم ، والذين يكفرون فهم الأموات ، فكما أن الميت لا يسمع ولا ينتفع كذلك هؤلاء ( إِنَّما يَسْتَجِيبُ الَّذِينَ يَسْمَعُونَ ) أي يقبل الإيمان من كان حيا يسمع ( وَالْمَوْتى ) لا سماع لهم حتّى ( يَبْعَثُهُمُ اللهُ ) في الآخرة فيسمعون ، إنهم لا علاج لهم ، يقول الشاعر : لقد أسمعت لو ناديت حيا و لكن لا حياة لمن تنادي ( ثُمَ ) بعد البعث والحساب ( إِلَيْهِ يُرْجَعُونَ ) أي يرجعون إلى حكمه وقضائه ، وهذا لتأكيد أن الكفار أموات ، كقول الإمام وَقالُوا لَوْ لا نُزِّلَ عَلَيْهِ آيَةٌ مِنْ رَبِّهِ قُلْ إِنَّ اللهَ قادِرٌ عَلى أَنْ يُنَزِّلَ آيَةً وَلكِنَّ أَكْثَرَهُمْ لا يَعْلَمُونَ (37) وَما مِنْ دَابَّةٍ فِي الْأَرْضِ علي عليه‌السلام : « يا أشباه الرجال ولا رجال » (1) ، فإن « ولا رجال » لتأكيد الجملة الأولى.` },
            { text: "قَدْ نَعْلَمُ إِنَّهُۥ لَيَحْزُنُكَ ٱلَّذِى يَقُولُونَ فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ", tafsir: `` },
            { text: "وَلَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ فَصَبَرُوا۟ عَلَىٰ مَا كُذِّبُوا۟ وَأُوذُوا۟ حَتَّىٰٓ أَتَىٰهُمْ نَصْرُنَا وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِ وَلَقَدْ جَآءَكَ مِن نَّبَإِى۟ ٱلْمُرْسَلِينَ", tafsir: `` },
            { text: "وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ ٱسْتَطَعْتَ أَن تَبْتَغِىَ نَفَقًا فِى ٱلْأَرْضِ أَوْ سُلَّمًا فِى ٱلسَّمَآءِ فَتَأْتِيَهُم بِـَٔايَةٍ وَلَوْ شَآءَ ٱللَّهُ لَجَمَعَهُمْ عَلَى ٱلْهُدَىٰ فَلَا تَكُونَنَّ مِنَ ٱلْجَٰهِلِينَ", tafsir: `` },
            { text: "إِنَّمَا يَسْتَجِيبُ ٱلَّذِينَ يَسْمَعُونَ وَٱلْمَوْتَىٰ يَبْعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيْهِ يُرْجَعُونَ", tafsir: `` },
            { text: "وَقَالُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ قُلْ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةً وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ", tafsir: `أي قال الكفار : ( لَوْ لا ) أي هلّا ( نُزِّلَ عَلَيْهِ آيَةٌ ) أي معجزة خارقة ( مِنْ رَبِّهِ ) فإنهم بعد ما عجزوا عن مقابلة القرآن قالوا للرسول صلى‌الله‌عليه‌وآله‌وسلم : أنزل علينا مثل عصا موسى وناقة صالح وأشباههما حتى نؤمن بك ، فردهم سبحانه بقوله : ( قُلْ ) يا رسول الله : ( إِنَّ اللهَ قادِرٌ عَلى أَنْ يُنَزِّلَ آيَةً ) كما تقترحون ( وَلكِنَّ أَكْثَرَهُمْ لا يَعْلَمُونَ ) قدرة الله ، بل إنه ليس في إنزالها مصلحة ، فإنهم معاندون والمعاند لا تفيده ألف آية ، كما لم تفد مع فرعون عصا موسى عليه‌السلام ومع قوم صالح عليه‌السلام الناقة ، ولو لم يكن هؤلاء معاندون لكفاهم الكتاب الحكيم. ثمّ إن إتيان آية موسى عليه‌السلام أو ما أشبهها أبعد لقبولهم ، إذ القرآن الذي هو على لسانهم ينسبونه إلى السحر ، فكيف بالعصا التي ليست من مهنتهم ؟! [39] وحيث أن جو هذه السورة حول التوحيد وشؤونه والآيات الكونية وردع الكفّار بمختلف أصنافهم عن عقائدهم الباطلة ، بيّن سبحانه بعض مخلوقاته الدالة على وجوده وصفاته الكمالية بقوله : ( وَما مِنْ دَابَّةٍ فِي الْأَرْضِ ) من « دبّ يدبّ » إذا تحرك ، ثم عمّ كل حيوان ولو لم يتحرك ، ( 1) نهج البلاغة : خطبة 27 ص 92. وَلا طائِرٍ يَطِيرُ بِجَناحَيْهِ إِلاَّ أُمَمٌ أَمْثالُكُمْ ما فَرَّطْنا فِي الْكِتابِ مِنْ شَيْءٍ ثُمَّ إِلى رَبِّهِمْ يُحْشَرُونَ (38) وَالَّذِينَ كَذَّبُوا بِآياتِنا صُمٌّ وَبُكْمٌ كما أنه يشمل حيوانات البر ، لمقابلته بالطائر ، وذكر « في الأرض » للتعميم ، ( وَلا طائِرٍ يَطِيرُ بِجَناحَيْهِ ) كما أن ذكر « يطير بجناحيه » للتعميم أيضا ، والسر أنه كثيرا ما يعبّر بمثل هذا التعبير ويراد به العموم مبالغة ، فإذا جاء القيد أفاد العموم الاستغراقي ( إِلَّا أُمَمٌ أَمْثالُكُمْ ) أيها البشر فإن كل نوع منهما أمة مستقلة وهي مثلكم في الإبداع ولطف الصنع ودقة التركيب ( ما فَرَّطْنا ) أي ما تركنا ( فِي الْكِتابِ ) أي كتاب الكون ، فإن الكون كتاب الله والموجودات كلماته ، وإنما سمّي الكون كتابا ، لأن الكتاب بمعنى الجمع ، من كتب بمعنى جمع ، وهذا الكون قد جمع الأشياء فهو كتاب الله التكويني ( مِنْ شَيْءٍ ) فهذا الكتاب قد اشتمل على جميع الأشياء ومختلف الأصناف ، فهل بعد ذلك يطلب أحد دليلا على وجود الله ؟ ( ثُمَ ) هذه الأمم كلها بعد الممات ( إِلى رَبِّهِمْ يُحْشَرُونَ ) أي يجمعهم يوم القيامة جميعا ، كما قال : ( وَإِذَا الْوُحُوشُ حُشِرَتْ ) (1) ، فمنه سبحانه بدؤها وإليه عودها.` },
            { text: "وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ وَلَا طَٰٓئِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ أَمْثَالُكُم مَّا فَرَّطْنَا فِى ٱلْكِتَٰبِ مِن شَىْءٍ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ", tafsir: `` },
            { text: "وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا صُمٌّ وَبُكْمٌ فِى ٱلظُّلُمَٰتِ مَن يَشَإِ ٱللَّهُ يُضْلِلْهُ وَمَن يَشَأْ يَجْعَلْهُ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ", tafsir: `أي بدلائلنا الدالة على وجودنا وسائر صفاتنا ، بعد هذه الدلائل الواضحة ( صُمٌ ) جمع « أصم » وهو الذي لا يسمع ( وَبُكْمٌ ) جمع « أبكم » وهو الذي لا يتكلم ، فهم كالذي لا يسمع ولا يتكلم حتّى يكتسب العلم ويدركه فإن العلم يأتي من الأذن ويخرج ( 1) التكوير : 6. فِي الظُّلُماتِ مَنْ يَشَأِ اللهُ يُضْلِلْهُ وَمَنْ يَشَأْ يَجْعَلْهُ عَلى صِراطٍ مُسْتَقِيمٍ (39) قُلْ أَ رَأَيْتَكُمْ إِنْ أَتاكُمْ عَذابُ اللهِ أَوْ أَتَتْكُمُ السَّاعَةُ أَ غَيْرَ اللهِ تَدْعُونَ إِنْ كُنْتُمْ صادِقِينَ (40) من اللسان ( فِي الظُّلُماتِ ) فلا يبصر حتّى يرى الأشياء ، فإن الكافر مثل هذا الشخص لأنه قد عطّل جوارحه فلا يدرك شيئا كما لا يدرك الأعمى الأبكم الأصم شيئا ( مَنْ يَشَأِ اللهُ يُضْلِلْهُ ) أي يتركه ولا يجبره على الهداية حتى يضل الطريق وذلك بعد ما بين له الحجة فلم يقبل بل أعرض عنها ـ وقد تقدم معنى ذلك ـ ( وَمَنْ يَشَأْ يَجْعَلْهُ عَلى صِراطٍ مُسْتَقِيمٍ ) باللطف الخفي به ، كما قال سبحانه : ( وَالَّذِينَ اهْتَدَوْا زادَهُمْ هُدىً ) (1) ، ( وَالَّذِينَ جاهَدُوا فِينا لَنَهْدِيَنَّهُمْ سُبُلَنا ) (2) .` },
            { text: "قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ أَوْ أَتَتْكُمُ ٱلسَّاعَةُ أَغَيْرَ ٱللَّهِ تَدْعُونَ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `يا رسول الله لهؤلاء الكفار : ( أَ رَأَيْتَكُمْ ) أي أخبروني ؛ فإن « أ رأيت » بمعنى « أخبر » ، و « كم » للخطاب ، وهو يتغير حسب إفراد المخاطب وتثنيته وجمعه ، كقوله سبحانه : ( أَ رَأَيْتَكَ هذَا الَّذِي كَرَّمْتَ عَلَيَ ) (3) ، ( إِنْ أَتاكُمْ ) أي جاءكم ( عَذابُ اللهِ ) بأن نزلت صاعقة أو خسفت بكم الأرض أو ما أشبههما ـ كما حدث في الأمم السابقة ـ ( أَوْ أَتَتْكُمُ السَّاعَةُ ) أي القيامة بأهوالها وعذابها ( أَ غَيْرَ اللهِ تَدْعُونَ ) لكشف العذاب والأهوال عنكم ( إِنْ كُنْتُمْ صادِقِينَ ) في أن هذه الأصنام آلهة ؟! وهم بفطرتهم يجيبون بالنفي ، وأنهم لا يدعون غير الله ، بل يدعون الله وحده ، وفي ذلك دلالة على بطلان الأصنام وعبادتها. ( 1) محمد : 18. ( 2) العنكبوت : 70. ( 3) الإسراء : 63. بَلْ إِيَّاهُ تَدْعُونَ فَيَكْشِفُ ما تَدْعُونَ إِلَيْهِ إِنْ شاءَ وَتَنْسَوْنَ ما تُشْرِكُونَ (41) وَلَقَدْ أَرْسَلْنا إِلى أُمَمٍ مِنْ قَبْلِكَ فَأَخَذْناهُمْ بِالْبَأْساءِ وَالضَّرَّاءِ لَعَلَّهُمْ يَتَضَرَّعُونَ (42) فَلَوْ لا إِذْ جاءَهُمْ بَأْسُنا تَضَرَّعُوا وَلكِنْ قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ الشَّيْطانُ ما كانُوا يَعْمَلُونَ (43) [42] ولذا قال سبحانه ( بَلْ إِيَّاهُ ) أي الله سبحانه ( تَدْعُونَ ) وتقبلون عليه في شدائدكم ( فَيَكْشِفُ ما تَدْعُونَ إِلَيْهِ ) أي يرفع الضر الذي دعوتموه من أجله ( إِنْ شاءَ ) الكشف عنكم ( وَتَنْسَوْنَ ) في وقت الشدة ( ما تُشْرِكُونَ ) من دون الله. [43] ثم بيّن سبحانه أن الأمم الماضية لما أتتهم الرسل ولم يؤمنوا بهم أصابهم أنواع البلاء ، وأن حال هؤلاء كحال أولئك إن لم يؤمنوا ( وَلَقَدْ أَرْسَلْنا ) رسلنا ( إِلى أُمَمٍ مِنْ قَبْلِكَ ) يا رسول الله فلم يؤمنوا ( فَأَخَذْناهُمْ ) أي أخذنا تلك الأمم ( بِالْبَأْساءِ ) أي الفقر والبؤس ( وَالضَّرَّاءِ ) أي الأوجاع والأسقام ( لَعَلَّهُمْ يَتَضَرَّعُونَ ) أي كي يتضرعوا إلى الله سبحانه ، فإن الإنسان إذا ابتلي بالبلاء كان أقرب إلى الله سبحانه ، وفي ذلك لطف بالنسبة إليه. [44] لكنهم لم يتضرعوا وحتى في هذه الحالة ركبوا العناد وسلكوا سبيل اللّجاج ( فَلَوْ لا ) أي هلّا ـ وهي كلمة توبيخ ـ ( إِذْ جاءَهُمْ ) أي جاء تلك الأمم ( بَأْسُنا تَضَرَّعُوا ) وخضعوا لله ( وَلكِنْ قَسَتْ قُلُوبُهُمْ ) بسبب استمرارهم في الكفر والعصيان فلم تجد الهداية إلى قلوبهم سبيلا ( وَزَيَّنَ لَهُمُ الشَّيْطانُ ما كانُوا يَعْمَلُونَ ) فرأوا أعمالهم فَلَمَّا نَسُوا ما ذُكِّرُوا بِهِ فَتَحْنا عَلَيْهِمْ أَبْوابَ كُلِّ شَيْءٍ حَتَّى إِذا فَرِحُوا بِما أُوتُوا أَخَذْناهُمْ بَغْتَةً فَإِذا هُمْ مُبْلِسُونَ (44) فَقُطِعَ دابِرُ الْقَوْمِ الَّذِينَ ظَلَمُوا وَالْحَمْدُ لِلَّهِ رَبِّ الْعالَمِينَ (45) قُلْ أَرَأَيْتُمْ إِنْ أَخَذَ اللهُ سَمْعَكُمْ وَأَبْصارَكُمْ حسنة ، ولذا لم يتركوها.` },
            { text: "بَلْ إِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَآءَ وَتَنسَوْنَ مَا تُشْرِكُونَ", tafsir: `` },
            { text: "وَلَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَأَخَذْنَٰهُم بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَتَضَرَّعُونَ", tafsir: `` },
            { text: "فَلَوْلَآ إِذْ جَآءَهُم بَأْسُنَا تَضَرَّعُوا۟ وَلَٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ مَا كَانُوا۟ يَعْمَلُونَ", tafsir: `` },
            { text: "فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحْنَا عَلَيْهِمْ أَبْوَٰبَ كُلِّ شَىْءٍ حَتَّىٰٓ إِذَا فَرِحُوا۟ بِمَآ أُوتُوٓا۟ أَخَذْنَٰهُم بَغْتَةً فَإِذَا هُم مُّبْلِسُونَ", tafsir: `أي تركوا ما ذكّرناهم من أوامرنا ولم يعملوا بما دعاهم الرسل إليه ( فَتَحْنا عَلَيْهِمْ أَبْوابَ كُلِّ شَيْءٍ ) من النّعم حيث قد أقبلت الدنيا عليهم من جميع النواحي بعد تلك البأساء والضراء. وذلك لأجل احتمال إفادة التذكير بالنعم حتى يشكروا بارئها والمتفضل بها عليهم ( حَتَّى إِذا فَرِحُوا بِما أُوتُوا ) أي بما أعطاهم الله من النعم واشتغلوا بالتلذذ ولم يقبلوا أمر الرسل ، بل صار ذلك سببا لزيادة طغيانهم وكفرهم ( أَخَذْناهُمْ ) بالهلاك والنكال ( بَغْتَةً ) أي فجأة ( فَإِذا هُمْ مُبْلِسُونَ ) من « بلس » إذا تحسّر ، أي أنهم متحيّرون آيسون من النجاة.` },
            { text: "فَقُطِعَ دَابِرُ ٱلْقَوْمِ ٱلَّذِينَ ظَلَمُوا۟ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ", tafsir: `« الدابر » الأصل ، أي استؤصل وقطع أصل القوم بسبب العذاب ( وَالْحَمْدُ لِلَّهِ رَبِّ الْعالَمِينَ ) الذي أهلك الكفار وأراح البلاد والعباد منهم. [47] ثم احتج الله على الكفار بحجة أخرى تدل على بطلان أصنامهم وأن الأمر لله وحده ( قُلْ ) يا رسول الله لهؤلاء الكفار الذين يشركون بالله سبحانه : ( أَ رَأَيْتُمْ ) أي أخبروني ، فقد تقدم أن « أ رأيت » بمعنى أخبرني ( إِنْ أَخَذَ اللهُ سَمْعَكُمْ وَأَبْصارَكُمْ ) أي أذهب بها فصرتم صمّ وعمي وَخَتَمَ عَلى قُلُوبِكُمْ مَنْ إِلهٌ غَيْرُ اللهِ يَأْتِيكُمْ بِهِ انْظُرْ كَيْفَ نُصَرِّفُ الْآياتِ ثُمَّ هُمْ يَصْدِفُونَ (46) قُلْ أَ رَأَيْتَكُمْ إِنْ أَتاكُمْ عَذابُ اللهِ بَغْتَةً أَوْ جَهْرَةً هَلْ يُهْلَكُ إِلاَّ الْقَوْمُ الظَّالِمُونَ (47) وَما نُرْسِلُ الْمُرْسَلِينَ إِلاَّ مُبَشِّرِينَ ( وَخَتَمَ عَلى قُلُوبِكُمْ ) أي سلب عقولكم حتى صرتم لا تعقلون ، أو المراد الطبع عليها حتى تبتعد عن الخير ( مَنْ إِلهٌ غَيْرُ اللهِ يَأْتِيكُمْ بِهِ ) أي بذلك الشيء المأخوذ منكم ، فإنهم يعترفون بأن الأصنام لا تتمكن من إعادة الأشياء المذكورة ( انْظُرْ ) يا رسول الله ( كَيْفَ نُصَرِّفُ الْآياتِ ) أي نبيّن لهم في القرآن الآيات الدالة على التوحيد ، و « تصريف الآيات » توجيهها ، من « صرف » إذا أرسل ( ثُمَّ هُمْ يَصْدِفُونَ ) من « صدف » بمعنى أعرض ، أي يعرضون عن الحق وعن القائل في الآيات.` },
            { text: "قُلْ أَرَءَيْتُمْ إِنْ أَخَذَ ٱللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِهِ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَٰتِ ثُمَّ هُمْ يَصْدِفُونَ", tafsir: `` },
            { text: "قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ بَغْتَةً أَوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلظَّٰلِمُونَ", tafsir: `يا رسول الله لهؤلاء الكفار : ( أَ رَأَيْتَكُمْ ) أي أخبروني ( إِنْ أَتاكُمْ عَذابُ اللهِ ) بعد ما أنذرتكم ولم تؤمنوا ( بَغْتَةً ) أو مفاجأة خفية ، فإن الفجأة تلازم الخفية ( أَوْ جَهْرَةً ) علانية بلا فجأة ( هَلْ يُهْلَكُ إِلَّا الْقَوْمُ الظَّالِمُونَ ) الكافرون الذين ظلموا أنفسهم ، والعاصون ، والمراد بالهلاك ما يسبب خسارة الدارين ، أما المؤمن لو هلك ، فإنه لا يخسر إلّا الدنيا ، ويعوّض عنها بأنواع الإنعام ، وفي هذا الاستفهام إيقاظ وتنبيه وردع لهم من الظلم ، فأي أحد يجب أن يهلك إذا أتى العذاب.` },
            { text: "وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ فَمَنْ ءَامَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", tafsir: `بالجنة والثّواب لمن آمن وأصلح وَمُنْذِرِينَ فَمَنْ آمَنَ وَأَصْلَحَ فَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (48) وَالَّذِينَ كَذَّبُوا بِآياتِنا يَمَسُّهُمُ الْعَذابُ بِما كانُوا يَفْسُقُونَ (49) ( وَمُنْذِرِينَ ) بالنار والعقاب لمن كفر أو عصى ( فَمَنْ آمَنَ ) بما أمر الله الإيمان به ( وَأَصْلَحَ ) أعماله ( فَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ) لا في الدنيا ولا في الآخرة ، أما في الآخرة فواضح ، وأما في الدنيا فلأن الخوف والحزن الحقيقيين ما كانا مع الانقطاع عن العوض والثواب وما أشبهها ، وليس المؤمن كذلك فإنه يعلم أن ما يصيبه يعقبه الثواب والأجر. ولذا قال الإمام الحسين عليه‌السلام يوم عاشوراء : « هوّن عليّ ما نزل بي أنه بعين الله » (1) ، والارتباط بين هذه الآية والآية السابقة واضح فإن العذاب لما وعد به الكفار بيّن أن الرسل شأنهم التبشير والإنذار.` },
            { text: "وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا يَمَسُّهُمُ ٱلْعَذَابُ بِمَا كَانُوا۟ يَفْسُقُونَ", tafsir: `أي يصيبهم العذاب ( بِما كانُوا يَفْسُقُونَ ) أي بسبب فسقهم وخروجهم من طاعة الله سبحانه. ثم لا يخفى أن الغالب تفسير الآيات الدالة على العذاب بعذاب الآخرة ، مع أن الإطلاق خلاف ذلك ، فإن من أعرض عن ذكره سبحانه يصيبه العذاب في الدنيا وفي الآخرة ، كما قال سبحانه : ( وَمَنْ أَعْرَضَ عَنْ ذِكْرِي فَإِنَّ لَهُ مَعِيشَةً ضَنْكاً ) (2) ، وسببه واضح فإن المناهج التي يتبعها الإنسان مما وضعها غير الله سبحانه لا بد وأن تكون منحرفة ، وهذا الانحراف يسبب الفوضى والاستبداد وما أشبه ، ( 1) بحار الأنوار : ج 45 ص 45. ( 2) طه : 125. قُلْ لا أَقُولُ لَكُمْ عِنْدِي خَزائِنُ اللهِ وَلا أَعْلَمُ الْغَيْبَ وَلا أَقُولُ لَكُمْ إِنِّي مَلَكٌ إِنْ أَتَّبِعُ إِلاَّ ما يُوحى إِلَيَّ قُلْ مما يؤذي الإنسان وينغّص عيشه. [51] إن الكفار كانوا يستعظمون كيف يمكن أن يكون الإنسان رسولا بدون أن يكون له مال عريض أو علم غيب ذاتي يعينه في أموره وحوائجه ، ويردّ الله سبحانه عليهم ذلك ، بأن الرسالة لا ترتبط بهذه الأمور ، وإنما هي هداية ونور ( قُلْ ) يا رسول الله : ( لا أَقُولُ لَكُمْ ) أيها الناس ( عِنْدِي خَزائِنُ اللهِ ) التي يهب منها لمن يشاء ما يشاء. ومن المعلوم أنه ليس لله سبحانه خزائن بالمعنى المتعارف لدينا ، بل خزائنه الأرض والشمس والمعادن وما أشبه ، مما تفيض ثروة ومالا. و في الحديث القدسي : « إنما خزائني إذا أردت شيئا أن أقول له كن فيكون » (1) . والمراد ب « عدم القول » عدم الوجود ، فهو من السالبة بانتفاء الموضوع ( وَلا ) أقول ( أَعْلَمُ الْغَيْبَ ) كما يعلم الله سبحانه ، بل إنما أعلم بما يوحي إليّ بإذن الله سبحانه ، كما قال عيسى عليه‌السلام : ( وَأُنَبِّئُكُمْ بِما تَأْكُلُونَ وَما تَدَّخِرُونَ فِي بُيُوتِكُمْ ) (2) ، وفي الآية الكريمة : ( فَلا يُظْهِرُ عَلى غَيْبِهِ أَحَداً* إِلَّا مَنِ ارْتَضى مِنْ رَسُولٍ ) (3) ، ( وَلا أَقُولُ لَكُمْ إِنِّي مَلَكٌ ) كما أنكم تتوقعون أن يكون الرسول ملكا ( إِنْ أَتَّبِعُ ) أي ليس لي شأن إلّا أن أتبع ، و « إن » بمعنى « ما » ( إِلَّا ما يُوحى إِلَيَ ) من الأوامر والنواهي لأجل الإرشاد والإصلاح ( قُلْ ) يا رسول الله لهم : إن مثل المؤمن والكافر كمثل البصير الذي يبصر الأشياء ( 1) بحار الأنوار : ج 4 ص 135. ( 2) آل عمران : 50. ( 3) الجن : 27 و 28. هَلْ يَسْتَوِي الْأَعْمى وَالْبَصِيرُ أَ فَلا تَتَفَكَّرُونَ (50) وَأَنْذِرْ بِهِ الَّذِينَ يَخافُونَ أَنْ يُحْشَرُوا إِلى رَبِّهِمْ لَيْسَ لَهُمْ مِنْ دُونِهِ وَلِيٌّ وَلا شَفِيعٌ لَعَلَّهُمْ يَتَّقُونَ (51) وَلا تَطْرُدِ الَّذِينَ يَدْعُونَ والأعمى الذي لا يبصر ( هَلْ يَسْتَوِي الْأَعْمى وَالْبَصِيرُ ) ؟ كلّا ، إن كل أحد يعلم بأنهما ليسا متساويين. ولعل تقديم الأعمى لأن الخطاب كان مع الكفار الذين هم بمنزلة الأعمى ( أَ فَلا تَتَفَكَّرُونَ ) في الأمر وأن مقام الرسالة لا يرتبط بما ذكرتم من الأشياء.` },
            { text: "قُل لَّآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ لَكُمْ إِنِّى مَلَكٌ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ أَفَلَا تَتَفَكَّرُونَ", tafsir: `` },
            { text: "وَأَنذِرْ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحْشَرُوٓا۟ إِلَىٰ رَبِّهِمْ لَيْسَ لَهُم مِّن دُونِهِۦ وَلِىٌّ وَلَا شَفِيعٌ لَّعَلَّهُمْ يَتَّقُونَ", tafsir: `يا رسول الله ( بِهِ ) أي بالقرآن ، فإنه قد تقدّم ذكره بلفظ « ما يوحى إليّ » ( الَّذِينَ يَخافُونَ أَنْ يُحْشَرُوا إِلى رَبِّهِمْ ) والخوف هنا ليس بمعنى الاحتمال ، كقولك : « أخاف أن يهدم البناء » ، بل بمعنى الخوف القطعي ، فهو كقولك : « أخاف من الجلاد » وهو يريد القتل. والمراد ب « الذين يخافون » المعترفون بالبعث ، وإنما قد أنذر هؤلاء مع أن الإنذار عام ، لأن هؤلاء هم المنتفعون بالإنذار ، أما من أعرض فلا ينتفع به ( لَيْسَ لَهُمْ مِنْ دُونِهِ ) أي من دون الله تعالى ( وَلِيٌ ) يلي أمورهم هناك ( وَلا شَفِيعٌ ) وليس المراد أن الله يشفع إذ لا معنى لشفاعته ، بل المراد أن الشفاعة بيده ، فلا يشفع أحد إلّا بإذنه ، كما قال سبحانه : ( لا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضى ) (1) ، ( لَعَلَّهُمْ ) أي هؤلاء الذين أنذرتهم ( يَتَّقُونَ ) معاصي الله ، ويأتمرون بأوامره. [53] إن من يخاف الحساب ، أنذره يا رسول الله ولا تطرده من عندك وإن طلب الأشراف ذلك ( وَلا تَطْرُدِ ) من مجلسك ( الَّذِينَ يَدْعُونَ ( 1) الأنبياء : 29. رَبَّهُمْ بِالْغَداةِ وَالْعَشِيِّ يُرِيدُونَ وَجْهَهُ ما عَلَيْكَ مِنْ حِسابِهِمْ مِنْ شَيْءٍ وَما مِنْ حِسابِكَ عَلَيْهِمْ مِنْ شَيْءٍ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ الظَّالِمِينَ (52) وَكَذلِكَ فَتَنَّا بَعْضَهُمْ بِبَعْضٍ رَبَّهُمْ بِالْغَداةِ ) أي صباحا ( وَالْعَشِيِ ) طرف العصر ( يُرِيدُونَ ) بالدعاء والضراعة ( وَجْهَهُ ) أي ذاته سبحانه خالصا مخلصا. وقد ورد أنه مرّ ملأ من قريش على رسول الله صلى‌الله‌عليه‌وآله‌وسلم وعنده صهيب وخباب وبلال وعمار وسلمان وغيرهم من ضعفاء المسلمين فقالوا : يا محمد أرضيت بهؤلاء من قومك ؟ أ فنحن نكون تبعا لهم ؟ أ هؤلاء الذين منّ الله عليهم ؟ اطردهم عنك فلعلّك إن طردتهم تبعناك. فنزلت الآية. وفي بعض التفاسير أنه طعن أولئك الأشراف في سيرة هؤلاء الفقراء وأعمالهم ، كي يدفعوا الرسول صلى‌الله‌عليه‌وآله‌وسلم لإبعادهم عنه ، فرد عليهم سبحانه بقوله : ( ما عَلَيْكَ ) أي ليس عليك ( مِنْ حِسابِهِمْ مِنْ شَيْءٍ ) فأنت لا تتحمل تبعة سيرتهم ( وَما مِنْ حِسابِكَ ) يا رسول الله ( عَلَيْهِمْ مِنْ شَيْءٍ ) فإنهم لا يطالبون بحسابك ، بل كلّ وعمله ، فسيرتهم لو كانت كما يقولون لا تضرك ( فَتَطْرُدَهُمْ ) فإن الشخص إنما يطرد من تضره سيرته ، أما من كان قلبه عامرا بالإيمان وصلاته دائمة طرفي النهار فإن فقره وسيرته لا يوجبان طرده ـ لو فرض أن في سيرته ميل ـ ( فَتَكُونَ ) بسبب طردهم ( مِنَ الظَّالِمِينَ ) لهم ، أو لنفسك ، فإن الإنسان إذا ظلم غيره فقد ظلم نفسه أيضا ، وسيقت هذه الجملة مبالغة في ردع من طلب طرد أولئك.` },
            { text: "وَلَا تَطْرُدِ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَىْءٍ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ ٱلظَّٰلِمِينَ", tafsir: `` },
            { text: "وَكَذَٰلِكَ فَتَنَّا بَعْضَهُم بِبَعْضٍ لِّيَقُولُوٓا۟ أَهَٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيْهِم مِّنۢ بَيْنِنَآ أَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِٱلشَّٰكِرِينَ", tafsir: `أي هكذا ( فَتَنَّا ) أي ابتلينا ( بَعْضَهُمْ بِبَعْضٍ ) حيث ابتلينا لِيَقُولُوا أَ هؤُلاءِ مَنَّ اللهُ عَلَيْهِمْ مِنْ بَيْنِنا أَ لَيْسَ اللهُ بِأَعْلَمَ بِالشَّاكِرِينَ (53) وَإِذا جاءَكَ الَّذِينَ يُؤْمِنُونَ بِآياتِنا فَقُلْ سَلامٌ عَلَيْكُمْ كَتَبَ رَبُّكُمْ عَلى نَفْسِهِ الرَّحْمَةَ أَنَّهُ مَنْ عَمِلَ مِنْكُمْ سُوءاً بِجَهالَةٍ الأشراف والفقراء ( لِيَقُولُوا ) أولئك الأشراف : ( أَ هؤُلاءِ ) أي هل هؤلاء الفقراء ( مَنَّ اللهُ عَلَيْهِمْ مِنْ بَيْنِنا ) حتى عمّهم النبي بلطفه ، وجعلهم ندماءه وموضع سره ؟ نعم ، ليس الإسلام ينظر للناس كما ينظر أهل الدنيا ( أَ لَيْسَ اللهُ بِأَعْلَمَ بِالشَّاكِرِينَ ) أنهم شاكرون ، والشاكر أفضل من غيره عند الإسلام ، وإن كان غيره في نظر الناس شريفا ، فإن الميزان عند الإسلام التقوى ( إِنَّ أَكْرَمَكُمْ عِنْدَ اللهِ أَتْقاكُمْ ) (1) . [55] والإسلام لا يسد الأبواب على العاصي ، وإنما يفتح له باب التوبة. وقد ورد أن جماعة جاءوا إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم فقالوا : إنا أصبنا ذنوبا عظاما ، فلم يرد عليهم شيئا فانصرفوا ، فنزل قوله تعالى ( وَإِذا جاءَكَ ) يا رسول الله ( الَّذِينَ يُؤْمِنُونَ بِآياتِنا ) أي بدلائلنا وبراهيننا ( فَقُلْ ) لهم : ( سَلامٌ عَلَيْكُمْ ) أي أنتم في سلام لا في عذاب وعقاب ، يقبل عذركم ويغفر ذنبكم ( كَتَبَ رَبُّكُمْ عَلى نَفْسِهِ الرَّحْمَةَ ) أي أنه فرض على نفسه ـ حسب حكمته ـ أن يرحم العباد ويشملهم بلطفه وإحسانه ( أَنَّهُ مَنْ عَمِلَ مِنْكُمْ سُوءاً بِجَهالَةٍ ) والمراد بالجهالة هنا ليس الجهل مقابل العلم ، بل عدم المبالاة ، وإنما سمي بذلك لأن العالم التارك ( 1) الحجرات : 14. ثُمَّ تابَ مِنْ بَعْدِهِ وَأَصْلَحَ فَأَنَّهُ غَفُورٌ رَحِيمٌ (54) وَكَذلِكَ نُفَصِّلُ الْآياتِ وَلِتَسْتَبِينَ سَبِيلُ الْمُجْرِمِينَ (55) قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِنْ دُونِ اللهِ قُلْ لا أَتَّبِعُ أَهْواءَكُمْ قَدْ ضَلَلْتُ إِذاً لعلمه هو والجاهل سواء ، وكأنه للجهل بالنتائج والعواقب المرتبة على العمل ، وإلا فالآية تشمل العمل ، بل هو موردها. ( ثُمَّ تابَ مِنْ بَعْدِهِ ) أي بعد العمل ( وَأَصْلَحَ ) أي عمل صالحا ( فَأَنَّهُ ) أي الله سبحانه ( غَفُورٌ ) لذنبه ( رَحِيمٌ ) به. وكان الإتيان ب « رحيم » بعد « غفور » غالبا ، لإفادة الفضل في لطفه وإحسانه.` },
            { text: "وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤْمِنُونَ بِـَٔايَٰتِنَا فَقُلْ سَلَٰمٌ عَلَيْكُمْ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءًۢا بِجَهَٰلَةٍ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَأَنَّهُۥ غَفُورٌ رَّحِيمٌ", tafsir: `` },
            { text: "وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ وَلِتَسْتَبِينَ سَبِيلُ ٱلْمُجْرِمِينَ", tafsir: `أي كما سبق نفصل الأدلة والبراهين الدالة على التوحيد وسائر شؤون المبدأ والمعاد ، ونشرحها ونبيّنها ، حتى يتضح سبيل المهتدين ( وَلِتَسْتَبِينَ ) أي تظهر ( سَبِيلُ الْمُجْرِمِينَ ) المعاندين ، فإن في بيان الحق وضوح الأمرين ؛ سبيل المحق وسبيل المبطل. ولفظة « سبيل » مما يجوز التذكير والتأنيث ، ولذا قال : «تستبين » بالتأنيث. [57] ثم أمر سبحانه رسوله بالبراءة مما يعبد المشركون بقوله : ( قُلْ ) يا رسول الله لهؤلاء المشركين : ( إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِنْ دُونِ اللهِ ) يعني الأصنام التي كانوا يعبدونها ، والمراد ب « من دون الله » ما خلا عبادة الله ، فإن النهي أعم من عبادة الأصنام وحدها أو بالاشتراك مع عبادة الله ، فإن عبادة الأصنام إنما أتت من هوى النفس لا من دليل عقلي أو منطقي ( قُلْ ) يا رسول الله لهم : ( لا أَتَّبِعُ أَهْواءَكُمْ ) في عبادة الأصنام ( قَدْ ضَلَلْتُ إِذاً ) إذا فعلت أنا ذلك وَما أَنَا مِنَ الْمُهْتَدِينَ (56) قُلْ إِنِّي عَلى بَيِّنَةٍ مِنْ رَبِّي وَكَذَّبْتُمْ بِهِ ما عِنْدِي ما تَسْتَعْجِلُونَ بِهِ إِنِ الْحُكْمُ إِلاَّ لِلَّهِ يَقُصُّ الْحَقَّ وَهُوَ خَيْرُ الْفاصِلِينَ (57) قُلْ لَوْ أَنَّ عِنْدِي ما تَسْتَعْجِلُونَ بِهِ ( وَما أَنَا مِنَ الْمُهْتَدِينَ ) لو عبدت الأصنام.` },
            { text: "قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ قُل لَّآ أَتَّبِعُ أَهْوَآءَكُمْ قَدْ ضَلَلْتُ إِذًا وَمَآ أَنَا۠ مِنَ ٱلْمُهْتَدِينَ", tafsir: `` },
            { text: "قُلْ إِنِّى عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَكَذَّبْتُم بِهِۦ مَا عِندِى مَا تَسْتَعْجِلُونَ بِهِۦٓ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ يَقُصُّ ٱلْحَقَّ وَهُوَ خَيْرُ ٱلْفَٰصِلِينَ", tafsir: `يا رسول الله لهؤلاء الكفار : ( إِنِّي عَلى بَيِّنَةٍ ) أي أمر واضح بيّن لا غموض فيه ( مِنْ رَبِّي ) أي أن تلك البينّة أتتني من جانب الله سبحانه ، لا مثلكم أتبع هوى النفس ( وَكَذَّبْتُمْ بِهِ ) أي بما أنا عليه من الدليل والبيّنة ، وقد كان الكفّار يطلبون من الرسول ـ استهزاء ـ أن ينزل عليهم العذاب الذي يعدهم ، كما قال سبحانه : ( وَيَسْتَعْجِلُونَكَ بِالْعَذابِ ) (1) ، فرد عليهم بقوله : ( ما عِنْدِي ) أي ليس باختياري وأمري ( ما تَسْتَعْجِلُونَ بِهِ ) أي الذي تطلبون سرعته ( إِنِ الْحُكْمُ ) أي ليس الحكم في باب العذاب ( إِلَّا لِلَّهِ ) فهو وحده ( يَقُصُّ الْحَقَ ) أي يبيّنه ( وَهُوَ خَيْرُ الْفاصِلِينَ ) الذي يفصّل الأمور ، فإذا اقتضت المصلحة أتاكم بالعذاب ويفصل الأمر وتنتهي المشكلة ، ومن المعلوم أن إنزال العذاب له مقاييس خاصة ، وأوقات محددة ، فليس كل من طلب العذاب يجاب فورا وإن كان من أكثر الناس إجراما.` },
            { text: "قُل لَّوْ أَنَّ عِندِى مَا تَسْتَعْجِلُونَ بِهِۦ لَقُضِىَ ٱلْأَمْرُ بَيْنِى وَبَيْنَكُمْ وَٱللَّهُ أَعْلَمُ بِٱلظَّٰلِمِينَ", tafsir: `يا رسول الله لهؤلاء الكفار الذين يطلبون سرعة العذاب ( لَوْ أَنَّ عِنْدِي ) أي بأمري وإرادتي ( ما تَسْتَعْجِلُونَ بِهِ ) من إنزال العذاب ( 1) الحج : 48. لَقُضِيَ الْأَمْرُ بَيْنِي وَبَيْنَكُمْ وَاللهُ أَعْلَمُ بِالظَّالِمِينَ (58) وَعِنْدَهُ مَفاتِحُ الْغَيْبِ لا يَعْلَمُها إِلاَّ هُوَ وَيَعْلَمُ ما فِي الْبَرِّ بكم ( لَقُضِيَ الْأَمْرُ بَيْنِي وَبَيْنَكُمْ ) إذ أهلككم فأستريح منكم ، لكن ذلك بإذن الله ومشيئته ( وَاللهُ أَعْلَمُ بِالظَّالِمِينَ ) وبمقتضى عمله يقدم العذاب تارة ويؤخره أخرى. [60] وحيث ذكر علمه سبحانه بالظالمين يأتي السياق ليذكر الكافرين بعلمه سبحانه وقدرته وأعماله ، في أنفسهم وفي الآفاق ، إنها أقوى الأدلة على وجوده وسائر صفاته الكلامية ، وهل من حاجة بعدها إلى الخوارق التي كانوا يقترحونها لإثبات كلامه صلى‌الله‌عليه‌وآله‌وسلم ( وَعِنْدَهُ ) أي عند الله سبحانه ( مَفاتِحُ ) جمع « مفتح » بمعنى المفتاح ( الْغَيْبِ ) أي ما غاب عن الحواس والمشاعر ، فكأن الغيب قد سدّت أبوابه وأقفلت فلا يتمكن الإنسان أن يرى ما ورائها ، وليس بيد أحد مفاتيح تلك الأبواب ليفتحها ويرى الغيب ، وإنما هي بيد الله سبحانه وحده ، فهو الذي يعلم الغيب كله ويتمكن أن يفتح تلك الأبواب لمن أراد من خلقه ، كما قال : ( فَلا يُظْهِرُ عَلى غَيْبِهِ أَحَداً* إِلَّا مَنِ ارْتَضى مِنْ رَسُولٍ ) (1) ، ( لا يَعْلَمُها ) أي لا يدري ما هي تلك المفاتيح ( إِلَّا هُوَ ) أي إلّا الله سبحانه ، وحيث أن كشف الغيب يحتاج إلى العلم بالكشف والقدرة على الكشف ، وكان المقام مقام بيان عمله سبحانه ، قال سبحانه « لا يعلمها » فلا يقال أن الأنسب أن يقول : « لا يقدر عليها » لا أن يقول « لا يعلمها » . فالأرزاق والآجال وما أشبههما ، التي تأتي في المستقبل ، لا يعلمها إلّا الله سبحانه ( وَيَعْلَمُ ما فِي الْبَرِّ ( 1) الجن : 27 و 28. وَالْبَحْرِ وَما تَسْقُطُ مِنْ وَرَقَةٍ إِلاَّ يَعْلَمُها وَلا حَبَّةٍ فِي ظُلُماتِ الْأَرْضِ وَلا رَطْبٍ وَلا يابِسٍ إِلاَّ فِي كِتابٍ مُبِينٍ (59) وَهُوَ الَّذِي يَتَوَفَّاكُمْ بِاللَّيْلِ وَالْبَحْرِ ) المراد بالبر : الأعم من المدن ، والبحر : الأعم من الأنهار ، بقرينة المقابلة ( وَما تَسْقُطُ مِنْ وَرَقَةٍ ) من أوراق الأشجار ( إِلَّا يَعْلَمُها ) ، ( وَلا ) من ( حَبَّةٍ ) كامنة ( فِي ظُلُماتِ الْأَرْضِ ) أي جوفها ، أو لا تسقط حبة في باطن الأرض مما تزرع أو غيره. وقد كان التقابل بين « ما تسقط من ورقة » وبين « ولا حبة » لطيفا جدا ، حيث أن الأول حركة الحياة إلى الموت ، والسقوط الثاني حركة الموت إلى الحياة والارتفاع ( وَلا ) من ( رَطْبٍ وَلا يابِسٍ ) من جميع الأشياء والأصناف. وهذا وإن كان أخص من الموجودات ، لأن من الأشياء ما لا يتصف برطوبة لا يبوسة كالعقل ، إلّا أن العموم يشمله الفحوى ، وكثيرا ما يقال اللفظ الأخص ويراد الأعم حيث أن الأخص صار مثلا ، كقوله : ( إِنْ تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً ) (1) ، فإن الأكثر داخل بالفحوى ( إِلَّا فِي كِتابٍ مُبِينٍ ) أي إن جميع الأشياء محفوظة عند الله سبحانه في كتاب واضح جليّ ، وهو اللّوح المحفوظ ، أو المراد بالكتاب علمه الشامل. ولعلّ التعبير بالكتاب لأجل بيان أنه محفوظ لا يزول ، كما أن الكتاب كذلك.` },
            { text: "وَعِندَهُۥ مَفَاتِحُ ٱلْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَ وَيَعْلَمُ مَا فِى ٱلْبَرِّ وَٱلْبَحْرِ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍ فِى ظُلُمَٰتِ ٱلْأَرْضِ وَلَا رَطْبٍ وَلَا يَابِسٍ إِلَّا فِى كِتَٰبٍ مُّبِينٍ", tafsir: `` },
            { text: "وَهُوَ ٱلَّذِى يَتَوَفَّىٰكُم بِٱلَّيْلِ وَيَعْلَمُ مَا جَرَحْتُم بِٱلنَّهَارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضَىٰٓ أَجَلٌ مُّسَمًّى ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ", tafsir: `سبحانه كما يعلم الأشياء كذلك تجري الأشياء بقدرته وإرادته ، فأنتم أيها البشر في قبضته وطوع أمره ، فإنه ( الَّذِي يَتَوَفَّاكُمْ ) أيها البشر ( بِاللَّيْلِ ) أي يقبض أرواحكم عن التصرف ، و « التوفي » أخذ ( 1) التوبة : 80. وَيَعْلَمُ ما جَرَحْتُمْ بِالنَّهارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضى أَجَلٌ مُسَمًّى ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُمْ بِما كُنْتُمْ تَعْمَلُونَ (60) وَهُوَ الْقاهِرُ فَوْقَ عِبادِهِ الشيء كاملا ومنه الوفاة ، فإن الإنسان إذا نام أخذ الله روحه المتصرفة التي تبصر وتسمع وتذوق وتلمس وتشم ، وهذه الآية كقوله سبحانه : ( اللهُ يَتَوَفَّى الْأَنْفُسَ حِينَ مَوْتِها ) (1) ، وإنما الفرق أن الموت توف بمعنى أتم من التوفي ، بمعنى النوم ( وَيَعْلَمُ ما جَرَحْتُمْ ) أي ما كسبتم وفعلتم ، أي عملتم بجوارحكم ( بِالنَّهارِ ) وهذا التفصيل خارج مجرى الغالب ، وإلا فهو يتوفى بالنهار لمن نام فيه ، ويعلم ما جرح الإنسان بالليل لمن عمل فيه ( ثُمَ ) بعد توفيكم بالليل ( يَبْعَثُكُمْ ) أي يوقظكم وينبهكم من نومكم ( فِيهِ ) أي في النهار ( لِيُقْضى ) أي لينهى ( أَجَلٌ مُسَمًّى ) أي أمدكم الذي سماه سبحانه في اللوح المحفوظ ، يعني أنه إنما يوقظكم في النهار حتّى لا يموت الإنسان قبل وقته ( ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ) بعد تمام المدة وانتهاء الأمد ، ترجعون إليه سبحانه في الآخرة ، والمراد : إلى حسابه ، وإلا فليس له سبحانه محلّ ، فإنه منزّه عن الزمان والمكان ( ثُمَّ يُنَبِّئُكُمْ ) أي يخبركم ـ بعد رجوعكم إليه ـ ( بِما كُنْتُمْ تَعْمَلُونَ ) ليعطي كلّ ذي جزاء جزائه ، إن خيرا فخير ، وإن شرا فشر.` },
            { text: "وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ", tafsir: `سبحانه ( الْقاهِرُ ) أي القادر الذي يقهر ويجبر كما يشاء ( فَوْقَ عِبادِهِ ) أي مستعل عليهم ، فإن من يتصرف في الإنسان يكون ( 1) الزمر : 43. وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً حَتَّى إِذا جاءَ أَحَدَكُمُ الْمَوْتُ تَوَفَّتْهُ رُسُلُنا وَهُمْ لا يُفَرِّطُونَ (61) ثُمَّ رُدُّوا إِلَى اللهِ مَوْلاهُمُ الْحَقِّ أَلا لَهُ الْحُكْمُ وَهُوَ أَسْرَعُ الْحاسِبِينَ (62) فوقه رتبة ، وليس المراد الفوقية الحقيقية ، فإنه منزه عن المكان ( وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً ) جمع حافظ ، وهم الملائكة الذين يبعثهم الله تعالى لحفظ الإنسان عن العطب ، وحفظ أعماله في دفاتر سجلات ليجزي كلّا حسب ما عمل ( حَتَّى إِذا جاءَ أَحَدَكُمُ الْمَوْتُ ) وصار وقت أن يموت تركه الحافظ له وأسلمه إلى حتفه ( تَوَفَّتْهُ ) أي قبضت روحه كاملة ( رُسُلُنا ) أي الملائكة المرسلة لأجل هذه الغاية ( وَهُمْ لا يُفَرِّطُونَ ) بأن يقدموا أخذ الروح أو يؤخروها ، أو يشددوا في النزع أو يخفّفوا ، بل يفعلون ما يؤمرون ، وإنما أتي بلفظ « رسلنا » جمعا ، لأن لملك الموت أعوانا ، كما ثبت من السنة ، ولعل في قوله : ( الَّذِينَ تَوَفَّاهُمُ الْمَلائِكَةُ ) (1) ، دلالة عليه.` },
            { text: "ثُمَّ رُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ أَلَا لَهُ ٱلْحُكْمُ وَهُوَ أَسْرَعُ ٱلْحَٰسِبِينَ", tafsir: `بعد ما أخذت الملائكة أرواحهم ( رُدُّوا ) أي رجعت أرواحهم ( إِلَى اللهِ ) أي في المكان المهيأ لهم من قبله سبحانه ( مَوْلاهُمُ الْحَقِ ) أي سيدهم بالحقيقة ، لا مثل سيادة الأصنام عليهم ( أَلا ) فلينتبه الناس أن الله ( لَهُ ) وحده ( الْحُكْمُ ) في جميع الأمور الكونية ، حتى قبض أرواحهم ومحاسبتهم هناك ( وَهُوَ أَسْرَعُ الْحاسِبِينَ ) وحسابه سريع لا يحتاج إلى ما يحتاج إليه حساب المحاسبين من الوقت ونحوه ، فليس هناك بطء في الحساب حتّى يكون للمحاسب مجال ( 1) النساء : 98. قُلْ مَنْ يُنَجِّيكُمْ مِنْ ظُلُماتِ الْبَرِّ وَالْبَحْرِ تَدْعُونَهُ تَضَرُّعاً وَخُفْيَةً لَئِنْ أَنْجانا مِنْ هذِهِ لَنَكُونَنَّ مِنَ الشَّاكِرِينَ (63) قُلِ اللهُ يُنَجِّيكُمْ مِنْها وَمِنْ كُلِّ كَرْبٍ ثُمَّ أَنْتُمْ تُشْرِكُونَ (64) قُلْ هُوَ الْقادِرُ عَلى واسع لكي يتمّ حسابه.` },
            { text: "قُلْ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ تَدْعُونَهُۥ تَضَرُّعًا وَخُفْيَةً لَّئِنْ أَنجَىٰنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ", tafsir: `يا رسول الله لهؤلاء الكفّار ، دلالة على قدرته سبحانه الكاملة : ( مَنْ يُنَجِّيكُمْ ) ويخلصكم ( مِنْ ظُلُماتِ الْبَرِّ وَالْبَحْرِ ) أي من شدائدهما وأهوالهما ، فإنّهم يقولون لليوم الشّديد : « يوم مظلم » تشبيها ، فكما أنّ الإنسان لا يهتدي طريقه في الليل والظلمة ، كذلك لا يهتدي طريقه في الشّدائد ( تَدْعُونَهُ ) أي تدعون الله تعالى إذا وقعتم في الشّدّة والظلمة ( تَضَرُّعاً ) ضراعة واستكانة بلسانكم ( وَخُفْيَةً ) وسرا في نفوسكم ، فتتوافق الظواهر والبواطن في الضراعة والمسألة لكي ينجيهم الله سبحانه ، قائلين : ( لَئِنْ أَنْجانا ) ربنا ( مِنْ هذِهِ ) الشّدّة والكارثة ( لَنَكُونَنَّ مِنَ الشَّاكِرِينَ ) الذين يشكرون نعمائه عليهم معترفين به وبفضله وإحسانه.` },
            { text: "قُلِ ٱللَّهُ يُنَجِّيكُم مِّنْهَا وَمِن كُلِّ كَرْبٍ ثُمَّ أَنتُمْ تُشْرِكُونَ", tafsir: `يا رسول الله لهؤلاء : ( اللهُ يُنَجِّيكُمْ مِنْها ) أي من هذه الشدّة ( وَمِنْ كُلِّ كَرْبٍ ) أي يخلّصكم من كلّ غمّ وهمّ ( ثُمَّ أَنْتُمْ تُشْرِكُونَ ) به غيره ، وترجعون إلى شرككم وعصيانكم ، كما قال سبحانه : ( فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ إِذا هُمْ يُشْرِكُونَ ) (1) .` },
            { text: "قُلْ هُوَ ٱلْقَادِرُ عَلَىٰٓ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَٰتِ لَعَلَّهُمْ يَفْقَهُونَ", tafsir: `يا رسول الله لهؤلاء الكفار : الله ( هُوَ الْقادِرُ عَلى ( 1) العنكبوت : 66. أَنْ يَبْعَثَ عَلَيْكُمْ عَذاباً مِنْ فَوْقِكُمْ أَوْ مِنْ تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعاً وَيُذِيقَ بَعْضَكُمْ بَأْسَ بَعْضٍ انْظُرْ كَيْفَ نُصَرِّفُ الْآياتِ لَعَلَّهُمْ يَفْقَهُونَ (65) وَكَذَّبَ بِهِ قَوْمُكَ وَهُوَ الْحَقُّ قُلْ لَسْتُ عَلَيْكُمْ بِوَكِيلٍ (66) أَنْ يَبْعَثَ ) أي يرسل ( عَلَيْكُمْ عَذاباً مِنْ فَوْقِكُمْ ) كالصواعق ( أَوْ مِنْ تَحْتِ أَرْجُلِكُمْ ) كالخسف ( أَوْ يَلْبِسَكُمْ ) من « لبس عليه الأمر » إذا خلط بعضه ببعض أي يخلطكم ( شِيَعاً ) جمع « شيعة » أي فرقا ، مختلفي الأهواء لا تكونون أمة واحدة ، بل أحزابا وأهواء ( وَيُذِيقَ بَعْضَكُمْ بَأْسَ بَعْضٍ ) فهم في عداء مستمر وحروب دائمة ، وإنما ينسب ذلك إليه سبحانه ، لأنه يكلهم إلى أمرهم بعد أن أعرضوا عن طريقه ، وتركوا منهاجه ( انْظُرْ ) يا رسول الله. والمراد بالنظر التأمل والتفكر ( كَيْفَ نُصَرِّفُ الْآياتِ ) نردّد الدلائل على التوحيد ونكررها مرة بعد مرة ( لَعَلَّهُمْ يَفْقَهُونَ ) أي يفهموا الحق ، ويذعنوا للخالق ويتجنبوا الكفر والباطل.` },
            { text: "وَكَذَّبَ بِهِۦ قَوْمُكَ وَهُوَ ٱلْحَقُّ قُل لَّسْتُ عَلَيْكُم بِوَكِيلٍ", tafsir: `أي بما نصرّف من الآيات ( قَوْمُكَ ) يا رسول الله ، والمراد بهم إما قريش ، وإما العرب ، وإما الناس المبعوث إليهم بصورة عامة ، والمراد بالتكذيب : تكذيب أغلبهم لا جميعهم ، لوضوح إيمان بعض من كلّ من الطوائف الثلاث به صلى‌الله‌عليه‌وآله‌وسلم حين نزول الآية ( وَهُوَ الْحَقُ ) أي ما نصرفه من الآيات حق لا مرية فيه ( قُلْ ) يا رسول الله لهؤلاء الكفار : ( لَسْتُ عَلَيْكُمْ بِوَكِيلٍ ) أي موكل إليّ أمركم حتى يضرني تكذيبكم ، بل أنا مبلّغ ، وقد بلغت ما أمرت بتبليغه. لِكُلِّ نَبَإٍ مُسْتَقَرٌّ وَسَوْفَ تَعْلَمُونَ (67) وَإِذا رَأَيْتَ الَّذِينَ يَخُوضُونَ فِي آياتِنا فَأَعْرِضْ عَنْهُمْ حَتَّى يَخُوضُوا فِي حَدِيثٍ غَيْرِهِ وَإِمَّا يُنْسِيَنَّكَ الشَّيْطانُ [68] ثم بيّن سبحانه أن ما أخبر به الرسول من وعيد المكذبين بشر الدنيا والآخرة لا بد وأن يظهر ، وهناك يعلم المكذبون أنهم خسروا ، وأن تكذيبهم عاد بالوبال عليهم ( لِكُلِّ نَبَإٍ ) أي لكل خبر ( مُسْتَقَرٌّ ) أي محل استقرار يظهر هناك صدقه ، فما كان في الدنيا يظهر أثره في الدنيا وما كان في الآخرة يظهر أثره في الآخرة ( وَسَوْفَ تَعْلَمُونَ ) أيها المكذبون عاقبة أمركم. [69] إن أول حركة لا بد وأن يختلط المؤمنون بها والمناوئون لها ، ولا بد وأن يكون ضعاف النفوس من المؤمنين يكتسبون من المعاندين بعض الأفكار المعادية ، ولا أقل من أن يجبنوا عن الاستمرار والتظاهر ، ولذا فمن اللازم أن يجنّب القادة أتباعهم عن الاختلاط خصوصا حالة التهجم من المعاندين ( وَإِذا رَأَيْتَ ) يا رسول الله ( الَّذِينَ يَخُوضُونَ فِي آياتِنا ) خوض المناقشة والاستهزاء ، والخطاب وإن كان موجها إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم إلا أنه عام لجميع المسلمين ( فَأَعْرِضْ عَنْهُمْ ) أي فاتركهم ولا تجالسهم ( حَتَّى يَخُوضُوا فِي حَدِيثٍ غَيْرِهِ ) أي غير ما خاضوا فيه أولا ، بأن يتكلموا في سائر المواضيع فلا بأس حينئذ من مجالستهم والتكلم معهم ( وَإِمَّا يُنْسِيَنَّكَ الشَّيْطانُ ) بأن نسي المسلم وجلس مع الخائضين في آيات الله ، والجملة شرطية ، أي : وإن أنساك ، و « ما » زائدة ، ومن المعلوم أن الشرط لا ينافي العصمة ، فإن الجملة الشرطية تأتي حتّى مع استحالة طرفيها نحو : إِنْ كانَ لِلرَّحْمنِ فَلا تَقْعُدْ بَعْدَ الذِّكْرى مَعَ الْقَوْمِ الظَّالِمِينَ (68) وَما عَلَى الَّذِينَ يَتَّقُونَ مِنْ حِسابِهِمْ مِنْ شَيْءٍ وَلكِنْ ذِكْرى لَعَلَّهُمْ يَتَّقُونَ (69) وَلَدٌ فَأَنَا أَوَّلُ الْعابِدِينَ ) (1) ، ( فَلا تَقْعُدْ بَعْدَ الذِّكْرى ) أي بعد التذكر ، لكون مجالستهم محرمة منهي عنها ( مَعَ الْقَوْمِ الظَّالِمِينَ ) الذين يخوضون في الآيات.` },
            { text: "لِّكُلِّ نَبَإٍ مُّسْتَقَرٌّ وَسَوْفَ تَعْلَمُونَ", tafsir: `` },
            { text: "وَإِذَا رَأَيْتَ ٱلَّذِينَ يَخُوضُونَ فِىٓ ءَايَٰتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيْطَٰنُ فَلَا تَقْعُدْ بَعْدَ ٱلذِّكْرَىٰ مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ", tafsir: `` },
            { text: "وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَلَٰكِن ذِكْرَىٰ لَعَلَّهُمْ يَتَّقُونَ", tafsir: `أي هل على المؤمنين المتقين ( مِنْ حِسابِهِمْ ) أي حساب الكفار الخائضين في آيات الله ( مِنْ شَيْءٍ ) ؟ فإنهم ليسوا بمسؤولين عن خوضهم في الآيات ( وَلكِنْ ) قيامهم عن المجالس إذا خاضوا ( ذِكْرى ) أي تذكير للخائضين بأنهم يعملون عملا سيّئا ، وإنما قال « ذكرى » لأن الخائض يعلم سوء فعله في قرارة نفسه ، لكنه يغفل غالبا حين الخوض ، فأمر المسلم أن يقوم من مجلسه ليتذكر ( لَعَلَّهُمْ ) أي لكي ينتهي الخائضون و ( يَتَّقُونَ ) ويتورعون عن الخوض. روي عن الإمام الباقر عليه‌السلام أنه قال : لما نزلت ( فَلا تَقْعُدْ بَعْدَ الذِّكْرى مَعَ الْقَوْمِ الظَّالِمِينَ ) قال المسلمون : كيف نصنع إن كان كلما استهزأ المشركون بالقرآن قمنا وتركناهم فلا ندخل المسجد الحرام ولا نطوف بالبيت الحرام ؟ فأنزل الله سبحانه : ( وَما عَلَى الَّذِينَ يَتَّقُونَ مِنْ حِسابِهِمْ مِنْ شَيْءٍ ) أمرهم بتذكيرهم وتبصيرهم ما استطاعوا (2) . ( 1) الزخرف : 82. ( 2) مستدرك الوسائل : ج 12 ص 312. وَذَرِ الَّذِينَ اتَّخَذُوا دِينَهُمْ لَعِباً وَلَهْواً وَغَرَّتْهُمُ الْحَياةُ الدُّنْيا وَذَكِّرْ بِهِ أَنْ تُبْسَلَ نَفْسٌ بِما كَسَبَتْ لَيْسَ لَها مِنْ دُونِ اللهِ وَلِيٌّ وَلا شَفِيعٌ وَإِنْ تَعْدِلْ كُلَّ عَدْلٍ لا يُؤْخَذْ مِنْها أُولئِكَ الَّذِينَ أُبْسِلُوا بِما كَسَبُوا لَهُمْ شَرابٌ` },
            { text: "وَذَرِ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَعِبًا وَلَهْوًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَذَكِّرْ بِهِۦٓ أَن تُبْسَلَ نَفْسٌۢ بِمَا كَسَبَتْ لَيْسَ لَهَا مِن دُونِ ٱللَّهِ وَلِىٌّ وَلَا شَفِيعٌ وَإِن تَعْدِلْ كُلَّ عَدْلٍ لَّا يُؤْخَذْ مِنْهَآ أُو۟لَٰٓئِكَ ٱلَّذِينَ أُبْسِلُوا۟ بِمَا كَسَبُوا۟ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ", tafsir: `أي اترك يا رسول الله ( الَّذِينَ اتَّخَذُوا دِينَهُمْ لَعِباً وَلَهْواً ) المراد من « دينهم » : الذي يتدينون به من عبادة الأصنام ، والمسيحية واليهودية وما أشبه ، والمراد باتخاذه لعبا ولهوا : أنهم كالأطفال الذين يتخذون آلة للعب واللهو فلا علاقة لهم بها إلا علاقة التلاعب ، لا أنه دين وصل إلى أعماق قلوبهم وأخذ يوجه حياتهم ، وأما دينهم الذي يجب أن يتدينوا به ـ أي الإسلام ـ ونسبته إليهم لأجل وجوب اتخاذه دينا ، واتخاذه لعبا ولهوا استهزاؤهم به كأنه لعب ولهو ( وَغَرَّتْهُمُ الْحَياةُ الدُّنْيا ) زاعمين أنه ليس ورائها شيء ، وشغلتهم الدنيا عن الدين ( وَذَكِّرْ ) يا رسول الله هؤلاء الكفار ( بِهِ ) أي بالدين ( أَنْ تُبْسَلَ ) من « بسل » بمعنى استسلم ، أي لكي لا تسلم ( نَفْسٌ ) للهلكة ( بِما كَسَبَتْ ) أي بسبب عملها ، فإنك إن ذكّرت لعلها تعود إلى الرشد وتنقذ من الهلكة حيث ( لَيْسَ لَها ) أي للنفس ( مِنْ دُونِ اللهِ ) أي غير الله ( وَلِيٌ ) ناصر ينصرها ( وَلا شَفِيعٌ ) يشفع لها ، فإن الشفاعة بيد الله وحده ( وَإِنْ تَعْدِلْ كُلَّ عَدْلٍ ) أي تفدي بكل ما يمكن جعله فدية ، لتنقذ نفسها من العذاب ( لا يُؤْخَذْ مِنْها ) إذ ليس الميزان هناك إلا العمل وحده ( أُولئِكَ ) الذين اتخذوا دينهم لعبا ولهوا هم ( الَّذِينَ أُبْسِلُوا بِما كَسَبُوا ) أي أهلكوا « ب » سبب « ما كسبوا » من الأعمال والعقائد الباطلة ( لَهُمْ شَرابٌ مِنْ حَمِيمٍ وَعَذابٌ أَلِيمٌ بِما كانُوا يَكْفُرُونَ (70) قُلْ أَ نَدْعُوا مِنْ دُونِ اللهِ ما لا يَنْفَعُنا وَلا يَضُرُّنا وَنُرَدُّ عَلى أَعْقابِنا بَعْدَ إِذْ هَدانَا اللهُ كَالَّذِي اسْتَهْوَتْهُ الشَّياطِينُ فِي الْأَرْضِ حَيْرانَ لَهُ أَصْحابٌ يَدْعُونَهُ إِلَى الْهُدَى ائْتِنا مِنْ حَمِيمٍ ) أي : الماء الذي يشربون إنما هو من حميم جهنم ، وهو الماء المغلي الحار ( وَعَذابٌ أَلِيمٌ ) أي مؤلم موجع ( بِما كانُوا يَكْفُرُونَ ) أي بسبب كفرهم.` },
            { text: "قُلْ أَنَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعْقَابِنَا بَعْدَ إِذْ هَدَىٰنَا ٱللَّهُ كَٱلَّذِى ٱسْتَهْوَتْهُ ٱلشَّيَٰطِينُ فِى ٱلْأَرْضِ حَيْرَانَ لَهُۥٓ أَصْحَٰبٌ يَدْعُونَهُۥٓ إِلَى ٱلْهُدَى ٱئْتِنَا قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ ٱلْعَٰلَمِينَ", tafsir: `يا رسول الله لهؤلاء الكفار : ( أَ نَدْعُوا مِنْ دُونِ اللهِ ما لا يَنْفَعُنا ) أي هل ندعو الأصنام التي لا تنفعنا إن عبدناها ( وَلا يَضُرُّنا ) إن تركنا عبادتها ( وَنُرَدُّ عَلى أَعْقابِنا ) أي نرجع القهقرى ، فإن من أتى إلى مكان ثم رجع إلى محله الأول كان خاسرا ، و « الأعقاب » جمع « عقب » ( بَعْدَ إِذْ هَدانَا اللهُ ) إلى دينه وصراطه ( كَالَّذِي اسْتَهْوَتْهُ ) أي استغوته ( الشَّياطِينُ ) أي الغيلان ( فِي الْأَرْضِ ) أي البيداء ، بأن أخرجته الشياطين من الجادة إلى المهلكة ( حَيْرانَ ) لا يدري أ يتبع أصحابه أم يتبع الشياطين ( لَهُ ) أي لهذا الذي استهوته الشياطين ( أَصْحابٌ يَدْعُونَهُ إِلَى الْهُدَى ) إلى الجادة ، وأن لا يتبع الشياطين ، قائلين له : ( ائْتِنا ) أي جئنا وكن معنا. فإن قسما من الغول ـ وهم سحرة الجن ـ يكونون في الصحراء ، يؤذون بعض المارة ، فإذا رأى الشخص جماعة منهم يستهوونه قائلين له : من هنا الجادة ـ ويدلّونه إلى المفاوز المهلكة ـ فهو يتحير بين أن يسير مع هذه الجماعة التي تصبغ نفسها بصبغة أدلاء الطريق وأنها من أهل البادية تعرف الطريق الموصل من قُلْ إِنَّ هُدَى اللهِ هُوَ الْهُدى وَأُمِرْنا لِنُسْلِمَ لِرَبِّ الْعالَمِينَ (71) وَأَنْ أَقِيمُوا الصَّلاةَ وَاتَّقُوهُ وَهُوَ الَّذِي إِلَيْهِ تُحْشَرُونَ (72) وَهُوَ الَّذِي خَلَقَ السَّماواتِ وَالْأَرْضَ بِالْحَقِّ غيره ، أم يسير مع رفاقه الذين خرج معهم ، حيث أنهم رفاقه ، لكنهم ـ بزعمه ـ يمشون على غير الطريق ويصيبهم العطب أخيرا. وهناك قسم من الناس ينكرون الجن والغول والشيطان ، لكنه من ضيق الأفق ، فإن العلمين القديم والحديث أيّدا الدين والقصص المؤكدة لوجود ذلك (1) . ( قُلْ ) يا رسول الله : ( إِنَّ هُدَى اللهِ هُوَ الْهُدى ) الذي ينبغي للإنسان أن يتبعه ويترك غيره ( وَأُمِرْنا ) أي أمرنا الله وأرشدنا العقل ( لِنُسْلِمَ لِرَبِّ الْعالَمِينَ ) في جميع شؤوننا.` },
            { text: "وَأَنْ أَقِيمُوا۟ ٱلصَّلَوٰةَ وَٱتَّقُوهُ وَهُوَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ", tafsir: `أمرنا ( أَنْ أَقِيمُوا الصَّلاةَ ) أي بإقامة الصلاة ، فإن حذف حرف الجر ، مع أن « وأن » مطرد شائع ، كما قال ابن مالك : و الخوف مع أن وإن يطرد مع أمن لبس كعجبت أن يدو ( وَاتَّقُوهُ ) أي احذروا عقاب الله تعالى ( وَهُوَ الَّذِي إِلَيْهِ تُحْشَرُونَ ) أي تجمعون يوم القيامة ليحاسبكم على ما عملتم من خير وشر.` },
            { text: "وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَيَوْمَ يَقُولُ كُن فَيَكُونُ قَوْلُهُ ٱلْحَقُّ وَلَهُ ٱلْمُلْكُ يَوْمَ يُنفَخُ فِى ٱلصُّورِ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ", tafsir: `والمراد بالسماوات : إما الأجرام هناك ، أو المدارات للكواكب ( بِالْحَقِ ) أي ليس بالباطل فإن ( 1) أنظر كتاب « على حافة العالم الاثيري » لفريد وجدي ، مادة « اسبرتزم » . وَيَوْمَ يَقُولُ كُنْ فَيَكُونُ قَوْلُهُ الْحَقُّ وَلَهُ الْمُلْكُ يَوْمَ يُنْفَخُ فِي الصُّورِ عالِمُ الْغَيْبِ وَالشَّهادَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ (73) من يصنع شيئا قد يصنعه عبثا وباطلا وقد يصنعه لغاية وحكمة ، فمعنى بالحق : أن الخلق ليس عبثا ، كما قال سبحانه : ( ما خَلَقْتَ هذا باطِلاً سُبْحانَكَ ) (1) ، ( وَيَوْمَ يَقُولُ ) سبحانه لشيء ( كُنْ ) واخرج من العدم إلى الوجود ( فَيَكُونُ ) ويوجد ( قَوْلُهُ الْحَقُ ) الظاهر أنه العامل في « يوم » أي أن قوله تعالى يكون ويتحقق في أي يوم قال لشيء «كن» فهو سبحانه خلقه بالحق ، وقوله حق ، أي متحقق ثابت لا خلف فيه ، وليس كأقوال من تذهب أقواله باطلة. ( وَلَهُ الْمُلْكُ يَوْمَ يُنْفَخُ فِي الصُّورِ ) الصور هو الآلة التي ينفخ فيها لأجل هلاك الناس جميعا ، وهو في آخر يوم من أيام الدنيا ، أو لأجل أحيائهم جميعا ، وهو في أول يوم من أيام الآخرة ، يعني أنه سبحانه الملك الوحيد الذي لا يوجد ملك غيره ، في ذلك اليوم. والفقرات الثلاثة في الآية لبيان الأحوال الثلاثة ، الخلق للأشياء ، والتصرف في الكون بما يشاء الله ، وكون المعادلة له سبحانه ، وهو ( عالِمُ الْغَيْبِ ) أي يعلم ما غاب عن الحواس ، لعدم إدراك الحواس له ، أو لكونه من الأمور المستقلة ( وَالشَّهادَةِ ) أي ما يشاهده الناس ، وأتى بهذه الجملة هنا ، ليتناسق العلم مع القدرة ، ( وَهُوَ الْحَكِيمُ ) في أفعاله ( الْخَبِيرُ ) بالأشياء ، فلا يعمل شيئا اعتباطا وعبثا ( 1) آل عمران : 192. وَإِذْ قالَ إِبْراهِيمُ لِأَبِيهِ آزَرَ أَ تَتَّخِذُ أَصْناماً آلِهَةً إِنِّي أَراكَ وَقَوْمَكَ فِي ضَلالٍ مُبِينٍ (74) وَكَذلِكَ نُرِي إِبْراهِيمَ مَلَكُوتَ السَّماواتِ وَالْأَرْضِ وَلِيَكُونَ مِنَ الْمُوقِنِينَ (75) [75] وبعد ما بيّن سبحانه الأدلة حول التوحيد ، أتى بقصة إبراهيم عليه‌السلام الذي كان يدعو إلى التوحيد ، ليمثل الأدلة في قصة حوارية جذابة ( وَ ) اذكر يا رسول الله ( إِذْ قالَ إِبْراهِيمُ لِأَبِيهِ آزَرَ ) والمراد بالأب هنا العم ، كما ورد ، فإن العرب تسمي العم أبا ، كما تسمي الخالة أما ، و قد ورد في زيارة الشهيد على الأكبر عليه‌السلام ، « السلام عليك يا بن الحسن والحسين » ( أَ تَتَّخِذُ أَصْناماً آلِهَةً ) على وجه الاستنكار والتوبيخ ، أي كيف تعبد الأصنام وتجعلها إلها من دون الله ؟ ( إِنِّي أَراكَ وَقَوْمَكَ فِي ضَلالٍ مُبِينٍ ) أي واضح ، فإن الإله يجب أن يكون خالقا رازقا فكيف تكون الأصنام آلهة ؟` },
            { text: "وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَامًا ءَالِهَةً إِنِّىٓ أَرَىٰكَ وَقَوْمَكَ فِى ضَلَٰلٍ مُّبِينٍ", tafsir: `` },
            { text: "وَكَذَٰلِكَ نُرِىٓ إِبْرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلِيَكُونَ مِنَ ٱلْمُوقِنِينَ", tafsir: `أي بمثل هذه الفطرة المستقيمة التي رأى بها إبراهيم بطلان عبادة الأصنام ( نُرِي إِبْراهِيمَ مَلَكُوتَ السَّماواتِ وَالْأَرْضِ ) أي آثار الملك الموجودة في السماوات والأرض من الشمس والقمر والنجوم والجبال والبحار والأشجار والدواب وغيرها ، مما تدل كلها على وجود إله حكيم عليم خالق قادر ، وإنما نسب الإراءة إلى نفسه تعالى لأنه هو الذي فتق بصيرة إبراهيم عليه‌السلام للتأمل في الآيات الكونية. وفي الأحاديث أنه عليه‌السلام كان يرى أغوار الأرض وآفاق السماء فقد كشف عن عينه الحجاب وكان يرى ما لا يدركه البصر الإنساني. ( وَلِيَكُونَ مِنَ الْمُوقِنِينَ ) أي المتيقنين بأن الله سبحانه هو الخالق والإله ، أريناه الملكوت ، فجملة « وليكون .. إلخ » مستأنفة. فَلَمَّا جَنَّ عَلَيْهِ اللَّيْلُ رَأى كَوْكَباً قالَ هذا رَبِّي فَلَمَّا أَفَلَ قالَ لا أُحِبُّ الْآفِلِينَ (76) فَلَمَّا رَأَى الْقَمَرَ بازِغاً قالَ هذا رَبِّي فَلَمَّا أَفَلَ قالَ لَئِنْ لَمْ يَهْدِنِي رَبِّي لَأَكُونَنَّ مِنَ الْقَوْمِ الضَّالِّينَ (77) فَلَمَّا رَأَى الشَّمْسَ بازِغَةً قالَ هذا رَبِّي هذا [77] إن إبراهيم عليه‌السلام اصطدم بأصناف ثلاثة يعبدون من دون الله الكواكب ، فكان بعضهم يعبدون « الزهرة » وبعضهم يعبد « القمر » وبعضهم يعبد « الشمس » فأراد الاحتجاج عليهم فلما جن عليه الليل رأى الزهرة فقال لعبّادها مستنكرا : هل هذا ربي ؟ ثم رد عليهم بأنه آفل ذاهب متحرك ، وهذا من شأن المخلوق لا الخالق فإن الخالق لا يتغير ولا يتحرك ، وبعد ما طلع القمر ، قال لعباده على وجه الاستنكار : هل هذا ربي ؟ ثم أبطل ألوهيته بما سبق وبيّن أن إلهه هو الله وحده لا شريك له. ( فَلَمَّا جَنَ ) أي أظلم ( عَلَيْهِ اللَّيْلُ ) وستر بظلامه كل شيء ( رَأى ) إبراهيم عليه‌السلام ( كَوْكَباً ) وجماعة يعبدونه ( قالَ ) مستنكرا عليهم : هل ( هذا رَبِّي ) ؟ ( فَلَمَّا أَفَلَ ) وغرب النجم ( قالَ ) إبراهيم : ( لا أُحِبُّ الْآفِلِينَ ) أي لا أحب أن أتخذ الشيء الذي يغرب إلها.` },
            { text: "فَلَمَّا جَنَّ عَلَيْهِ ٱلَّيْلُ رَءَا كَوْكَبًا قَالَ هَٰذَا رَبِّى فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلْـَٔافِلِينَ", tafsir: `` },
            { text: "فَلَمَّا رَءَا ٱلْقَمَرَ بَازِغًا قَالَ هَٰذَا رَبِّى فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِى رَبِّى لَأَكُونَنَّ مِنَ ٱلْقَوْمِ ٱلضَّآلِّينَ", tafsir: `إبراهيم عليه‌السلام ( الْقَمَرَ بازِغاً ) أي طالعا منيرا وجماعة يعبدونه ( قالَ ) مستنكرا عليهم : هل ( هذا رَبِّي ) ؟ ( فَلَمَّا أَفَلَ ) وغرب القمر ( قالَ ) إبراهيم على سبيل التّعريض بأولئك ( لَئِنْ لَمْ يَهْدِنِي رَبِّي ) إلى الطّريق المستقيم ( لَأَكُونَنَّ مِنَ الْقَوْمِ الضَّالِّينَ ) الذين ضلّوا الطّريق ، واتّخذوا آلهة باطلة.` },
            { text: "فَلَمَّا رَءَا ٱلشَّمْسَ بَازِغَةً قَالَ هَٰذَا رَبِّى هَٰذَآ أَكْبَرُ فَلَمَّآ أَفَلَتْ قَالَ يَٰقَوْمِ إِنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ", tafsir: `أصبح إبراهيم عليه‌السلام و ( رَأَى الشَّمْسَ بازِغَةً ) طالعة وجماعة يعبدونها ( قالَ ) مستنكرا عملهم طاعنا في حجّتهم : هل ( هذا رَبِّي هذا أَكْبَرُ فَلَمَّا أَفَلَتْ قالَ يا قَوْمِ إِنِّي بَرِيءٌ مِمَّا تُشْرِكُونَ (78) إِنِّي وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّماواتِ وَالْأَرْضَ حَنِيفاً وَما أَنَا مِنَ الْمُشْرِكِينَ (79) وَحاجَّهُ قَوْمُهُ قالَ أَ تُحاجُّونِّي فِي اللهِ وَقَدْ هَدانِ وَلا أَخافُ ما تُشْرِكُونَ بِهِ إِلاَّ أَنْ يَشاءَ رَبِّي شَيْئاً ( أَكْبَرُ ) ؟ ، فكأنّهم كانوا يستدلّون بكبرها على أنها الرّب دون سواها ( فَلَمَّا أَفَلَتْ ) الشّمس وغربت ( قالَ ) إبراهيم عليه‌السلام : ( يا قَوْمِ ) العبّاد لغير الله تعالى ( إِنِّي بَرِيءٌ مِمَّا تُشْرِكُونَ ) أي ما تجعلونه من الكواكب شريكا لله سبحانه.` },
            { text: "إِنِّى وَجَّهْتُ وَجْهِىَ لِلَّذِى فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ حَنِيفًا وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ", tafsir: `والمراد بالوجه الذات ، لكن حيث أن الإنسان حينما يخلص لشيء ويريد استقباله ، يوجّه وجهه إليه ، واستعمل الوجه في الذات مجازا ( لِلَّذِي فَطَرَ السَّماواتِ وَالْأَرْضَ ) أي خلقها وأوجدها ( حَنِيفاً ) أي مائلا عن الشرك إلى الإخلاص ( وَما أَنَا مِنَ الْمُشْرِكِينَ ) الذين يشركون بالله غيره. [81] ولما جادل إبراهيم حول الأصنام والكواكب التي يعبدها قومه ، فشي أمره فجاء إليه الناس يحاجّونه ( وَحاجَّهُ قَوْمُهُ ) أي خاصموه وجادلوه في باب الألوهية ( قالَ ) إبراهيم ( أَ تُحاجُّونِّي فِي اللهِ ) أي تجادلونني بالنسبة إلى الله تعالى ( وَقَدْ هَدانِ ) إلى الحق بلطفه وإحسانه ( وَلا أَخافُ ما تُشْرِكُونَ بِهِ ) أي لا أخاف من آلهتكم أن يسببوا لي ضررا ، فإنه ليس الصنم والنجم يضران الإنسان ( إِلَّا أَنْ يَشاءَ رَبِّي شَيْئاً ) أي ضررا بي ، والاستثناء منقطع ، وقد مر سابقا أن هذه الاستثناءات إنما وَسِعَ رَبِّي كُلَّ شَيْءٍ عِلْماً أَ فَلا تَتَذَكَّرُونَ (80) وَكَيْفَ أَخافُ ما أَشْرَكْتُمْ وَلا تَخافُونَ أَنَّكُمْ أَشْرَكْتُمْ بِاللهِ ما لَمْ يُنَزِّلْ بِهِ عَلَيْكُمْ سُلْطاناً فَأَيُّ الْفَرِيقَيْنِ أَحَقُّ بِالْأَمْنِ إِنْ كُنْتُمْ تَعْلَمُونَ (81) الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمانَهُمْ بِظُلْمٍ هي لأجل إفادة تمام الطلب بعد جعل المستثنى منه الإطلاق ، فالأصل مثلا ، ولا أخاف ضررا إلا من الله سبحانه. ولست أعلم ما يشاء ربي من ضرري أو نفعي بل ( وَسِعَ رَبِّي كُلَّ شَيْءٍ عِلْماً ) أي سبحانه المحيط بالأشياء بعلمه الواسع واطلاعه الشامل ( أَ فَلا تَتَذَكَّرُونَ ) أيها المشركون وتتدبرون لتعرفوا أن الأمر كما قلت لكم.` },
            { text: "وَحَآجَّهُۥ قَوْمُهُۥ قَالَ أَتُحَٰٓجُّوٓنِّى فِى ٱللَّهِ وَقَدْ هَدَىٰنِ وَلَآ أَخَافُ مَا تُشْرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّى شَيْـًٔا وَسِعَ رَبِّى كُلَّ شَىْءٍ عِلْمًا أَفَلَا تَتَذَكَّرُونَ", tafsir: `` },
            { text: "وَكَيْفَ أَخَافُ مَآ أَشْرَكْتُمْ وَلَا تَخَافُونَ أَنَّكُمْ أَشْرَكْتُم بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ عَلَيْكُمْ سُلْطَٰنًا فَأَىُّ ٱلْفَرِيقَيْنِ أَحَقُّ بِٱلْأَمْنِ إِن كُنتُمْ تَعْلَمُونَ", tafsir: `أنا المعتقد بالله سبحانه الضرر من قبل ( ما أَشْرَكْتُمْ ) من الأصنام والنجوم وهي لا تملك شيئا من الضرر والنفع ( وَ ) الحال أنكم ( لا تَخافُونَ أَنَّكُمْ أَشْرَكْتُمْ بِاللهِ ) الذي بيده كل ضرر ونفع ( ما لَمْ يُنَزِّلْ بِهِ عَلَيْكُمْ سُلْطاناً ) أي جعلتم النجوم والأصنام شركاء لله والتي لم يدل دليل من قبل الله سبحانه على صحتها ، فإن « ما » موصولة مصداقها « الأصنام والنجوم » ( فَأَيُّ الْفَرِيقَيْنِ ) نحن وأنتم ( أَحَقُّ بِالْأَمْنِ ) بأن لا يخاف الضرر ( إِنْ كُنْتُمْ تَعْلَمُونَ ) أي تستعملون عقولكم وعلومكم فتميزون الحق من الباطل ؟ [83] ثم بيّن سبحانه من له الأمن بقوله : ( الَّذِينَ آمَنُوا ) بالله تعالى ( وَلَمْ يَلْبِسُوا ) أي لم يخلطوا ( إِيمانَهُمْ بِظُلْمٍ ) بأن لم يشركوا فإن الشرك ظلم ، أُولئِكَ لَهُمُ الْأَمْنُ وَهُمْ مُهْتَدُونَ (82) وَتِلْكَ حُجَّتُنا آتَيْناها إِبْراهِيمَ عَلى قَوْمِهِ نَرْفَعُ دَرَجاتٍ مَنْ نَشاءُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ (83) وَوَهَبْنا لَهُ إِسْحاقَ وَيَعْقُوبَ كما قال سبحانه : ( لا تُشْرِكْ بِاللهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ ) (1) ( أُولئِكَ لَهُمُ الْأَمْنُ ) فإنهم لا يخافون عقاب الآخرة ، ولا ضرر الدنيا بلا عوض ( وَهُمْ مُهْتَدُونَ ) أي مهديون إلى الحق. وهذه الآية وإن كان موردها قصة إبراهيم عليه‌السلام والإيمان والشرك إلا أنها عامة تشمل كل إيمان لم يلبس بظلم ، ولذا ورد في مصداقها الولاية لأهل البيت عليهم‌السلام (2) .` },
            { text: "ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَٰنَهُم بِظُلْمٍ أُو۟لَٰٓئِكَ لَهُمُ ٱلْأَمْنُ وَهُم مُّهْتَدُونَ", tafsir: `` },
            { text: "وَتِلْكَ حُجَّتُنَآ ءَاتَيْنَٰهَآ إِبْرَٰهِيمَ عَلَىٰ قَوْمِهِۦ نَرْفَعُ دَرَجَٰتٍ مَّن نَّشَآءُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ", tafsir: `الحجة التي احتج بها إبراهيم عليه‌السلام في ما سبق ( حُجَّتُنا ) أي الأدلة التي ( آتَيْناها إِبْراهِيمَ ) أعطيناها لإبراهيم عليه‌السلام ، ولقنّاه إياها ( عَلى قَوْمِهِ ) المشركين حتى تمكن من إيرادها عليهم وأن يغلبهم ( نَرْفَعُ دَرَجاتٍ مَنْ نَشاءُ ) كما رفعنا إبراهيم عليه‌السلام درجات حيث كان مؤمنا موحدا مجاهدا ( إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ ) فبحسب حكمته البالغة يرفع الدرجات ، وبحسب علمه الشامل يعلم الأشياء.` },
            { text: "وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ كُلًّا هَدَيْنَا وَنُوحًا هَدَيْنَا مِن قَبْلُ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيْمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ", tafsir: `أي لإبراهيم عليه‌السلام ( إِسْحاقَ وَيَعْقُوبَ ) إسحاق هو ابن إبراهيم من سارة ، ويعقوب ابن اسحق عليهم‌السلام ، ولم يذكر إسماعيل وهو ابنه من هاجر لإرادة ذكره مستقلا حتى يظهر له من الشأن ما لا يظهر لو أدرج في جملة « وهبنا » وقد ذكر سبحانه الشجرة النبوية من إبراهيم عليه‌السلام ومن نوح عليه‌السلام فلا يفوت ذكره حيث يذكرون ( 1) لقمان : 14. ( 2) بحار الأنوار : ج 36 ص 114. كُلاًّ هَدَيْنا وَنُوحاً هَدَيْنا مِنْ قَبْلُ وَمِنْ ذُرِّيَّتِهِ داوُدَ وَسُلَيْمانَ وَأَيُّوبَ وَيُوسُفَ وَمُوسى وَهارُونَ وَكَذلِكَ نَجْزِي الْمُحْسِنِينَ (84) وَزَكَرِيَّا وَيَحْيى وَعِيسى وَإِلْياسَ كُلٌّ مِنَ الصَّالِحِينَ (85) وَإِسْماعِيلَ وَالْيَسَعَ وَيُونُسَ وَلُوطاً ( كُلًّا ) من الثلاثة ( هَدَيْنا ) إلى الحق والى صراط مستقيم ( وَنُوحاً هَدَيْنا مِنْ قَبْلُ ) هؤلاء ( وَمِنْ ذُرِّيَّتِهِ ) أي من ذرية إبراهيم ، أو من ذرية نوح عليه‌السلام أو المراد كلّا منهما ، فإنه يجوز ذلك بإرجاع الضمير إلى كل واحد ، كما قال سبحانه : ( فَانْظُرْ إِلى طَعامِكَ وَشَرابِكَ لَمْ يَتَسَنَّهْ ) (1) ( داوُدَ وَسُلَيْمانَ ) وهو ابن داود ( وَأَيُّوبَ وَيُوسُفَ ) ابن يعقوب بن إسحاق بن إبراهيم ( وَمُوسى ) بن عمران ( وَهارُونَ ) أخو موسى عليه‌السلام ( وَكَذلِكَ ) أي هكذا يجعل النبوة في ذريته ، تكريما له ( نَجْزِي الْمُحْسِنِينَ ) الذين يحسنون في أعمالهم ، فإنا نكرمهم بما يستحقون.` },
            { text: "وَزَكَرِيَّا وَيَحْيَىٰ وَعِيسَىٰ وَإِلْيَاسَ كُلٌّ مِّنَ ٱلصَّٰلِحِينَ", tafsir: `ابن زكريا ( وَعِيسى ) ابن مريم ( وَإِلْياسَ كُلٌّ مِنَ الصَّالِحِينَ ) أي أن كل واحد منهم من الذين أصلحوا.` },
            { text: "وَإِسْمَٰعِيلَ وَٱلْيَسَعَ وَيُونُسَ وَلُوطًا وَكُلًّا فَضَّلْنَا عَلَى ٱلْعَٰلَمِينَ", tafsir: `ابن إبراهيم عليه‌السلام جد النبي صلى‌الله‌عليه‌وآله‌وسلم ومن المحتمل أن يراد به إسماعيل صادق الوعد الذي أشير إليه في قوله سبحانه : ( وَاذْكُرْ فِي الْكِتابِ إِسْماعِيلَ إِنَّهُ كانَ صادِقَ الْوَعْدِ ) (2) ، ( وَالْيَسَعَ وَيُونُسَ ) ابن متّى صاحب الحوت ( وَلُوطاً ) والكلام في « اللام » في « اليسع » ، ( 1) البقرة : 260. ( 2) مريم : 55. وَكلاًّ فَضَّلْنا عَلَى الْعالَمِينَ (86) وَمِنْ آبائِهِمْ وَذُرِّيَّاتِهِمْ وَإِخْوانِهِمْ وَاجْتَبَيْناهُمْ وَهَدَيْناهُمْ إِلى صِراطٍ مُسْتَقِيمٍ (87) ذلِكَ هُدَى اللهِ يَهْدِي بِهِ مَنْ يَشاءُ مِنْ عِبادِهِ وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ والمنصرف وغير المنصرف من الأسماء مرتبط بالمفصلات ( وَكلًّا ) أي كل واحد منهم ( فَضَّلْنا عَلَى الْعالَمِينَ ) أي عالم زمانهم ، فإن كل نبي كان أفضل من جميع الناس ، باستثناء النبي الذي في عهده ، فلوط كان في عهد إبراهيم ولم يكن أفضل منه.` },
            { text: "وَمِنْ ءَابَآئِهِمْ وَذُرِّيَّٰتِهِمْ وَإِخْوَٰنِهِمْ وَٱجْتَبَيْنَٰهُمْ وَهَدَيْنَٰهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ", tafsir: `كذلك فضلنا جماعة ( مِنْ آبائِهِمْ ) أي من آباء هؤلاء الأنبياء ( وَذُرِّيَّاتِهِمْ ) أي أولاد هؤلاء الأنبياء ( وَإِخْوانِهِمْ ) أي إخوان هؤلاء الأنبياء ( وَاجْتَبَيْناهُمْ ) أي اصطفيناهم واخترناهم للرسالة ( وَهَدَيْناهُمْ ) إلى الحق ، وذلك لا يلازم سبق الضلالة ، كما لا يخفى ( إِلى صِراطٍ مُسْتَقِيمٍ ) في كل شيء ؛ العقيدة والسلوك والقول.` },
            { text: "ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ وَلَوْ أَشْرَكُوا۟ لَحَبِطَ عَنْهُم مَّا كَانُوا۟ يَعْمَلُونَ", tafsir: `الهدى الذي هدينا به الأنبياء ( هُدَى اللهِ ) وإرشاده الذي يأتي بأكمل السعادة وأوفر الخير ( يَهْدِي بِهِ مَنْ يَشاءُ مِنْ عِبادِهِ ) ، والمراد إما الهدى الخالص ، ومن المعلوم أنه لا يلزم في الحكمة بالنسبة إلى كل أحد ، وإما الهدى العام وذلك وإن لزم بالنسبة إلى كل أحد لكن المراد هنا الإيصال إلى المطلوب لا إراءة الطريق ، أو يقال : إن الذي دلّ عليه الدليل أن العقاب لا يجوز بلا بيان ، أما الهداية فلا دليل عقلي على إيجابها بالنسبة إلى كل أحد ، نعم في لزوم خروج الخلق عن العبث يلزم الإرشاد في الجملة ( وَلَوْ أَشْرَكُوا ) أي لو أشرك هؤلاء الأنبياء ( لَحَبِطَ ) أي لبطل ( عَنْهُمْ ) فإن الحبط لما أشرب معنى الزوال والذهاب عدّي ب « عن » ما كانُوا يَعْمَلُونَ (88) أُولئِكَ الَّذِينَ آتَيْناهُمُ الْكِتابَ وَالْحُكْمَ وَالنُّبُوَّةَ فَإِنْ يَكْفُرْ بِها هؤُلاءِ فَقَدْ وَكَّلْنا بِها قَوْماً لَيْسُوا بِها بِكافِرِينَ (89) أُولئِكَ الَّذِينَ هَدَى اللهُ ( ما كانُوا يَعْمَلُونَ ) من الأعمال السابقة على الشرك. ثم إن الآية في مقام بيان أن الشرك موجب لحبط الأعمال مهما كانت سوابق الشرك ، إذ من المعلوم الضروري عدم شرك الأنبياء ، فإن الشرط يأتي حتّى في مستحيل الطرفين ، كقوله : ( قُلْ إِنْ كانَ لِلرَّحْمنِ وَلَدٌ فَأَنَا أَوَّلُ الْعابِدِينَ ) (1) ، ومن هذا القبيل أيضا قوله : ( لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ ) (2) .` },
            { text: "أُو۟لَٰٓئِكَ ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ فَإِن يَكْفُرْ بِهَا هَٰٓؤُلَآءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًا لَّيْسُوا۟ بِهَا بِكَٰفِرِينَ", tafsir: `الذين ذكرناهم من الأنبياء عليهم‌السلام ، هم ( الَّذِينَ آتَيْناهُمُ ) أي أعطيناهم ( الْكِتابَ ) المراد به الجنس ( وَالْحُكْمَ ) أي منصب الحكم بين الناس ، فإن هذا المنصب ليس إلّا لله ولمن أعطاه إياه ( وَالنُّبُوَّةَ ) حيث كانوا أنبياء ، وذكر النبوة بعد الكتاب ، لدفع توهم أن إعطاء الكتاب ليس من قبيل إعطاء الكتاب للاسم ، كقوله سبحانه : ( خُذُوا ما آتَيْناكُمْ بِقُوَّةٍ ) (3) ، ( فَإِنْ يَكْفُرْ بِها ) أي بالكتاب والحكم والنبوة ( هؤُلاءِ ) الكفار الذين جحدوا نبوتك يا رسول الله ( فَقَدْ وَكَّلْنا بِها ) أي بالإيمان بها ، والمراد إيكال أمر دعاية النبوة والإيمان بها ، والجهاد في سبيلها ، كالوكيل الذي يراعي أمور الموكل ( قَوْماً لَيْسُوا بِها بِكافِرِينَ ) فهم يقومون بواجب أمر النبوة خير قيام.` },
            { text: "أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُ فَبِهُدَىٰهُمُ ٱقْتَدِهْ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِنْ هُوَ إِلَّا ذِكْرَىٰ لِلْعَٰلَمِينَ", tafsir: `الأنبياء عليهم‌السلام الذين سبق ذكرهم ( الَّذِينَ هَدَى اللهُ ) أي ( 1) الزخرف : 82. ( 2) الزمر : 66. ( 3) البقرة : 64. فَبِهُداهُمُ اقْتَدِهْ قُلْ لا أَسْئَلُكُمْ عَلَيْهِ أَجْراً إِنْ هُوَ إِلاَّ ذِكْرى لِلْعالَمِينَ (90) هداهم الله ، والتكرار هنا مقدمة لقوله سبحانه ( فَبِهُداهُمُ ) يا رسول الله ( اقْتَدِهْ ) في أسلوب الدعوة والصبر على الأذى والاهتمام بالأمر ، وهذا كتسلية للرسول صلى‌الله‌عليه‌وآله‌وسلم وإشارة إلى أن الأنبياء السابقين ابتلوا بما ابتلي به ، بالإضافة إلى أن الاقتداء بهم في هدى الله سبحانه ، لا فيما هو من عند أنفسهم ، حتى يقال : كيف يؤمن النبي صلى‌الله‌عليه‌وآله‌وسلم بالاقتداء بمن هو دونه في الفضيلة. إنه قيام بالوظيفة لأمر الله سبحانه ولحسابه الخاص ، فالأجر منه وحده ( قُلْ ) يا رسول الله لمن تبلغهم : ( لا أَسْئَلُكُمْ عَلَيْهِ أَجْراً ) أي لا أطلب منكم على تبليغ الرسالة وأداء الوحي ثمنا وأجرة ( إِنْ هُوَ ) أي ما تبليغ الوحي ( إِلَّا ذِكْرى ) أي تذكيرا ( لِلْعالَمِينَ ) الذين هم في زماني وبعد زماني. وكونه تذكيرا باعتبار ما أودع في الإنسان من الفطرة الدالة على توحيده سبحانه. وهنا سؤال : كيف يمكن الجمع بين هذه الآية وبين قوله : ( لا أَسْئَلُكُمْ عَلَيْهِ أَجْراً إِلَّا الْمَوَدَّةَ فِي الْقُرْبى ) (1) . والجواب : إن إطلاق الأجر على المودة مجاز ، وقد كان إرجاع الناس إليهم لصالح الناس ، حيث إنهم الهداة المصلحون. [92] وحيث ذكر سبحانه أنه أعطى الأنبياء الكتاب ، ردّ على من زعم أنه سبحانه لم ينزل كتابا. فقد ورد أن حبرا من أحبار اليهود جاء إلى ( 1) الشورى : 24. وَما قَدَرُوا اللهَ حَقَّ قَدْرِهِ إِذْ قالُوا ما أَنْزَلَ اللهُ عَلى بَشَرٍ مِنْ شَيْءٍ قُلْ مَنْ أَنْزَلَ الْكِتابَ الَّذِي جاءَ بِهِ مُوسى نُوراً وَهُدىً لِلنَّاسِ تَجْعَلُونَهُ قَراطِيسَ تُبْدُونَها النبي صلى‌الله‌عليه‌وآله‌وسلم فقال له النبي : أنشدك بالذي أنزل التوراة على موسى أما تجد في التوراة أن الله سبحانه يبغض الحبر السمين ـ وكان اليهودي سمينا ـ فغضب وقال : ما أنزل الله على بشر من شيء. فقال له أصحابه : ويحك ولا موسى ؟ فأنزل الله هذه الآية (1) ( وَما قَدَرُوا اللهَ حَقَّ قَدْرِهِ ) أي ما عظموه سبحانه حق تعظيمه الذي يليق به ( إِذْ ) نسبوا إليه الكذب ف ( قالُوا ما أَنْزَلَ اللهُ عَلى بَشَرٍ مِنْ شَيْءٍ ) أي لم ينزل على رسول كتابا من السماء ، كما قال ذلك اليهودي. إن معنى عدم إرسال الرسل ، وإنزال الكتب أن الله خلق الخلق عبثا واعتباطا. ومن المعلوم أن نسبة العبث إلى شخص عادي موجب لإهانته وعدم تقديره ، فكيف بالله الحكيم العليم ؟! ( قُلْ ) يا رسول الله لإبطال كلامهم ف ( مَنْ أَنْزَلَ الْكِتابَ الَّذِي جاءَ بِهِ مُوسى ) عليه‌السلام أ ليست التوراة من إنزال الله تعالى ، وإنما ذكرها لكون طرف الكلام يهوديا ( نُوراً وَهُدىً ) أي في حال كون كتابه عليه‌السلام نور يهدي الناس إلى مناهج الحياة الصحيحة ، وهداية ( لِلنَّاسِ ) إلى الحق ( تَجْعَلُونَهُ ) أي تجعلون ذلك الكتاب ( قَراطِيسَ ) أي تكتبونه ، وهذا لزيادة التأكيد ، أي : فكيف تنكرون ما تلقيتموه أنتم بالقبول ، وكنتم تكتبونه في قراطيس باعتبار أنه كتاب سماوي منزل من عند الله سبحانه ؟ ( تُبْدُونَها ) أي تظهرون بعضها ، حيث كانوا يكتبون بعض الأحكام ( 1) بحار الأنوار : ج 9 ص 89. وَتُخْفُونَ كَثِيراً وَعُلِّمْتُمْ ما لَمْ تَعْلَمُوا أَنْتُمْ وَلا آباؤُكُمْ قُلِ اللهُ ثُمَّ ذَرْهُمْ فِي خَوْضِهِمْ يَلْعَبُونَ (91) وَهذا كِتابٌ أَنْزَلْناهُ مُبارَكٌ مُصَدِّقُ الَّذِي بَيْنَ يَدَيْهِ وَلِتُنْذِرَ أُمَّ الْقُرى وَمَنْ حَوْلَها وَالَّذِينَ يُؤْمِنُونَ بِالْآخِرَةِ يُؤْمِنُونَ بِهِ الموجودة في التوراة في أوراق ويعطونها بيد الناس ( وَتُخْفُونَ كَثِيراً ) من التوراة لأجل كونها خطرا على أموالهم أو جاههم ، أو فيه دلالة على الرسول صلى‌الله‌عليه‌وآله‌وسلم . ( وَعُلِّمْتُمْ ) أيها اليهود ببركة التوراة المنزلة على موسى ( ما لَمْ تَعْلَمُوا أَنْتُمْ وَلا آباؤُكُمْ ) فإنكم لو لا كتاب الله المنزل لم تكونوا تعلمون شيئا ، فكيف تنكرون إنزال الله الكتاب ، وتقولون : ( ما أَنْزَلَ اللهُ عَلى بَشَرٍ مِنْ شَيْءٍ ) ؟ ( قُلْ ) يا رسول الله : ( اللهَ ) أنزل الكتاب على موسى ( ثُمَّ ذَرْهُمْ ) أي دعهم ( فِي خَوْضِهِمْ يَلْعَبُونَ ) فهم وما خاضوا فيه من الباطل والكذب ، إنهم يلعبون بالدين ، فذرهم وما هم فيه` },
            { text: "وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِذْ قَالُوا۟ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٍ مِّن شَىْءٍ قُلْ مَنْ أَنزَلَ ٱلْكِتَٰبَ ٱلَّذِى جَآءَ بِهِۦ مُوسَىٰ نُورًا وَهُدًى لِّلنَّاسِ تَجْعَلُونَهُۥ قَرَاطِيسَ تُبْدُونَهَا وَتُخْفُونَ كَثِيرًا وَعُلِّمْتُم مَّا لَمْ تَعْلَمُوٓا۟ أَنتُمْ وَلَآ ءَابَآؤُكُمْ قُلِ ٱللَّهُ ثُمَّ ذَرْهُمْ فِى خَوْضِهِمْ يَلْعَبُونَ", tafsir: `` },
            { text: "وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌ مُّصَدِّقُ ٱلَّذِى بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا وَٱلَّذِينَ يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ يُؤْمِنُونَ بِهِۦ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ", tafsir: `كما أنزلنا الكتاب على موسى كذلك ( هذا ) القرآن ( كِتابٌ أَنْزَلْناهُ ) إليك يا رسول الله ( مُبارَكٌ ) يوجب البركة والسعادة ( مُصَدِّقُ ) الكتاب ( الَّذِي بَيْنَ يَدَيْهِ ) أي قبله ، من التوراة والإنجيل وسائر الكتب السماوية ، ومن المعلوم أن تصديق أصل الكتاب لا يلازم تصديق التحريفات التي طرأت عليه ، ( وَلِتُنْذِرَ ) يا رسول الله ( أُمَّ الْقُرى ) أي مكة ، وإنما سميت بها لأن الأرض دحيت من تحتها ( وَمَنْ حَوْلَها ) من سائر أهل الأرض ( وَالَّذِينَ يُؤْمِنُونَ بِالْآخِرَةِ ) من أهل الكتاب وغيرهم ( يُؤْمِنُونَ بِهِ ) أي بالقرآن المنزل عليك ، فإن وَهُمْ عَلى صَلاتِهِمْ يُحافِظُونَ (92) وَمَنْ أَظْلَمُ مِمَّنِ افْتَرى عَلَى اللهِ كَذِباً أَوْ قالَ أُوحِيَ إِلَيَّ وَلَمْ يُوحَ إِلَيْهِ شَيْءٌ وَمَنْ قالَ سَأُنْزِلُ مِثْلَ ما أَنْزَلَ اللهُ الإيمان بالآخرة يوجب خوفا في القلب ، ينبعث منه اتباع الحق أينما وجد ، وفيه تعريض بمن لا يؤمن من أهل الكتاب ، فإنه غير مؤمن بالآخرة ( وَهُمْ عَلى صَلاتِهِمْ يُحافِظُونَ ) فيؤدونها لأوقاتها ، فمن يترك الصلاة ليس بمؤمن بالآخرة والقرآن ، وإن ادّعى الإيمان. [94] وحيث كان الكلام حول الوحي ، ومن قال بعدم الوحي إطلاقا ، ناسب ذلك التنديد بمن قال بالوحي كذبا ، ( وَمَنْ أَظْلَمُ مِمَّنِ افْتَرى عَلَى اللهِ كَذِباً ) نزلت في ابن أبي سرح الذي استعمله عثمان على مصر وقد هدر رسول الله دمه وكان حسن الخط من كتابة الوحي فإذا قال له الرسول صلى‌الله‌عليه‌وآله‌وسلم : اكتب : ( أَنَّ اللهَ عَزِيزٌ حَكِيمٌ ) كتب : « إن الله عليم حكيم » وهكذا ، وكان يقول للمنافقين : إني أقول من نفسي مثل ما يجيء به. ثم ارتد كافرا إلى مكة وصار من الطلقاء يوم فتح مكة. ثم لا يخفى أن قوله سبحانه « ومن أظلم » على سبيل الحصر الإضافي ، كقوله : ( وَمَنْ أَظْلَمُ مِمَّنْ مَنَعَ مَساجِدَ اللهِ ) (1) ، وغيره. ( أَوْ قالَ أُوحِيَ إِلَيَّ وَلَمْ يُوحَ إِلَيْهِ شَيْءٌ ) كمسيلمة الكذاب الذي ادّعى النبوة كذبا ، وكغيره ممن ادّعى هذا المنصب افتراء ، نحو : ( وَمَنْ قالَ سَأُنْزِلُ مِثْلَ ما أَنْزَلَ اللهُ ) من الآيات أو الأحكام. في « المجمع » : قيل : المراد به عبد الله بن سعد بن أبي سرح ، ( 1) البقرة : 115. وَلَوْ تَرى إِذِ الظَّالِمُونَ فِي غَمَراتِ الْمَوْتِ وَالْمَلائِكَةُ باسِطُوا أَيْدِيهِمْ أَخْرِجُوا أَنْفُسَكُمُ الْيَوْمَ تُجْزَوْنَ عَذابَ الْهُونِ بِما كُنْتُمْ تَقُولُونَ عَلَى اللهِ غَيْرَ الْحَقِّ وَكُنْتُمْ عَنْ آياتِهِ أملى عليه رسول الله صلى‌الله‌عليه‌وآله‌وسلم ذات يوم : ( وَلَقَدْ خَلَقْنَا الْإِنْسانَ مِنْ سُلالَةٍ مِنْ طِينٍ ) ـ إلى قوله ـ ( ثُمَّ أَنْشَأْناهُ خَلْقاً آخَرَ ) (1) ، فجرى على لسان ابن أبي سرح : ( فَتَبارَكَ اللهُ أَحْسَنُ الْخالِقِينَ ) فأملاه عليه وقال : هكذا أنزل فارتد عدو الله وقال : لئن كان محمد صادقا فقد أوحي إليّ كما أوحي إليه ولئن كان كاذبا فلقد قلت كما قال (2) . ( وَلَوْ تَرى ) يا رسول الله ( إِذِ الظَّالِمُونَ فِي غَمَراتِ الْمَوْتِ ) أي في شدائد الموت عند النزع ، كأن الموت بشدائده يغمرهم مرة فمرة ، كما يغمر الماء الغريق ( وَالْمَلائِكَةُ ) القابضة لأرواحهم ( باسِطُوا أَيْدِيهِمْ ) لقبض أرواحهم بأبشع الوسائل يضربون وجوههم وأدبارهم ، قائلين لهم : ( أَخْرِجُوا أَنْفُسَكُمُ ) من أجسادكم ، وهذا للإذلال والإهانة ، وإلا فليس خروج أنفسهم بإمكانهم ، بل بقدرة الله تعالى ( الْيَوْمَ تُجْزَوْنَ ) أيها الظالمون ( عَذابَ الْهُونِ ) فإنه ليس عذابا جسديا فقط بل معه ذلة وهوان ( بِما كُنْتُمْ تَقُولُونَ عَلَى اللهِ غَيْرَ الْحَقِ ) أي جازاكم بعذاب الهون بسبب مقالتكم الكاذبة على الله حيث كنتم تقولون : « أوحي إلينا ولم يوح إليكم » ومعنى « على الله » أي بالنسبة إليه سبحانه ( وَ ) بما ( كُنْتُمْ عَنْ آياتِهِ ) ودلائله ( 1) المؤمنون : 13 ـ 15. ( 2) مجمع البيان : ج 4 ص 111. تَسْتَكْبِرُونَ (93) وَلَقَدْ جِئْتُمُونا فُرادى كَما خَلَقْناكُمْ أَوَّلَ مَرَّةٍ وَتَرَكْتُمْ ما خَوَّلْناكُمْ وَراءَ ظُهُورِكُمْ وَما نَرى مَعَكُمْ شُفَعاءَكُمُ الَّذِينَ زَعَمْتُمْ أَنَّهُمْ فِيكُمْ شُرَكاءُ لَقَدْ تَقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنْكُمْ ما كُنْتُمْ تَزْعُمُونَ (94) ( تَسْتَكْبِرُونَ ) فلا تخضعون لأحكامه وأنبيائه ، وجواب « لو » محذوف للتهويل ، أي : لو رأيت ذلك لرأيت أمرا فظيعا مريعا. [95] وهنا يوجّه الباري سبحانه كلامه إليهم ( وَلَقَدْ جِئْتُمُونا ) أيها الظالمون ( فُرادى ) أي في حال كونكم وحدانا لا مال لكم ولا مدافع ، بل واحدا واحدا ( كَما خَلَقْناكُمْ أَوَّلَ مَرَّةٍ ) حين جئتم إلى الدنيا ( وَتَرَكْتُمْ ما خَوَّلْناكُمْ ) أي ما أعطيناكم من المال والأقرباء والخدم ( وَراءَ ظُهُورِكُمْ ) في دار الدنيا ، فإن الإنسان باعتبار إقباله على الآخرة تكون الدنيا وراء ظهره ( وَما نَرى مَعَكُمْ شُفَعاءَكُمُ ) الذين اتخذتموهم لأنفسكم شفعاء يشفعون لكم يوم القيامة ( الَّذِينَ زَعَمْتُمْ أَنَّهُمْ فِيكُمْ شُرَكاءُ ) أي الأصنام التي كان المشركون يزعمون أنها شركاء الله سبحانه في الخلق والرزق وقضاء الحوائج ، وقد كان المشركون يقولون : إنّ هذه الأصنام تشفع لنا يوم القيامة. وورد أن سبب نزول هذه الآية أن النضر قال : سوف يشفع لي اللّات والعزّى. ( لَقَدْ تَقَطَّعَ ) أيها الظالمون ( بَيْنَكُمْ ) وبين الأصنام فلا مواصلة تنفع للشفاعة ( وَضَلَّ عَنْكُمْ ) أي ضاع وتلاشى ( ما كُنْتُمْ تَزْعُمُونَ ) من الآلهة المزعومة فلا تجلب نفعا ولا تدفع خيرا. [96] إن أصنامكم لا تشترك مع الله في الخلق ولا في أي شيء من الشؤون إِنَّ اللهَ فالِقُ الْحَبِّ وَالنَّوى يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَمُخْرِجُ الْمَيِّتِ مِنَ الْحَيِّ ذلِكُمُ اللهُ فَأَنَّى تُؤْفَكُونَ (95) فالِقُ الْإِصْباحِ وَجَعَلَ اللَّيْلَ سَكَناً وَالشَّمْسَ وَالْقَمَرَ حُسْباناً ذلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ (96) بل ( إِنَّ اللهَ ) وحده ( فالِقُ الْحَبِّ وَالنَّوى ) أي يشق الحب اليابس الميت ويخرج منه النبات ويشق نواة التمر فيخرج منها النخل ( يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ ) فالنبات حي يخرجه من الحبة التي لا حياة فيها ، والفرخ حيّ يخرجه من البيض الميت ، والولد الحيّ يخرجه من الأم الميتة ، والبعوض وأشباهه يخرجه من الماء الميت ، وهكذا ( وَمُخْرِجُ الْمَيِّتِ مِنَ الْحَيِ ) كالحبة من النبات ، والبيض من الدجاج ، والجنين الميت من الأم الحية ، والفضلات الميتة من الحيّ ، وكأن التغيّر في العبارة « يخرج » و « مخرج » للتفنّن في العبارة الذي هو نوع من أنواع البلاغة ( ذلِكُمُ اللهُ ) أي ذلك الذي يفعل كل ذلك ـ أيها البشر ـ هو الله وحده ( فَأَنَّى تُؤْفَكُونَ ) أي تصرفون عن الحق إلى الباطل.` },
            { text: "وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ قَالَ أُوحِىَ إِلَىَّ وَلَمْ يُوحَ إِلَيْهِ شَىْءٌ وَمَن قَالَ سَأُنزِلُ مِثْلَ مَآ أَنزَلَ ٱللَّهُ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِى غَمَرَٰتِ ٱلْمَوْتِ وَٱلْمَلَٰٓئِكَةُ بَاسِطُوٓا۟ أَيْدِيهِمْ أَخْرِجُوٓا۟ أَنفُسَكُمُ ٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى ٱللَّهِ غَيْرَ ٱلْحَقِّ وَكُنتُمْ عَنْ ءَايَٰتِهِۦ تَسْتَكْبِرُونَ", tafsir: `` },
            { text: "وَلَقَدْ جِئْتُمُونَا فُرَٰدَىٰ كَمَا خَلَقْنَٰكُمْ أَوَّلَ مَرَّةٍ وَتَرَكْتُم مَّا خَوَّلْنَٰكُمْ وَرَآءَ ظُهُورِكُمْ وَمَا نَرَىٰ مَعَكُمْ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمْتُمْ أَنَّهُمْ فِيكُمْ شُرَكَٰٓؤُا۟ لَقَد تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنكُم مَّا كُنتُمْ تَزْعُمُونَ", tafsir: `` },
            { text: "إِنَّ ٱللَّهَ فَالِقُ ٱلْحَبِّ وَٱلنَّوَىٰ يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَمُخْرِجُ ٱلْمَيِّتِ مِنَ ٱلْحَىِّ ذَٰلِكُمُ ٱللَّهُ فَأَنَّىٰ تُؤْفَكُونَ", tafsir: `` },
            { text: "فَالِقُ ٱلْإِصْبَاحِ وَجَعَلَ ٱلَّيْلَ سَكَنًا وَٱلشَّمْسَ وَٱلْقَمَرَ حُسْبَانًا ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ", tafsir: `أي يشق عمود الصبح عن ظلمة الليل ، ويخرج الضياء من الظلمة ( وَجَعَلَ اللَّيْلَ سَكَناً ) تسكنون فيه وتهدؤون عن العمل إذا أظلم ( وَ ) جعل ( الشَّمْسَ وَالْقَمَرَ حُسْباناً ) تجريان في أفلاكهما بحساب دقيق ، و « حسبان » مصدر ، وكونهما حسبانا أي مصدري حساب وتوقيت ، نحو : « زيد عدل » ، مما حمل المصدر على الذات مبالغة ، فمن الشمس تتولد الأيام ، ومن القمر تتولد الشهور والأعوام ( ذلِكَ ) المذكور من فلق الإصباح وجعل الليل سكنا والشمس والقمر حسبانا ( تَقْدِيرُ الْعَزِيزِ ) في سلطانه ( الْعَلِيمِ ) وَهُوَ الَّذِي جَعَلَ لَكُمُ النُّجُومَ لِتَهْتَدُوا بِها فِي ظُلُماتِ الْبَرِّ وَالْبَحْرِ قَدْ فَصَّلْنَا الْآياتِ لِقَوْمٍ يَعْلَمُونَ (97) وَهُوَ الَّذِي أَنْشَأَكُمْ مِنْ نَفْسٍ واحِدَةٍ فَمُسْتَقَرٌّ وَمُسْتَوْدَعٌ قَدْ فَصَّلْنَا الْآياتِ لِقَوْمٍ يَفْقَهُونَ (98) وَهُوَ الَّذِي أَنْزَلَ مِنَ السَّماءِ ماءً فَأَخْرَجْنا بِهِ بمصالح العباد ، فأي شيء يرتبط بأصنامكم أيها الضالون.` },
            { text: "وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهْتَدُوا۟ بِهَا فِى ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ قَدْ فَصَّلْنَا ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ", tafsir: `أيها البشر ( النُّجُومَ ) في السماء ( لِتَهْتَدُوا بِها فِي ظُلُماتِ الْبَرِّ وَالْبَحْرِ ) فإن الإنسان يعرف طريقه من النجم في الليالي ، فمن قصد مدينة نحو المشرق جعل النجم المشرقي أمامه ، ومن قصد مدينة نحو المغرب ، جعله خلفه ، وهكذا ( قَدْ فَصَّلْنَا الْآياتِ ) الدالة على الخالق وصفاته ( لِقَوْمٍ يَعْلَمُونَ ) أي لهم علم ومعرفة بالأوضاع.` },
            { text: "وَهُوَ ٱلَّذِىٓ أَنشَأَكُم مِّن نَّفْسٍ وَٰحِدَةٍ فَمُسْتَقَرٌّ وَمُسْتَوْدَعٌ قَدْ فَصَّلْنَا ٱلْـَٔايَٰتِ لِقَوْمٍ يَفْقَهُونَ", tafsir: `أي خلقكم وأبدعكم ( مِنْ نَفْسٍ واحِدَةٍ ) هي آدم عليه‌السلام ومن فضل طينته خلقت حواء عليها‌السلام ، إنه سبحانه القادر لمثل هذا الأمر العظيم فلكم مستقر في بطون الأمهات ( وَمُسْتَوْدَعٌ ) في أصلاب الآباء ، وإنما سمي ذلك مستودعا لأن المني يبقى قليلا في الصلب حتى ينزل ، فهو أشبه بالوديعة ( قَدْ فَصَّلْنَا الْآياتِ ) أي الأدلة والحجج ( لِقَوْمٍ يَفْقَهُونَ ) أي يفهمون الأدلة ، كي يعلمون أن الله سبحانه هو الذي صنع كل ذلك.` },
            { text: "وَهُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَىْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا نُّخْرِجُ مِنْهُ حَبًّا مُّتَرَاكِبًا وَمِنَ ٱلنَّخْلِ مِن طَلْعِهَا قِنْوَانٌ دَانِيَةٌ وَجَنَّٰتٍ مِّنْ أَعْنَابٍ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُشْتَبِهًا وَغَيْرَ مُتَشَٰبِهٍ ٱنظُرُوٓا۟ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَيَنْعِهِۦٓ إِنَّ فِى ذَٰلِكُمْ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ", tafsir: `هو المطر ، والمراد بالسماء جهة العلو ، فإن ما علاك فأظلك هو السماء ـ في لغة العرب ـ ( فَأَخْرَجْنا بِهِ نَباتَ كُلِّ شَيْءٍ فَأَخْرَجْنا مِنْهُ خَضِراً نُخْرِجُ مِنْهُ حَبًّا مُتَراكِباً وَمِنَ النَّخْلِ مِنْ طَلْعِها قِنْوانٌ دانِيَةٌ وَجَنَّاتٍ مِنْ أَعْنابٍ وَالزَّيْتُونَ وَالرُّمَّانَ مُشْتَبِهاً وَغَيْرَ مُتَشابِهٍ انْظُرُوا إِلى ثَمَرِهِ إِذا أَثْمَرَ وَيَنْعِهِ نَباتَ كُلِّ شَيْءٍ ) أي أخرجنا بسبب الماء نبات كل شيء قابل للإنبات من مختلف أقسام النباتات ( فَأَخْرَجْنا مِنْهُ ) أي من الماء ، والتكرار ، لأنه أجمل أولا ، ثم أريد التفصيل ، أو الضمير عائد إلى النبات ، فإن النبت أولا ليس أخضر ، وإنما أبيض صغير ثم يصير أخضر ( خَضِراً ) هو بمعنى أخضر ، أي نخرج من ذلك زرعا رطبا أخضر ( نُخْرِجُ مِنْهُ ) من ذلك الزرع الأخضر ( حَبًّا مُتَراكِباً ) قد تركّب بعضه على بعض كحب الحنطة والشعير ( وَ ) يخرج ( مِنَ النَّخْلِ مِنْ طَلْعِها ) بدل « من النخل » ( قِنْوانٌ ) أي أعذاق الرطب ، فإن « قنوان » : جمع « قنو » بكسر القاف وضمها ، وهو « العذق » بالكسر ( دانِيَةٌ ) أي قريبة التناول ( وَ ) أخرجنا منه ( جَنَّاتٍ ) أي بساتين ( مِنْ أَعْنابٍ ) جمع « عنب » ( وَ ) أخرجنا منه ( الزَّيْتُونَ وَالرُّمَّانَ ) أي شجريهما ( مُشْتَبِهاً وَغَيْرَ مُتَشابِهٍ ) فبعض الأشجار والأثمار والأوراق والأزهار والحبات متشابهة وبعضها غير متشابهة ، في اللون والطعم والحجم والخاصية وغيرها. والاختلاف بين لفظي « مشتبه ومتشابه » من أحسن أنواع البلاغة ، لتطابق اللفظ والخارج ( انْظُرُوا ) أيها الناس ( إِلى ثَمَرِهِ ) أي ثمر كل واحد من المذكورات ( إِذا أَثْمَرَ ) فإن في ذلك دلالة عجيبة على الصانع تعالى ( وَ ) انظروا إلى ( يَنْعِهِ ) أي نضجه إذ نضج ، فإن من نظر إلى ذلك نظر تأمل واعتبار ، عرف عظيم إِنَّ فِي ذلِكُمْ لَآياتٍ لِقَوْمٍ يُؤْمِنُونَ (99) وَجَعَلُوا لِلَّهِ شُرَكاءَ الْجِنَّ وَخَلَقَهُمْ وَخَرَقُوا لَهُ بَنِينَ وَبَناتٍ بِغَيْرِ عِلْمٍ سُبْحانَهُ وَتَعالى عَمَّا يَصِفُونَ (100) بَدِيعُ السَّماواتِ وَالْأَرْضِ الصنعة وجليل الخلقة ، ودقيق الحكمة ، و « ينع » في اللغة بمعنى « النضج » وقيل : جمع « يانع » ؛ كصحب وصاحب ( إِنَّ فِي ذلِكُمْ ) أي فيما تقدم من الخلقة ( لَآياتٍ لِقَوْمٍ يُؤْمِنُونَ ) بالحقائق ، ويتجنبون السخافة. [101] إن الله هو خالق كل شيء وهو الإله الواحد الذي لا شريك له ( وَ ) لكن الكفار ( جَعَلُوا لِلَّهِ شُرَكاءَ الْجِنَ ) فقالوا بأن لله شركاء في الألوهية هم من الجن ( وَ ) الحال أنه سبحانه هو الذي ( خَلَقَهُمْ ) أي خلق الجن ، فكيف يكون المخلوق شريكا مع الخالق في الألوهية ( وَخَرَقُوا ) أي جعلوا ، ولا يخفى ما في التعبير بلفظ « خرقوا » من اللطافة. ( لَهُ ) تعالى ( بَنِينَ وَبَناتٍ ) فقد قال اليهود : عزير ابن الله ، وقالوا : نحن أبناء الله ، وقالت النصارى : المسيح ابن الله ، وجعل المشركون الملائكة بنات الله ، كما قال سبحانه : ( وَجَعَلُوا الْمَلائِكَةَ الَّذِينَ هُمْ عِبادُ الرَّحْمنِ إِناثاً ) (1) ، ( بِغَيْرِ عِلْمٍ ) فإن ذلك منهم كان ظنا وتوهما ( سُبْحانَهُ ) منصوب بفعل محذوف ، أي : « أنزهه تنزيها له » ( وَتَعالى ) أي تقدس وترفع ( عَمَّا يَصِفُونَ ) أي الأوصاف التي يلصقونها بساحة قدسه ، من جعل الشريك والأولاد. [102] إنه وحده هو ( بَدِيعُ ) أي مبدع ( السَّماواتِ وَالْأَرْضِ ) وخالقهما بلا ( 1) الزخرف : 20. أَنَّى يَكُونُ لَهُ وَلَدٌ وَلَمْ تَكُنْ لَهُ صاحِبَةٌ وَخَلَقَ كُلَّ شَيْءٍ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ (101) ذلِكُمُ اللهُ رَبُّكُمْ لا إِلهَ إِلاَّ هُوَ خالِقُ كُلِّ شَيْءٍ فَاعْبُدُوهُ وَهُوَ عَلى كُلِّ شَيْءٍ وَكِيلٌ (102) لا تُدْرِكُهُ الْأَبْصارُ وَهُوَ يُدْرِكُ الْأَبْصارَ وَهُوَ اللَّطِيفُ الْخَبِيرُ (103) شريك أو ظهير ، وهذا ردّ على من جعل له شريكا ( أَنَّى ) أي كيف ( يَكُونُ لَهُ وَلَدٌ وَ ) الحال أنه تعالى ( لَمْ تَكُنْ لَهُ صاحِبَةٌ ) أي زوجة ؟ وهذا رد لمن جعل له أولادا ( وَخَلَقَ كُلَّ شَيْءٍ ) فهو الخالق المطلق ، ( وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ ) فهو العالم المطلق.` },
            { text: "وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ ٱلْجِنَّ وَخَلَقَهُمْ وَخَرَقُوا۟ لَهُۥ بَنِينَ وَبَنَٰتٍۭ بِغَيْرِ عِلْمٍ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَصِفُونَ", tafsir: `` },
            { text: "بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٌ وَلَمْ تَكُن لَّهُۥ صَٰحِبَةٌ وَخَلَقَ كُلَّ شَىْءٍ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ", tafsir: `` },
            { text: "ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَآ إِلَٰهَ إِلَّا هُوَ خَٰلِقُ كُلِّ شَىْءٍ فَٱعْبُدُوهُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ", tafsir: `أي ذلك المذكور له الصفات المتقدمة هو ( اللهُ ) تعالى ، و « كم » للخطاب إلى السامعين ( رَبُّكُمْ لا إِلهَ إِلَّا هُوَ ) فلا شريك له ( خالِقُ كُلِّ شَيْءٍ ) فلا شيء خارج من خلقه ، حتى يكون له شريكا ( فَاعْبُدُوهُ ) وحده ( وَهُوَ عَلى كُلِّ شَيْءٍ وَكِيلٌ ) أي حفيظ ومدبّر وقائم ، فلا حافظ غيره ، ولا قائم بالأمر أحد سواه.` },
            { text: "لَّا تُدْرِكُهُ ٱلْأَبْصَٰرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَٰرَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ", tafsir: `فإنه سبحانه ليس بجسم حتى يكون مرئيا ، وهذا لا فرق فيه بين الدنيا والآخرة ، فهو لا يبصر في الدنيا ولا يبصر في الآخرة ( وَهُوَ يُدْرِكُ الْأَبْصارَ ) روعي في الكلام التجانس اللفظي ، وإلا فهو يدرك كل شيء الأبصار وغيرها ( وَهُوَ اللَّطِيفُ ) لا يراد به اللطف بالمعنى في الأجسام ، المراد به النافذ في الأجسام ، والرقيق ، وما أشبه ، بل من باب « خذ الغايات واترك المبادئ » فعلمه نافذ في الأشياء ، وقدرته سارية في الأكوان ( الْخَبِيرُ ) العالم بكل شيء. ( قَدْ جاءَكُمْ بَصائِرُ مِنْ رَبِّكُمْ فَمَنْ أَبْصَرَ فَلِنَفْسِهِ وَمَنْ عَمِيَ فَعَلَيْها وَما أَنَا عَلَيْكُمْ بِحَفِيظٍ (104) وَكَذلِكَ نُصَرِّفُ الْآياتِ وَلِيَقُولُوا دَرَسْتَ وَلِنُبَيِّنَهُ لِقَوْمٍ يَعْلَمُونَ (105) اتَّبِعْ ما أُوحِيَ إِلَيْكَ مِنْ رَبِّكَ لا إِلهَ إِلاَّ` },
            { text: "قَدْ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمْ فَمَنْ أَبْصَرَ فَلِنَفْسِهِۦ وَمَنْ عَمِىَ فَعَلَيْهَا وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ", tafsir: `أيها البشر ( بَصائِرُ مِنْ رَبِّكُمْ ) « بصائر » جمع « بصيرة » وهي الدلالة البيّنة التي يبصر بها الشيء ، أي جاءتكم دلالات من قبل الله سبحانه ، على الأصول ، والأحكام ( فَمَنْ أَبْصَرَ ) أي من تبيّن هذه الدلالات ونظر فيها نظر معتبر بصير ( فَلِنَفْسِهِ ) فإنه يعود خير ذلك إلى ذاته وشخصه ( وَمَنْ عَمِيَ ) عنها فلم ينظر فيها وأعرض عنها ( فَعَلَيْها ) أي أن وبال الإعراض يعود على نفسه ( وَما أَنَا ) المراد بالضمير الرسول صلى‌الله‌عليه‌وآله‌وسلم ( عَلَيْكُمْ ) أيها الناس ( بِحَفِيظٍ ) أحفظكم عن الخطأ والانحراف ، وإنما أنا مبلغ مرشد ، من آمن فلنفسه ومن ضل فعليها.` },
            { text: "وَكَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَٰتِ وَلِيَقُولُوا۟ دَرَسْتَ وَلِنُبَيِّنَهُۥ لِقَوْمٍ يَعْلَمُونَ", tafsir: `أي مثل تصريفنا الآيات من ذي قبل ( نُصَرِّفُ ) هذه ( الْآياتِ ) نرسلها ونبيّنها ( وَلِيَقُولُوا دَرَسْتَ ) أي يقول الكفار : درست هذه الآيات وتعلمتها من غيرك ، كما كانوا ينسبون القرآن إلى تعلمه صلى‌الله‌عليه‌وآله‌وسلم من الراهب في طريق الشام ، أو من سلمان ، أو من بعض اليهود ( وَلِنُبَيِّنَهُ ) أي نوضّح ما تقدم من الآيات ( لِقَوْمٍ يَعْلَمُونَ ) أي للعلماء الذين يعلمون الآيات ، فإن هؤلاء هم المنتفعون بالآيات ، ولذا خصّهم بالذكر.` },
            { text: "ٱتَّبِعْ مَآ أُوحِىَ إِلَيْكَ مِن رَّبِّكَ لَآ إِلَٰهَ إِلَّا هُوَ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ", tafsir: `يا رسول الله ( ما أُوحِيَ إِلَيْكَ مِنْ رَبِّكَ ) وهو ( لا إِلهَ إِلَّا هُوَ وَأَعْرِضْ عَنِ الْمُشْرِكِينَ (106) وَلَوْ شاءَ اللهُ ما أَشْرَكُوا وَما جَعَلْناكَ عَلَيْهِمْ حَفِيظاً وَما أَنْتَ عَلَيْهِمْ بِوَكِيلٍ (107) وَلا تَسُبُّوا الَّذِينَ يَدْعُونَ مِنْ دُونِ اللهِ فَيَسُبُّوا اللهَ عَدْواً بِغَيْرِ عِلْمٍ هُوَ ) وذر الأصنام والأوثان ، فإن صاحب الدعوة لا يبالي بما قاله المغرضون ، ولا يضره انحراف المنحرفين ( وَأَعْرِضْ عَنِ الْمُشْرِكِينَ ) فلا تتعرض لهم ، وليس المراد عدم دعائهم إلى الإسلام ، أو عدم القتال معهم ، بل معناه : « أعرض عن أقوالهم وطريقتهم » ، وهذا كما يقال : « أعرض عن فلان » يراد عدم الاهتمام بقوله والاعتناء بشأنه ، وأنه لا بد من سلوك الطريق المستقيم أحبّ أم كره.` },
            { text: "وَلَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكُوا۟ وَمَا جَعَلْنَٰكَ عَلَيْهِمْ حَفِيظًا وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ", tafsir: `أن يكرههم على عدم الشرك ( ما أَشْرَكُوا ) ولكن الدنيا دنيا اختبار وامتحان ، وإنما يريهم الله سبحانه الطريق ، فمن شاء آمن ومن شاء أشرك ( وَما جَعَلْناكَ ) يا رسول الله ( عَلَيْهِمْ حَفِيظاً ) تحفظهم عن الشرك ، حتى يكون إثم الشرك عليك ( وَما أَنْتَ عَلَيْهِمْ بِوَكِيلٍ ) أي لست بموكل عليهم في ذلك ، وإنما عليك البلاغ والإنذار ، ولعل الفرق بين الحفيظ والوكيل ، أن الحفيظ هو الذي يحفظ الشيء عن الضرر ، والوكيل هو الذي يناط به أمره ، فيجب عليه دفع الضرر عنه وجلب النفع إليه ، فهو أعم من الحفيظ.` },
            { text: "وَلَا تَسُبُّوا۟ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّوا۟ ٱللَّهَ عَدْوًۢا بِغَيْرِ عِلْمٍ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ثُمَّ إِلَىٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا۟ يَعْمَلُونَ", tafsir: `أيها المسلمون الآلهة ( الَّذِينَ يَدْعُونَ ) ها الكفار ( مِنْ دُونِ اللهِ ) أي سوى الله ( فَيَسُبُّوا اللهَ ) مقابلة بالمثل ( عَدْواً ) أي ظلما ، بمعنى التعدي عن الحق ( بِغَيْرِ عِلْمٍ ) فإنهم جاهلون بالله ، وإلا لماذا كَذلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ثُمَّ إِلى رَبِّهِمْ مَرْجِعُهُمْ فَيُنَبِّئُهُمْ بِما كانُوا يَعْمَلُونَ (108) وَأَقْسَمُوا بِاللهِ جَهْدَ أَيْمانِهِمْ لَئِنْ جاءَتْهُمْ آيَةٌ لَيُؤْمِنُنَّ بِها قُلْ إِنَّمَا الْآياتُ عِنْدَ اللهِ كانوا يسبونه ، ويتخذون آلهة سواه ؟ ( كَذلِكَ ) الاعتقاد بالآلهة الباطلة ( زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ) فإن كل إنسان يرى عمله حسنا ، ولو تفكر وقارن رأى الصحيح من عمله وأباطيله. ونسبة التزيين إلى الله سبحانه لأنه هو الذي يخالف الخلق وسبب الأسباب ، وذلك للامتحان ، وليتبين من يخالف نفسه ومن يتبع هواها ( ثُمَّ إِلى رَبِّهِمْ مَرْجِعُهُمْ ) فإن الجميع يرجعون إلى حساب الله سبحانه ، وثوابه وعقابه ( فَيُنَبِّئُهُمْ ) أي يخبرهم ( بِما كانُوا يَعْمَلُونَ ) من الأعمال الحسنة والقبيحة ، ومعنى ذلك أنه يجازيهم بأعمالهم ، كما تقول لابنك العاصي : « أخبرك بما عملت .. . » تريد التهديد والوعيد. وهنا سؤال : كيف نهى الله عن سبّ الأصنام ، وفي القرآن كثير من القدح فيهم ؟ والجواب : إن الفرق بين سبّ الحكيم وسبّ الجاهل أن الأول يعرف موقع السب ، بخلاف الثاني ، كما لو نهى القاضي عن ضرب الناس ، ورأينا أنه يضرب بنفسه لحدّ أو قصاص ، فإن الأمرين لا يتنافيان.` },
            { text: "وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَتْهُمْ ءَايَةٌ لَّيُؤْمِنُنَّ بِهَا قُلْ إِنَّمَا ٱلْـَٔايَٰتُ عِندَ ٱللَّهِ وَمَا يُشْعِرُكُمْ أَنَّهَآ إِذَا جَآءَتْ لَا يُؤْمِنُونَ", tafsir: `أي حلف الكفار ( بِاللهِ جَهْدَ أَيْمانِهِمْ ) أي أيمانهم الغليظة ( لَئِنْ جاءَتْهُمْ آيَةٌ ) أي معجزة خارقة حسب ما طلبوا من مقترحاتهم ( لَيُؤْمِنُنَّ بِها ) أي بتلك الآية ( قُلْ ) يا رسول الله لهم : ( إِنَّمَا الْآياتُ ) الخارقة ( عِنْدَ اللهِ ) ومن لدنه ، وليس لدي منها شيء ، وَما يُشْعِرُكُمْ أَنَّها إِذا جاءَتْ لا يُؤْمِنُونَ (109) وَنُقَلِّبُ أَفْئِدَتَهُمْ وَأَبْصارَهُمْ كَما لَمْ يُؤْمِنُوا بِهِ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِي طُغْيانِهِمْ يَعْمَهُونَ (110) فإن عرف الله الصلاح في الإتيان بها أظهرها ، وإن عرف الصلاح في عدم الإتيان لم يأت بها ( وَما يُشْعِرُكُمْ ) أيها المؤمنون ( أَنَّها ) أي الآيات ( إِذا جاءَتْ لا يُؤْمِنُونَ ) كما جاءت الآيات من قبل فلم يؤمنوا. والسر أن المعاند لا تفيده الآية ، والطالب للحق تكفيه ما تقدم من الآيات ، فإنزال الآيات المقترحة لا فائدة فيها.` },
            { text: "وَنُقَلِّبُ أَفْـِٔدَتَهُمْ وَأَبْصَٰرَهُمْ كَمَا لَمْ يُؤْمِنُوا۟ بِهِۦٓ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ", tafsir: `جمع « فؤاد » وهو القلب ( وَأَبْصارَهُمْ ) جمع « بصر » وهو العين ( كَما لَمْ يُؤْمِنُوا بِهِ ) أي بالقرآن ( أَوَّلَ مَرَّةٍ ) فإنهم جوزوا بإنكارهم أول الأمر الذي استلزم عنادهم وتماديهم في غيهم ، بأن أزعجت نفوسهم ، فجعلت قلوبهم تخفق ، وأبصارهم تتحرك زائغة ، كما هو شأن كل مبطل أمام الحق أنه لا يدري ما يصنع ، وعينه تتلفت هنا وهناك تبحث في الأرض والسماء عن طريق المهرب والخلاص من الأزمة التي وقع فيها ( وَنَذَرُهُمْ ) أي ندعهم ( فِي طُغْيانِهِمْ ) الذي طغوا وتعدوا فيه الحق ( يَعْمَهُونَ ) يتردّدون في الحيرة. و قد روي أنهم لما طلبوا الآيات ، أراد النبي أن يسأل ربه بتلك الآيات ، فجاء جبرئيل وقال : إن شئت أصبح الصفا ذهبا ، ولكن إن لم يصدقوا ، عذّبوا ، وإن شئت تركتهم حتى يتوب تائبهم ، فقال رسول الله صلى‌الله‌عليه‌وآله‌وسلم : بل أتركهم حتى يتوب تائبهم (1) . فأنزل الله تعالى هذه الآية. ( 1) بحار الأنوار : ج 9 ص 91. تقريب القران الى الأذهان من آية 112 من سورة الأنعام إلى آية 88 من سورة الأعراف بسم الله الرّحمن الرّحيم الحمد لله رب العالمين ، والصلاة والسلام على أشرف الأنبياء والمرسلين محمد المصطفى وعترته الطاهرين وَلَوْ أَنَّنا نَزَّلْنا إِلَيْهِمُ الْمَلائِكَةَ وَكَلَّمَهُمُ الْمَوْتى وَحَشَرْنا عَلَيْهِمْ كُلَّ شَيْءٍ قُبُلاً ما كانُوا لِيُؤْمِنُوا إِلاَّ أَنْ يَشاءَ اللهُ وَلكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ (111) وَكَذلِكَ جَعَلْنا لِكُلِّ نَبِيٍّ عَدُوًّا شَياطِينَ الْإِنْسِ وَالْجِنِّ [112] ثم بيّن سبحانه أنّ هؤلاء معاندين لا يريدون بالآيات إلا الاقتراح ، ولو أنزلت إليهم لم يكونوا مؤمنين ( وَلَوْ أَنَّنا نَزَّلْنا إِلَيْهِمُ الْمَلائِكَةَ ) حتّى يرونهم مشاهدة ، ويشهدون لك بالرسالة ( وَكَلَّمَهُمُ الْمَوْتى ) أي أحيينا الأموات حتّى تكلّمهم ( وَحَشَرْنا ) أي جمعنا ( عَلَيْهِمْ كُلَّ شَيْءٍ قُبُلاً ) أي مقابلة ومعاينة ، بأن جئنا لهم بما طلبوا من الآيات ، أو المراد : جمعنا حواليهم الأشياء الكونية ، بأن يأتيهم الشجر والحجر والماء والحيوان ، وكان ذلك لبيان حشر صور مدهشة مرعبة ( ما كانُوا لِيُؤْمِنُوا ) لعنادهم وإصرارهم ( إِلَّا أَنْ يَشاءَ اللهُ ) أن يجبرهم على الإيمان ، ولكن الله لا يشاء ذلك لأنه خلاف الحكمة ( وَلكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ ) أنهم لو أوتوا بكل آية لم يؤمنوا ، بل يزعمون أنهم يؤمنون إن رأوا ، لجهلهم بعنادهم الكامن في نفوسهم ، الذي لا ينفع معه كل آية.` },
            { text: "وَلَوْ أَنَّنَا نَزَّلْنَآ إِلَيْهِمُ ٱلْمَلَٰٓئِكَةَ وَكَلَّمَهُمُ ٱلْمَوْتَىٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَىْءٍ قُبُلًا مَّا كَانُوا۟ لِيُؤْمِنُوٓا۟ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ", tafsir: `` },
            { text: "وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا شَيَٰطِينَ ٱلْإِنسِ وَٱلْجِنِّ يُوحِى بَعْضُهُمْ إِلَىٰ بَعْضٍ زُخْرُفَ ٱلْقَوْلِ غُرُورًا وَلَوْ شَآءَ رَبُّكَ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ", tafsir: `أي كما جعلنا لك يا رسول الله أعداء معاندين ( جَعَلْنا لِكُلِّ نَبِيٍّ عَدُوًّا ) ومعنى « الجعل » التخلية بينهم وبين اختيار العداوة ، وذلك اختبار لهم ، ورفعا لدرجات الأنبياء. وقد سبقت الإشارة إلى أن الأمور الاختيارية للناس تنسب إلى الله سبحانه باعتبار جعله الأسباب والتخلية بين الناس وبينها ، كما تنسب إلى فاعليها لأنهم السبب المريد لها ( شَياطِينَ الْإِنْسِ وَالْجِنِ ) نصب « شياطين » لأنه بدل « عدوا » يُوحِي بَعْضُهُمْ إِلى بَعْضٍ زُخْرُفَ الْقَوْلِ غُرُوراً وَلَوْ شاءَ رَبُّكَ ما فَعَلُوهُ فَذَرْهُمْ وَما يَفْتَرُونَ (112) وَلِتَصْغى إِلَيْهِ أَفْئِدَةُ الَّذِينَ لا يُؤْمِنُونَ بِالْآخِرَةِ وَلِيَرْضَوْهُ والمراد به الجنس لا الواحد ، والمراد بشياطين الإنس ، إما الشياطين الموكلة بالإنسان التي تغويه وتأمره بالقبائح ، وإما من قبيل « خاتم فضة » أي المردة من أفراد الإنسان ، فإن الشيطان بمعنى المارد من « شطن » ، قال الشاعر : أيا شاطن عصاه عكاه ثم يلقى في السجن والأغلال وهكذا يقال بالنسبة إلى شياطين الجن ( يُوحِي بَعْضُهُمْ إِلى بَعْضٍ ) أي يوسوس خفية ( زُخْرُفَ الْقَوْلِ ) أي : القول المزخرف ، الذي يستحسن ظاهره ولا حقيقة له ولا أصل ( غُرُوراً ) أي لأجل الغرور والإضلال ( وَلَوْ شاءَ رَبُّكَ ما فَعَلُوهُ ) أي لو أراد جبرهم على عدم هذه الأعمال العدوانية ضد الأنبياء ، لتمكّن من ذلك ، لكنه لم يشأ ، لأنه خلاف الحكمة ( فَذَرْهُمْ ) أي دعهم ( وَما يَفْتَرُونَ ) أي افتراؤهم ، فأعرض عنهم ، ولا تتعرّض لهم ، بل خذ طريقك ، وبلّغ رسالات ربك. [114] إن الشياطين يوحي بعضهم إلى بعض زخرف القول لأجل الغرور ( وَلِتَصْغى ) لأجل أن تميل ( إِلَيْهِ ) أي إلى هذا الوحي بزخرف القول ( أَفْئِدَةُ ) أي : قلوب ( الَّذِينَ لا يُؤْمِنُونَ بِالْآخِرَةِ ) فإنهم يوسوسون ليغروا الناس وليستميلوا أفئدة الكفار إلى مكائدهم ( وَلِيَرْضَوْهُ ) أي يرضى من لا يؤمن بالآخرة ، بالوحي والوسوسة ، بمعنى إرضاء الكفار وَلِيَقْتَرِفُوا ما هُمْ مُقْتَرِفُونَ (113) أَ فَغَيْرَ اللهِ أَبْتَغِي حَكَماً وَهُوَ الَّذِي أَنْزَلَ إِلَيْكُمُ الْكِتابَ مُفَصَّلاً وَالَّذِينَ آتَيْناهُمُ الْكِتابَ يَعْلَمُونَ أَنَّهُ مُنَزَّلٌ مِنْ رَبِّكَ بِالْحَقِّ فَلا تَكُونَنَّ مِنَ الْمُمْتَرِينَ (114) وَتَمَّتْ كَلِمَةُ رَبِّكَ بمنهجهم فلا يميلوا إلى الحق ( وَلِيَقْتَرِفُوا ) أي يرتكبوا من الكفر والمعاصي ( ما هُمْ مُقْتَرِفُونَ ) أي الشيء الذي يرتكبون. وجملة المعنى أن وسوسة الشياطين لأجل أن يغروا الناس ، ويستميلوا قلوبهم ، ويرضون عن طريقتهم ، ويرتكبون الآثام. [115] إنّ هناك شخصين متعاديين الرّسول صلى‌الله‌عليه‌وآله‌وسلم ، والذي لا يؤمن بالآخرة ، فمن الحكم بينهما ؟ وهنا يأتي الجواب أن الحكم هو الله وحده ، قل يا رسول الله لهؤلاء : ( أَ فَغَيْرَ اللهِ أَبْتَغِي حَكَماً ) أي أطلب سوى الله حاكما ( وَهُوَ ) أعلم الحكّام ( الَّذِي أَنْزَلَ إِلَيْكُمُ الْكِتابَ مُفَصَّلاً ) فيه ما يحتاج إليه الإنسان ، يفصل بين الحقّ والباطل ، ومعنى التفصيل : تبيين المعاني بما يوجب رفع الاشتباه. ومن المعلوم أن القادر على تنزيل الكتاب ، هو الذي يتخذ حكما ( وَالَّذِينَ آتَيْناهُمُ ) أي أعطيناهم ( الْكِتابَ ) من اليهود والنصارى ( يَعْلَمُونَ أَنَّهُ ) أي الكتاب وهو القرآن ( مُنَزَّلٌ مِنْ رَبِّكَ بِالْحَقِ ) وليس كلام الآدميين ، وتخصيص أهل الكتاب ، لأن علمهم يقتضي أن يعرفوا ذلك ، فإنه « إنما يعرف ذا الفضل من الناس ذووه » ( فَلا تَكُونَنَ ) يا رسول الله ( مِنَ الْمُمْتَرِينَ ) أي الشاكين. ومن المعلوم أن النبي لا يشك وإنما المراد به السامع ، وإن كان الخطاب موجها إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم .` },
            { text: "وَلِتَصْغَىٰٓ إِلَيْهِ أَفْـِٔدَةُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُوا۟ مَا هُم مُّقْتَرِفُونَ", tafsir: `` },
            { text: "أَفَغَيْرَ ٱللَّهِ أَبْتَغِى حَكَمًا وَهُوَ ٱلَّذِىٓ أَنزَلَ إِلَيْكُمُ ٱلْكِتَٰبَ مُفَصَّلًا وَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْلَمُونَ أَنَّهُۥ مُنَزَّلٌ مِّن رَّبِّكَ بِٱلْحَقِّ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ", tafsir: `` },
            { text: "وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلًا لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ", tafsir: `بالقرآن الكريم ، فما أراده الله سبحانه من صِدْقاً وَعَدْلاً لا مُبَدِّلَ لِكَلِماتِهِ وَهُوَ السَّمِيعُ الْعَلِيمُ (115) وَإِنْ تُطِعْ أَكْثَرَ مَنْ فِي الْأَرْضِ يُضِلُّوكَ عَنْ سَبِيلِ اللهِ إِنْ يَتَّبِعُونَ إِلاَّ الظَّنَّ وَإِنْ هُمْ إِلاَّ يَخْرُصُونَ (116) البشر ، تم بإنزال هذا الكتاب ، فليس وراءه كتاب آخر وكلمة أخرى ( صِدْقاً وَعَدْلاً ) فما فيه من الأخبار صدق لا يشوبه كذب ، وعدل لا يشوبه انحراف وزيغ ، فكل خبر يخالف إخباره عن المبدأ وعن المعاد وعن الرسالة وعن العدل وعن الخلافة وعن غيرها ، فهو كذب ، وكل حكم يخالف حكمه فهو زيغ وباطل ( لا مُبَدِّلَ لِكَلِماتِهِ ) فإن كلمات الله سبحانه هي الميزان لكل شيء فلا أحد يبدّل كلماته تعالى بالزيادة والنقصان ، تبديلا صحيحا ، ومن بدّل فهو المنحرف الضال ( وَهُوَ السَّمِيعُ ) لأقوال الناس ( الْعَلِيمُ ) بكل ما يفعلون فيجازيهم حسب أعمالهم وأقوالهم. [117] إن الميزان هو كلمات الله سبحانه ، فليس هناك حق فيما عدا ذلك ( وَ ) لذا ( إِنْ تُطِعْ أَكْثَرَ مَنْ فِي الْأَرْضِ يُضِلُّوكَ عَنْ سَبِيلِ اللهِ ) لأن غالب الناس كفّار أو ضالين ، فاتّباعهم موجب للكفر والضلال ، نعم هناك قلة لم يخل منهم زمان ، هم الآخذون بأحكام الله تعالى ، فإطاعتهم هي إطاعة الله ، ولا يوجب اتباعهم ضلالا وزيغا ( إِنْ يَتَّبِعُونَ ) أي ما يتّبع هؤلاء الكثرة من الناس ( إِلَّا الظَّنَ ) فليس لهم حجة وبرهان في كفرهم وضلالهم ، وإنما يرجّحون ظنّا ما يعتقدونه ، أو يعملون به ( وَإِنْ هُمْ ) أي ما هم ( إِلَّا يَخْرُصُونَ ) « الخرص » هو التخمين ، أي يقولون تخمينا لا اعتقادا وجزما. إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَنْ يَضِلُّ عَنْ سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ (117) فَكُلُوا مِمَّا ذُكِرَ اسْمُ اللهِ عَلَيْهِ إِنْ كُنْتُمْ بِآياتِهِ مُؤْمِنِينَ (118) وَما لَكُمْ أَلاَّ تَأْكُلُوا مِمَّا ذُكِرَ اسْمُ اللهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُمْ` },
            { text: "وَإِن تُطِعْ أَكْثَرَ مَن فِى ٱلْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ", tafsir: `` },
            { text: "إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ", tafsir: `يا رسول الله ( هُوَ أَعْلَمُ مَنْ يَضِلُّ عَنْ سَبِيلِهِ ) أي أعلم من سائر الناس بمن يسلك سبيل الضلال ، فقوله : ( إِنْ يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ ) صادر عن علم ومعرفة ، فإذا قال قائل : إن الكفار يعتقدون اعتقادا جازما بما أشركوا ، ويقولون ما يقولون عن قطع وجزم. فذلك غير عارف بأحوالهم ، وربك أعلم منه بهم ( وَهُوَ ) سبحانه ( أَعْلَمُ بِالْمُهْتَدِينَ ) الذين يسلكون سبيل الهدى والرشاد. [119] إذا فالحكم كله لله صغيرا كان أو كبيرا ، وقد كان الضّالّون يجادلون المسلمين في شؤون كثيرة ، ومنها أمر الذبائح ، فقد كانوا يأكلون الميتة ، ويتركون المذبوح ، وكانوا يحتجون على المسلمين قائلين : أ تأكلون أنتم ما قتلتم ولا تأكلون ما قتل ربّكم ؟ يريدون الاعتراض على المسلمين في عدم أكلهم للميتة ( فَكُلُوا ) أيها المسلمون ( مِمَّا ذُكِرَ اسْمُ اللهِ عَلَيْهِ ) عند الذبح ، واجتمع فيه سائر الشرائط ، والأمر للإباحة لأنه في مقام توهم الحضر ( إِنْ كُنْتُمْ بِآياتِهِ مُؤْمِنِينَ ) بأن آمنتم بالله ورسوله وصدّقتم بما جاء به الرسول صلى‌الله‌عليه‌وآله‌وسلم .` },
            { text: "فَكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤْمِنِينَ", tafsir: `` },
            { text: "وَمَا لَكُمْ أَلَّا تَأْكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا ٱضْطُرِرْتُمْ إِلَيْهِ وَإِنَّ كَثِيرًا لَّيُضِلُّونَ بِأَهْوَآئِهِم بِغَيْرِ عِلْمٍ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِٱلْمُعْتَدِينَ", tafsir: `أيها المسلمون ( أَلَّا تَأْكُلُوا ) أي شيء لكم في أن لا تأكلوا ( مِمَّا ذُكِرَ اسْمُ اللهِ عَلَيْهِ ) أي لم لا تأكلونه ، هل أن ذلك بزعم التحريم لأنكم تقتلونه ؟ ( وَقَدْ فَصَّلَ ) الله سبحانه ( لَكُمْ ) ما حَرَّمَ عَلَيْكُمْ إِلاَّ مَا اضْطُرِرْتُمْ إِلَيْهِ وَإِنَّ كَثِيراً لَيُضِلُّونَ بِأَهْوائِهِمْ بِغَيْرِ عِلْمٍ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِالْمُعْتَدِينَ (119) وَذَرُوا ظاهِرَ الْإِثْمِ وَباطِنَهُ إِنَّ الَّذِينَ يَكْسِبُونَ الْإِثْمَ سَيُجْزَوْنَ بِما كانُوا يَقْتَرِفُونَ (120) وَلا تَأْكُلُوا مِمَّا لَمْ يُذْكَرِ على لسان رسوله ( ما حَرَّمَ عَلَيْكُمْ ) وليست الذبيحة منها ( إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ ) فإنكم إذا اضطررتم إلى ما حرّم جاز لكم أكله بقدر الضرورة ( وَإِنَّ كَثِيراً ) من الناس ( لَيُضِلُّونَ بِأَهْوائِهِمْ ) فإلى حيث مال هواهم ساقوا الناس إليه ، فذلك يسبب إضلال الناس ( بِغَيْرِ عِلْمٍ ) يهديهم إلى الحق ، وإن تحريم المشركين للمذكى من هذا القبيل ، فإنه من الهوى ، لا من علم وصلاح ( إِنَّ رَبَّكَ ) يا رسول الله ( هُوَ أَعْلَمُ بِالْمُعْتَدِينَ ) الذين يتجاوزون الحق ، ويتعدونه إلى الباطل. [121] وفي عداد ذكر الحرام والحلال ، ينهى سبحانه عن كل محرم ( وَذَرُوا ) أيها المسلمون ( ظاهِرَ الْإِثْمِ وَباطِنَهُ ) أي ما ظهر من المعاصي وما بطن مما يؤتى به سرّا. قيل : إن أهل الجاهلية كانوا يقولون : إذا زنا الإنسان علنا كان آثما ، وإن زنا سرا لم يكن به بأس ، وبهذه المناسبة نزل هذا التعميم. ( إِنَّ الَّذِينَ يَكْسِبُونَ الْإِثْمَ ) أي يعملون بالمعاصي ( سَيُجْزَوْنَ ) أي يعاقبون ( بِما كانُوا يَقْتَرِفُونَ ) أي يرتكبون ، يقال : « اقترف الإثم » أي ارتكبه.` },
            { text: "وَذَرُوا۟ ظَٰهِرَ ٱلْإِثْمِ وَبَاطِنَهُۥٓ إِنَّ ٱلَّذِينَ يَكْسِبُونَ ٱلْإِثْمَ سَيُجْزَوْنَ بِمَا كَانُوا۟ يَقْتَرِفُونَ", tafsir: `` },
            { text: "وَلَا تَأْكُلُوا۟ مِمَّا لَمْ يُذْكَرِ ٱسْمُ ٱللَّهِ عَلَيْهِ وَإِنَّهُۥ لَفِسْقٌ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوْلِيَآئِهِمْ لِيُجَٰدِلُوكُمْ وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ", tafsir: `أيها المسلمون ( مِمَّا لَمْ يُذْكَرِ اسْمُ اللهِ عَلَيْهِ وَإِنَّهُ لَفِسْقٌ وَإِنَّ الشَّياطِينَ لَيُوحُونَ إِلى أَوْلِيائِهِمْ لِيُجادِلُوكُمْ وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ (121) أَ وَمَنْ كانَ مَيْتاً فَأَحْيَيْناهُ وَجَعَلْنا لَهُ نُوراً يَمْشِي بِهِ فِي النَّاسِ كَمَنْ مَثَلُهُ فِي الظُّلُماتِ لَيْسَ بِخارِجٍ مِنْها اسْمُ اللهِ عَلَيْهِ ) من الذبائح التي تذبح بدون التسمية ( وَإِنَّهُ لَفِسْقٌ ) وخروج عن طاعة الله تعالى ( وَإِنَّ الشَّياطِينَ لَيُوحُونَ ) أي يلقون خفية ( إِلى أَوْلِيائِهِمْ ) أي : في قلوب الذين اتبعوهم من الكفّار ( لِيُجادِلُوكُمْ ) قائلين : كيف تأكلون أيها المسلمون مما تقتلونه أنتم ولا تأكلون مما قتله الله ، وقتيل الله أولى بالأكل من قتيلكم ؟ ( وَإِنْ أَطَعْتُمُوهُمْ ) في أكل الميتة ( إِنَّكُمْ لَمُشْرِكُونَ ) لأنّ استحلال الميتة يوجب الكفر ، أو المراد : أنكم مثلهم ، لا مثل المؤمنين ، وهذا تعبير خطابي ، ولعل هذا أقرب لأن الاستحلال يوجب الكفر لا الشرك. [123] ثم ذكر سبحانه مثل الفريقين ، المؤمنين والكفار ( أَ وَمَنْ كانَ مَيْتاً ) بالكفر ( فَأَحْيَيْناهُ ) بالإيمان ، فإن الكفر شبه الموت حيث أن الكافر لا يأتي منه العمل الصالح ، والإيمان شبيه بالحياة لذلك ( وَجَعَلْنا لَهُ نُوراً ) منهاجا ينير به دروب الحياة ( يَمْشِي بِهِ ) أي بذلك النور ( فِي النَّاسِ ) فيعرف كيف يمشي وكيف يعاشر ، لا كالأعمى الذي يصطدم بهذا وذاك ( كَمَنْ مَثَلُهُ فِي الظُّلُماتِ ) أي كالكافر الذي هو مثل الشخص الذي لا نور له بل يمشي في الظلمات ، فمن في الظلمة شبّه بالكافر ، لأن ظلمة الكفر أشد من ظلمة عدم النور ، وإن الكافر لا يعرف سبيل الحياة السليمة ولذا فهو دائم المشاكل والمصادمات ( لَيْسَ بِخارِجٍ مِنْها ) إذ كَذلِكَ زُيِّنَ لِلْكافِرِينَ ما كانُوا يَعْمَلُونَ (122) وَكَذلِكَ جَعَلْنا فِي كُلِّ قَرْيَةٍ أَكابِرَ مُجْرِمِيها لِيَمْكُرُوا فِيها وَما يَمْكُرُونَ إِلاَّ بِأَنْفُسِهِمْ وَما يَشْعُرُونَ (123) الخروج من الظلمة لا يكون إلّا بانتهاج منهاج الإيمان ، وإلا فمن ظلمة إلى ظلمة ، وهذا سرّ ما يشاهد من ازدياد مشاكل العالم يوما بعد يوم ، وكلّما عدّلوا القوانين ، وبدّلوا المناهج لم يزدهم إلا مشكلة وإعضالا. والاستفهام إنكاري ، يراد أنهما ليسا بمتساويين ، بل الحي ذو النور أفضل من الميت في الظلمة ( كَذلِكَ ) أي كما زيّن للمؤمن الإيمان كذلك ( زُيِّنَ لِلْكافِرِينَ ما كانُوا يَعْمَلُونَ ) والذي زيّن لهم هو الشيطان والنفس الأمّارة بالسوء ، أو هو الله سبحانه بالمعنى المتقدم في قوله : ( كَذلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ) (1) ، أي خلّينا بينهم وبين ما يزيّن لهم عملهم.` },
            { text: "أَوَمَن كَانَ مَيْتًا فَأَحْيَيْنَٰهُ وَجَعَلْنَا لَهُۥ نُورًا يَمْشِى بِهِۦ فِى ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِى ٱلظُّلُمَٰتِ لَيْسَ بِخَارِجٍ مِّنْهَا كَذَٰلِكَ زُيِّنَ لِلْكَٰفِرِينَ مَا كَانُوا۟ يَعْمَلُونَ", tafsir: `` },
            { text: "وَكَذَٰلِكَ جَعَلْنَا فِى كُلِّ قَرْيَةٍ أَكَٰبِرَ مُجْرِمِيهَا لِيَمْكُرُوا۟ فِيهَا وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَ", tafsir: `أي كما تركنا الكفار في ظلمتهم يعمهون ، أو كما زيّنا لهم أعمالهم ، كذلك ( جَعَلْنا فِي كُلِّ قَرْيَةٍ أَكابِرَ مُجْرِمِيها ) فتركنا المجرمين على حالهم ( لِيَمْكُرُوا فِيها ) أي في القرية ، و « اللام » للعاقبة ، أي أن عاقبة تركنا إياهم مكرهم في القرية ، كقوله تعالى : ( فَالْتَقَطَهُ آلُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَناً ) (2) ، أو المراد : كما جعلنا ذا النور من المؤمنين ، كذلك جعلنا ذا الظلمة من المجرمين ( وَما يَمْكُرُونَ إِلَّا بِأَنْفُسِهِمْ ) فإن عاقبة مكرهم ووبال طغيانهم لا يرجع إلا إلى أنفسهم ( وَما يَشْعُرُونَ ) أي لا يدرون أن مكرهم يعود بالوبال ( 1) الأنعام : 109. ( 2) القصص : 9. وَإِذا جاءَتْهُمْ آيَةٌ قالُوا لَنْ نُؤْمِنَ حَتَّى نُؤْتى مِثْلَ ما أُوتِيَ رُسُلُ اللهِ اللهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسالَتَهُ سَيُصِيبُ الَّذِينَ أَجْرَمُوا صَغارٌ عِنْدَ اللهِ وَعَذابٌ شَدِيدٌ بِما كانُوا يَمْكُرُونَ (124) السيّئ إلى أنفسهم.` },
            { text: "وَإِذَا جَآءَتْهُمْ ءَايَةٌ قَالُوا۟ لَن نُّؤْمِنَ حَتَّىٰ نُؤْتَىٰ مِثْلَ مَآ أُوتِىَ رُسُلُ ٱللَّهِ ٱللَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُۥ سَيُصِيبُ ٱلَّذِينَ أَجْرَمُوا۟ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٌ شَدِيدٌۢ بِمَا كَانُوا۟ يَمْكُرُونَ", tafsir: `أي جاءت هؤلاء المجرمين ( آيَةٌ ) دلالة من الله على التوحيد والرسالة ( قالُوا لَنْ نُؤْمِنَ ) بهذه الآية وبما جاءت من أجله ( حَتَّى نُؤْتى مِثْلَ ما أُوتِيَ رُسُلُ اللهِ ) أي تأتي على أيدينا المعجزة ، ويوحى إلينا حتّى نكون كالرسل. قالوا : نزلت هذه الآية في الوليد بن المغيرة حيث قال للرسول صلى‌الله‌عليه‌وآله‌وسلم : والله لو كانت النبوة حقّا لكنت أولى بها منك ، لأني أكبر منك سنّا وأكثر منك مالا. وقيل : نزلت في أبي جهل حيث قال : زاحمنا بني عبد مناف في الشرف حتّى إذا صرنا كفرس رهان قالوا : منّا نبي يوحى إليه ، والله لا نؤمن به ولا نتبعه أبدا إلّا أن يأتينا وحي كما يأتيه. ( اللهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسالَتَهُ ) فإنه سبحانه أعلم من جميع الخلق بموضع الرسالة ، وليست هي بالمال والكبر والسن ، بل بالفضائل النفسية والقابلية المحلية ( سَيُصِيبُ الَّذِينَ أَجْرَمُوا ) أي عملوا الجرائم والموبقات ( صَغارٌ عِنْدَ اللهِ ) أي يكونوا أذلاء في الآخرة ، أو المراد : الأعم من الدنيا والآخرة ، ومعنى « عند الله » أن ذلك الصغار من عنده سبحانه ( وَعَذابٌ شَدِيدٌ بِما كانُوا يَمْكُرُونَ ) أي بسبب مكرهم ، فإن الصغار والعذاب جزاء لأعمالهم القبيحة. فَمَنْ يُرِدِ اللهُ أَنْ يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلامِ وَمَنْ يُرِدْ أَنْ يُضِلَّهُ يَجْعَلْ صَدْرَهُ ضَيِّقاً حَرَجاً كَأَنَّما يَصَّعَّدُ فِي السَّماءِ كَذلِكَ يَجْعَلُ اللهُ الرِّجْسَ عَلَى الَّذِينَ لا يُؤْمِنُونَ (125) [126] إن النبي صلى‌الله‌عليه‌وآله‌وسلم إذا جاء بالإسلام ، فمن حكّم عقله وآمن كان له من الله اللطف الخفي وشرح الصدر ، ومن أعرض وبقي على كفره أعرض سبحانه عنه وخلّى بينه وبين ما يفعل الشيطان به من تضييق الصدر ( فَمَنْ يُرِدِ اللهُ أَنْ يَهْدِيَهُ ) إلى الإيمان ( يَشْرَحْ صَدْرَهُ لِلْإِسْلامِ ) « الشرح » هو : التوسعة ، وهذا من باب التشبيه ، فكما أن الشيء الواسع له مجال أن ينفذ فيه شيء ، كذلك القلب المنشرح له محل أن ينفذ فيه الإسلام ( وَمَنْ يُرِدْ ) الله ( أَنْ يُضِلَّهُ ) لأنه ترك الإيمان وعاند ، فاقتضت المشيئة أن يخلى بينه وبين الضلال حتى تكون عاقبة أمره خسرا ، ويذوق وبال إعراضه ( يَجْعَلْ صَدْرَهُ ضَيِّقاً ) لا ينفذ فيه الإسلام ( حَرَجاً ) هو أضيق الضيق ـ كما قالوا ـ ( كَأَنَّما يَصَّعَّدُ فِي السَّماءِ ) فإن الإنسان إذا جرّ إلى السماء جرّا ، أحس بضيق شديد في صدره ، من جهة أن الهواء كلما لطف ، كان التنفس فيه أصعب ، ومعنى « في السماء » الولوج في طبقات السماء ، ليعطي معنى الشدة أكثر من « إلى » وكذاك التشديد في « يصّعّد » . ( كَذلِكَ ) أي كما ذكر من تضييق الصدر ( يَجْعَلُ اللهُ الرِّجْسَ ) وهو العذاب ، والصعوبة ، أو المراد به المعنى الظاهري له ، فإن للكفر رجسا ( عَلَى الَّذِينَ لا يُؤْمِنُونَ ) فالعقوبة لمن لا يؤمن أن يجعل صدره ضيقا حرجا ، فليس ذلك ابتداء منه سبحانه ، كما قد يزعم الناظر في أول الآية ، وهذا وَهذا صِراطُ رَبِّكَ مُسْتَقِيماً قَدْ فَصَّلْنَا الْآياتِ لِقَوْمٍ يَذَّكَّرُونَ (126) لَهُمْ دارُ السَّلامِ عِنْدَ رَبِّهِمْ وَهُوَ وَلِيُّهُمْ بِما كانُوا يَعْمَلُونَ (127) وَيَوْمَ يَحْشُرُهُمْ جَمِيعاً يا مَعْشَرَ الْجِنِّ قَدِ اسْتَكْثَرْتُمْ مِنَ الْإِنْسِ وَقالَ أَوْلِياؤُهُمْ مِنَ الْإِنْسِ كقولك : « إن من يريد خيره من أبنائي أعطه المال ، وإنّ من يريد شره أقطع عنه المال ، وهكذا أعمل بمن لا ينصاع إلى أوامري » .` },
            { text: "فَمَن يُرِدِ ٱللَّهُ أَن يَهْدِيَهُۥ يَشْرَحْ صَدْرَهُۥ لِلْإِسْلَٰمِ وَمَن يُرِدْ أَن يُضِلَّهُۥ يَجْعَلْ صَدْرَهُۥ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِى ٱلسَّمَآءِ كَذَٰلِكَ يَجْعَلُ ٱللَّهُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يُؤْمِنُونَ", tafsir: `` },
            { text: "وَهَٰذَا صِرَٰطُ رَبِّكَ مُسْتَقِيمًا قَدْ فَصَّلْنَا ٱلْـَٔايَٰتِ لِقَوْمٍ يَذَّكَّرُونَ", tafsir: `أي الإسلام ( صِراطُ رَبِّكَ ) يا رسول الله ( مُسْتَقِيماً ) لا اعوجاج فيه ولا انحراف ، فمن لم يقبله لم يفرّ من الانحراف ، وإنما زاغ وانحرف ( قَدْ فَصَّلْنَا الْآياتِ ) أي بيّناها وشرحناها ( لِقَوْمٍ يَذَّكَّرُونَ ) أصله « يتذكّرون » ثم أدغمت التاء في الذال ، والمراد : أنه لمن يتذكّر ما أودع فيه من الفطرة الآمرة باتباع الطريق القويم.` },
            { text: "لَهُمْ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمْ وَهُوَ وَلِيُّهُم بِمَا كَانُوا۟ يَعْمَلُونَ", tafsir: `أي للذين تذكروا وعرفوا الحق ( دارُ السَّلامِ ) وهي : الجنة ، فإنها دار السلامة التي لا حرب فيها ، ولا بغضاء ، ولا مرض ، ولا همّ ، ولا ما ينغّص العيش ( عِنْدَ رَبِّهِمْ ) أي أن تلك الدار عند كرامة الله ولطفه ، وفي ضمانه وعهده ( وَهُوَ ) أي الله سبحانه ( وَلِيُّهُمْ ) الذي يتولّى أمورهم ( بِما كانُوا يَعْمَلُونَ ) أي بسبب أعمالهم الصالحة واتّباع أوامره.` },
            { text: "وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا يَٰمَعْشَرَ ٱلْجِنِّ قَدِ ٱسْتَكْثَرْتُم مِّنَ ٱلْإِنسِ وَقَالَ أَوْلِيَآؤُهُم مِّنَ ٱلْإِنسِ رَبَّنَا ٱسْتَمْتَعَ بَعْضُنَا بِبَعْضٍ وَبَلَغْنَآ أَجَلَنَا ٱلَّذِىٓ أَجَّلْتَ لَنَا قَالَ ٱلنَّارُ مَثْوَىٰكُمْ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ", tafsir: `أي يجمعهم ، والضمير عائد إلى الجن والإنس ، الذين تقدم الكلام عنهم ، بأنهم يوحي بعضهم إلى بعض زخرف القول غرورا ، وأنه جعل لكل نبي عدوّا منهم ، وإذ يجمعون يقال لهم : ( يا مَعْشَرَ الْجِنِّ قَدِ اسْتَكْثَرْتُمْ مِنَ الْإِنْسِ ) أي اتّخذتم أتباعا كثيرين وَقالَ أَوْلِياؤُهُمْ مِنَ الْإِنْسِ رَبَّنَا اسْتَمْتَعَ بَعْضُنا بِبَعْضٍ وَبَلَغْنا أَجَلَنَا الَّذِي أَجَّلْتَ لَنا قالَ النَّارُ مَثْواكُمْ خالِدِينَ فِيها إِلاَّ ما شاءَ اللهُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ (128) وَكَذلِكَ نُوَلِّي بَعْضَ الظَّالِمِينَ بَعْضاً منهم واحتشدتم حشدا عظيما من التابعين الذين اتبعوكم في وساوسكم وغروركم. ولفظة « يوم » منصوبة ، ب « يقال » المقّدر ، ( وَقالَ أَوْلِياؤُهُمْ ) أي أتباع الجن ( مِنَ الْإِنْسِ ) الذين اتبعوهم وأخذوا بوساوسهم وإيحاءاتهم : ( رَبَّنَا اسْتَمْتَعَ بَعْضُنا بِبَعْضٍ ) فلقد كان الإغواء نأخذه متاعا واستمتاعا ، فإن الإنسان الذي لم يملأ فراغ قلبه الحقّ يطلب متعة يستمتع بها ، وما أجدر بالإغواء والإيحاء أن يملأ ذلك الفراغ ، وهذا كالاعتذار من الأتباع الإنسيين ، كما يقول أحد الناس إذا سئل عن عمله الباطل ؟ أنه اتخذه وسيلة للتسلية وسد الفراغ ( وَبَلَغْنا أَجَلَنَا ) أي الموت ( الَّذِي أَجَّلْتَ لَنا ) أي وقّتّه وجعلته مدة ، فقد أدركنا الموت ونحن في الاستمتاع ( قالَ ) الله تعالى : ( النَّارُ مَثْواكُمْ ) أي مقامكم ، و « الثواء » : الإقامة ، والضمير عائد إلى الجن والإنس ( خالِدِينَ فِيها ) أي في النار أبد الآبدين ( إِلَّا ما شاءَ اللهُ ) أن تنقطع النار وذلك بالنسبة إلى عصاة المؤمنين ( إِنَّ رَبَّكَ ) يا رسول الله ( حَكِيمٌ ) وبمقتضى حكمته جعل النار مثوى لهم ( عَلِيمٌ ) يعلم الصالح من الفاسد.` },
            { text: "وَكَذَٰلِكَ نُوَلِّى بَعْضَ ٱلظَّٰلِمِينَ بَعْضًۢا بِمَا كَانُوا۟ يَكْسِبُونَ", tafsir: `أي كما تقدم من الخلة بين الجن والإنس ، ليغوي بعضهم بعضا ، ( نُوَلِّي بَعْضَ الظَّالِمِينَ بَعْضاً ) فنجعل الظالم وليا بِما كانُوا يَكْسِبُونَ (129) يا مَعْشَرَ الْجِنِّ وَالْإِنْسِ أَ لَمْ يَأْتِكُمْ رُسُلٌ مِنْكُمْ يَقُصُّونَ عَلَيْكُمْ آياتِي وَيُنْذِرُونَكُمْ لِقاءَ يَوْمِكُمْ هذا قالُوا شَهِدْنا عَلى أَنْفُسِنا وَغَرَّتْهُمُ الْحَياةُ الدُّنْيا وَشَهِدُوا عَلى أَنْفُسِهِمْ أَنَّهُمْ كانُوا كافِرِينَ (130) ذلِكَ أَنْ لَمْ يَكُنْ رَبُّكَ مُهْلِكَ الْقُرى للظالم في الدنيا وفي الآخرة ( بِما كانُوا يَكْسِبُونَ ) أي بسبب كسبهم الأعمال السيئة وإعراضهم عن الحق. [131] ثم يخاطب الجن الذين أوحوا إلى الإنس وأضلوهم بهذا الخطاب : ( يا مَعْشَرَ الْجِنِّ وَالْإِنْسِ ) و « المعشر » هو الجماعة ( أَ لَمْ يَأْتِكُمْ رُسُلٌ مِنْكُمْ ) على وجه الاستفهام الإنكاري ، و « منكم » باعتبار أن الإنس والجن من مادة سفلية ، فبعضهم من بعض ، أو باعتبار أن الرسول صلى‌الله‌عليه‌وآله‌وسلم أرسل رسلا من الجن إليهم ( يَقُصُّونَ عَلَيْكُمْ ) أي يتلون عليكم ( آياتِي ) أي حججي ودلائلي ( وَيُنْذِرُونَكُمْ ) أي يخوفونكم ( لِقاءَ يَوْمِكُمْ هذا ) أي يوم القيامة ( قالُوا ) أي قالت الجن في جواب هذا الاستفهام : ( شَهِدْنا عَلى أَنْفُسِنا ) بما تستحق من العقاب حيث خالفنا وعصينا ، فإنّا معترفون بالجرائم ، ثم يقول سبحانه : ( وَغَرَّتْهُمُ الْحَياةُ الدُّنْيا ) أي تزيّنت لهم وأغوتهم ( وَشَهِدُوا عَلى أَنْفُسِهِمْ ) في الآخرة ( أَنَّهُمْ كانُوا كافِرِينَ ) في الدنيا فاستحقوا العقاب. [132] إن هؤلاء الجماعة الذين حكم عليهم بالنار لم يكن اعتباطا ، وإنما كان بعد الإنذار والتبليغ و ( ذلِكَ ) الإرسال والإنذار لأجل ( أَنْ لَمْ يَكُنْ ) أي لأنه ليس ( رَبُّكَ ) يا رسول الله ( مُهْلِكَ الْقُرى ) أي يهلك بِظُلْمٍ وَأَهْلُها غافِلُونَ (131) وَلِكُلٍّ دَرَجاتٌ مِمَّا عَمِلُوا وَما رَبُّكَ بِغافِلٍ عَمَّا يَعْمَلُونَ (132) وَرَبُّكَ الْغَنِيُّ ذُو الرَّحْمَةِ إِنْ يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنْ بَعْدِكُمْ ما يَشاءُ كَما أَنْشَأَكُمْ مِنْ ذُرِّيَّةِ قَوْمٍ آخَرِينَ (133) إِنَّ ما تُوعَدُونَ ويعذب أهل المدن ( بِظُلْمٍ وَأَهْلُها غافِلُونَ ) عن الدين والطريق ، بل إنما يهلكهم إذا أتمّ الحجة عليهم ، ثم خالفوا وعصوا. [133] ثم إنه ليس التعذيب اعتباطا بأن يحشرون جميعا في درجة واحدة ـ كما قد ينساق من الآيات السابقة ـ بل ( وَلِكُلٍ ) من المجرمين ، أو الأعم منهم ومن المطيعين ( دَرَجاتٌ ) أي مراتب خاصة بهم ( مِمَّا عَمِلُوا ) « من » للإنشاء ، أي : تنشأ تلك الدرجات من أعمالهم في الدنيا ( وَما رَبُّكَ ) يا رسول الله ( بِغافِلٍ عَمَّا يَعْمَلُونَ ) فلا يدري من عمل وما عمل ، بل كل شيء عنده محفوظ بقدره وخصوصياته. [134] إن هذه الأوامر وتلك العقوبات ، ليست لاحتياج الله سبحانه إلى هذه أو تلك ( وَرَبُّكَ ) يا رسول الله ( الْغَنِيُ ) الذي لا يحتاج إلى شيء إطلاقا ( ذُو الرَّحْمَةِ ) ومن رحمته جعل الأوامر ليرحم العباد بها ( إِنْ يَشَأْ يُذْهِبْكُمْ ) أي يهلككم أيها البشر ( وَيَسْتَخْلِفْ ) أي يجعل خليفة لكم وفي محلكم ( مِنْ بَعْدِكُمْ ) أي بعد الإذهاب بكم ( ما يَشاءُ ) من أنواع المخلوقات ( كَما أَنْشَأَكُمْ ) وأوجدكم ( مِنْ ذُرِّيَّةِ قَوْمٍ آخَرِينَ ) حيث أذهبهم وأتى بكم ، فإن ذلك عليه يسير.` },
            { text: "يَٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَٰتِى وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا قَالُوا۟ شَهِدْنَا عَلَىٰٓ أَنفُسِنَا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ", tafsir: `` },
            { text: "ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا غَٰفِلُونَ", tafsir: `` },
            { text: "وَلِكُلٍّ دَرَجَٰتٌ مِّمَّا عَمِلُوا۟ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ", tafsir: `` },
            { text: "وَرَبُّكَ ٱلْغَنِىُّ ذُو ٱلرَّحْمَةِ إِن يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنۢ بَعْدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوْمٍ ءَاخَرِينَ", tafsir: `` },
            { text: "إِنَّ مَا تُوعَدُونَ لَـَٔاتٍ وَمَآ أَنتُم بِمُعْجِزِينَ", tafsir: `أيها البشر من القيامة والحساب والثواب والعقاب لَآتٍ وَما أَنْتُمْ بِمُعْجِزِينَ (134) قُلْ يا قَوْمِ اعْمَلُوا عَلى مَكانَتِكُمْ إِنِّي عامِلٌ فَسَوْفَ تَعْلَمُونَ مَنْ تَكُونُ لَهُ عاقِبَةُ الدَّارِ إِنَّهُ لا يُفْلِحُ الظَّالِمُونَ (135) وَجَعَلُوا لِلَّهِ مِمَّا ذَرَأَ مِنَ الْحَرْثِ وَالْأَنْعامِ نَصِيباً فَقالُوا هذا لِلَّهِ ( لَآتٍ ) أي يأتي لا محالة ( وَما أَنْتُمْ بِمُعْجِزِينَ ) أي لستم تقدرون أن تسبّبوا عجزه سبحانه حتى لا يتمكن من إعادتكم والإتيان بكم لساحة الحساب.` },
            { text: "قُلْ يَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ", tafsir: `يا رسول الله لهؤلاء : ( يا قَوْمِ اعْمَلُوا عَلى مَكانَتِكُمْ ) أي منزلتكم ومقدار تمكّنكم من الدنيا ، وهذا الأمر للتهديد ، أي : اعملوا الكفر والمعاصي بما تتمكنون ( إِنِّي عامِلٌ ) بما أمرني الله سبحانه ـ فلكم دينكم ولي دين ـ ( فَسَوْفَ ) في الآخرة ( تَعْلَمُونَ ) جزاء أعمالكم ( مَنْ تَكُونُ لَهُ عاقِبَةُ الدَّارِ ) أي العاقبة المحمودة في دار السلام ، هل أنتم أم أنا ؟ لكن اعلموا أن عاقبة الدار لي ف ( إِنَّهُ لا يُفْلِحُ ) ولا يفوز بالسعادة ( الظَّالِمُونَ ) الذين ظلموا أنفسهم بالكفر والمعاصي. [137] ثم يعود السياق إلى معالجة العقيدة في بعض نواحيها فيحكي سبحانه ما كان يفعله أهل الجاهلية من تقسيم ما ينفقوه من الزرع والأنعام بين الله وبين الأصنام ( وَجَعَلُوا ) أي جعل الكفار ( لِلَّهِ مِمَّا ذَرَأَ ) أي خلق ( مِنَ الْحَرْثِ ) أي الزرع ( وَالْأَنْعامِ ) أي المواشي من الإبل والبقر والغنم ( نَصِيباً ) أي حظا وقسما ، وجعلوا للأصنام نصيبا ( فَقالُوا هذا ) القسم ( لِلَّهِ ) تعالى بِزَعْمِهِمْ وَهذا لِشُرَكائِنا فَما كانَ لِشُرَكائِهِمْ فَلا يَصِلُ إِلَى اللهِ وَما كانَ لِلَّهِ فَهُوَ يَصِلُ إِلى شُرَكائِهِمْ ( بِزَعْمِهِمْ ) وإنما نسبهم إلى الزعم لأنه لم يكن لله ، فإن الله لا يقبل الشيء الذي أشرك معه فيه ( وَهذا ) القسم ( لِشُرَكائِنا ) أي الأوثان ، الشركاء الذين نحن أشركناهم مع الله ـ وفي الإضافة تكفي أدنى ملابسة ، ككوكب الخرقاء ـ ( فَما كانَ لِشُرَكائِهِمْ ) من الأنعام والحرث ( فَلا يَصِلُ إِلَى اللهِ ) أي أن الله لا يقبله ، وكنّى بالإيصال لتشبيه المعقول بالمحسوس تقريبا للمعنى إلى الأذهان ( وَما كانَ لِلَّهِ ) بزعمهم ( فَهُوَ يَصِلُ إِلى شُرَكائِهِمْ ) وهذا مجاز ، أي أن الأصنام تنتفع بهذا النصيب من خلال ما يترسخ لها في قلوب المشركين من المكانة والاحترام ، أو المراد أنهم كانوا إذا خصصوا نصيبا للشركاء لا يأخذون منه لله شيئا ، أما الحصة المخصصة لله سبحانه فقد يأخذون منها ليوفروا المأخوذ مع حصة الأصنام. روي عن أهل البيت عليهم‌السلام : أن المشركين كانوا يعيّنون قسما من الحرث والأنعام لله وينفقونه على الضيوف والمساكين وقسما منهما لآلهتهم وينفقونه على سدنتها ويذبحون عندها ثم إن رأوا أن ما عيّنوا لله أزكى بدّلوه بما لآلهتهم ، وإن رأوا أن ما لآلهتهم أزكى تركوه لها حبا لآلهتهم وعللوا ذلك بأن الله غنيّ. و روي أيضا : أنه كان إذا اختلط ما جعل للأصنام بما جعل لله ردّوه ، وإذا اختلط ما جعل لله بما جعلوه للأصنام تركوه ، وقالوا : الله غني ، وإذا انخرق الماء الذي لله في الذي للأصنام لم يسدوه ، وإذا ساءَ ما يَحْكُمُونَ (136) وَكَذلِكَ زَيَّنَ لِكَثِيرٍ مِنَ الْمُشْرِكِينَ قَتْلَ أَوْلادِهِمْ شُرَكاؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا عَلَيْهِمْ دِينَهُمْ انخرق من الذي للأصنام في الذي لله سدوه وقالوا : الله غني .. فرد عليهم سبحانه بقوله : ( ساءَ ما يَحْكُمُونَ ) أي أن حكمهم بالتشريك أو عند الاختلاط ، والتزكية ، سيّئ ، فإن الله وإن كان غنيا ، لكن هذا العمل مخالف لجلال شأنه وعظيم كبريائه.` },
            { text: "وَجَعَلُوا۟ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلْحَرْثِ وَٱلْأَنْعَٰمِ نَصِيبًا فَقَالُوا۟ هَٰذَا لِلَّهِ بِزَعْمِهِمْ وَهَٰذَا لِشُرَكَآئِنَا فَمَا كَانَ لِشُرَكَآئِهِمْ فَلَا يَصِلُ إِلَى ٱللَّهِ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمْ سَآءَ مَا يَحْكُمُونَ", tafsir: `` },
            { text: "وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٍ مِّنَ ٱلْمُشْرِكِينَ قَتْلَ أَوْلَٰدِهِمْ شُرَكَآؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا۟ عَلَيْهِمْ دِينَهُمْ وَلَوْ شَآءَ ٱللَّهُ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ", tafsir: `أي كما جعل المشركون في الحرث والأنعام ما لا يجوز ، كذلك فعلوا بالنسبة إلى أولادهم ما لا يجوز ( زَيَّنَ لِكَثِيرٍ مِنَ الْمُشْرِكِينَ ) فاعل « زين » «شركاؤهم » أي أن الشياطين الذين اتخذهم المشركون شركاء لله زينوا لهم ( قَتْلَ أَوْلادِهِمْ ) مفعول « زين » ( شُرَكاؤُهُمْ ) فقد كان كثير من المشركين يعبدون الجن ، وهي توحي لهم بالأعمال السيئة. فقد كانوا يقتلون البنات خوفا من العار ، كما قال سبحانه : ( وَإِذا بُشِّرَ أَحَدُهُمْ بِالْأُنْثى ظَلَّ وَجْهُهُ مُسْوَدًّا وَهُوَ كَظِيمٌ* .. أَمْ يَدُسُّهُ فِي التُّرابِ ) (1) ، وقال : ( وَإِذَا الْمَوْؤُدَةُ سُئِلَتْ* بِأَيِّ ذَنْبٍ قُتِلَتْ ) (2) ، وكانوا يقتلون البنين خوف الفقر ، كما قال سبحانه : ( وَلا تَقْتُلُوا أَوْلادَكُمْ مِنْ إِمْلاقٍ ) (3) ، ( لِيُرْدُوهُمْ ) من « أراده » بمعنى : « أهلكه » أي أنه كانت غاية الشياطين ـ الشركاء ـ الذين زينوا للمشركين قتل أولادهم ، إرادة إهلاك الأولاد بالقتل ، وإهلاك الآباء بالذنب ( وَلِيَلْبِسُوا عَلَيْهِمْ دِينَهُمْ ) أي يخلطوا عليهم الحق بالباطل حتى ( 1) النحل : 59 و 60. ( 2) التكوير : 9 و 10. ( 3) الأنعام : 152. وَلَوْ شَاء اللّهُ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ (137) وَقالُوا هذِهِ أَنْعامٌ وَحَرْثٌ حِجْرٌ لا يَطْعَمُها إِلاَّ مَنْ نَشاءُ بِزَعْمِهِمْ وَأَنْعامٌ حُرِّمَتْ ظُهُورُها وَأَنْعامٌ لا يَذْكُرُونَ اسْمَ اللهِ عَلَيْهَا افْتِراءً عَلَيْهِ لا يعرفوا أحدهما من الآخر ، وفي الغالب يأتي أهل الباطل بضغث من الحق وضغث من الباطل ، حتى لا يصغر الحق ، فيتبعه الناس ( وَلَوْ شاءَ اللهُ ما فَعَلُوهُ ) أي ما قتلوا أولادهم ، ومشيئة الله إنما هي بجبرهم على الهدى ، لكنه لا يشاء لأن الدنيا خلقت للاختبار ( فَذَرْهُمْ ) أي دعهم واتركهم يا رسول الله ( وَما يَفْتَرُونَ ) أي افتراؤهم على الله سبحانه ، فقد كان المشركون ينسبون أباطيلهم إليه سبحانه ، و « ذرهم » تهديدا لهم ، لا أن معناه عدم وجوب ردعهم ونهيهم.` },
            { text: "وَقَالُوا۟ هَٰذِهِۦٓ أَنْعَٰمٌ وَحَرْثٌ حِجْرٌ لَّا يَطْعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعْمِهِمْ وَأَنْعَٰمٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَٰمٌ لَّا يَذْكُرُونَ ٱسْمَ ٱللَّهِ عَلَيْهَا ٱفْتِرَآءً عَلَيْهِ سَيَجْزِيهِم بِمَا كَانُوا۟ يَفْتَرُونَ", tafsir: `أي قال المشركون في قسم آخر من خزعبلاتهم : ( هذِهِ أَنْعامٌ وَحَرْثٌ ) أي مواش وزرع ( حِجْرٌ ) أي حرام ( لا يَطْعَمُها ) أي لا يأكلها ( إِلَّا مَنْ نَشاءُ ) وهي التي خصّصوها لأصنامهم فقد كانت خاصة للسدنة لا يشركهم فيها أحد ( بِزَعْمِهِمْ ) أي قد كان هذا التحريم زعما منهم ، إذ لم ينزل الله به من سلطان ( وَ ) عمدوا إلى قسم ثان من الأنعام فحجروها وقالوا : هذه ( أَنْعامٌ حُرِّمَتْ ظُهُورُها ) أي لا تركب ، لأنها نذرت للآلهة ، أو لأنها ولدت كذا ولدا ، أو لأنها حمت ظهرها ، من السائبة وأخواتها ، كما تقدم في سورة المائدة ( وَ ) عمدوا إلى قسم ثالث من الأنعام فهي ( أَنْعامٌ لا يَذْكُرُونَ اسْمَ اللهِ عَلَيْهَا ) عند الركوب ، أو عند الذبح ، أو لا يحجون عليها ، وقد كانوا ينسبون كل ذلك إلى الله سبحانه ( افْتِراءً عَلَيْهِ ) فقد كانوا كاذبين في سَيَجْزِيهِمْ بِما كانُوا يَفْتَرُونَ (138) وَقالُوا ما فِي بُطُونِ هذِهِ الْأَنْعامِ خالِصَةٌ لِذُكُورِنا وَمُحَرَّمٌ عَلى أَزْواجِنا وَإِنْ يَكُنْ مَيْتَةً فَهُمْ فِيهِ شُرَكاءُ سَيَجْزِيهِمْ وَصْفَهُمْ إِنَّهُ حَكِيمٌ عَلِيمٌ (139) قَدْ خَسِرَ الَّذِينَ قَتَلُوا أَوْلادَهُمْ سَفَهاً بِغَيْرِ عِلْمٍ وَحَرَّمُوا هذه النسب ( سَيَجْزِيهِمْ ) الله سبحانه ( بِما كانُوا يَفْتَرُونَ ) أي بسبب افترائهم على الله سبحانه كذبا وزورا.` },
            { text: "وَقَالُوا۟ مَا فِى بُطُونِ هَٰذِهِ ٱلْأَنْعَٰمِ خَالِصَةٌ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزْوَٰجِنَا وَإِن يَكُن مَّيْتَةً فَهُمْ فِيهِ شُرَكَآءُ سَيَجْزِيهِمْ وَصْفَهُمْ إِنَّهُۥ حَكِيمٌ عَلِيمٌ", tafsir: `أي قال المشركون في قسم آخر من أباطيلهم : ( ما فِي بُطُونِ هذِهِ الْأَنْعامِ ) من الأجنة ( خالِصَةٌ لِذُكُورِنا وَمُحَرَّمٌ عَلى أَزْواجِنا ) أي نسائنا ، إن كانت حية ( وَإِنْ يَكُنْ ) ما في بطون الأنعام ( مَيْتَةً ) بأن خرج الجنين ميتا ( فَهُمْ ) رجالا ونساء ( فِيهِ شُرَكاءُ ) يجوز للنساء أكله كما يجوز للرجال ( سَيَجْزِيهِمْ ) الله تعالى ( وَصْفَهُمْ ) أي هذا الوصف الذي كانوا يصفون به الجنين بالتحليل والتحريم و « وصف » منصوب بنزع الخافض ، أي « بوصفهم » ( إِنَّهُ ) سبحانه ( حَكِيمٌ ) يحكم عن حكمة ومصلحة ( عَلِيمٌ ) بما يصدر من هؤلاء ، فيجازيهم حسب المصلحة والحكمة. [141] ثم يجمع ذلك كله بقوله سبحانه : ( قَدْ خَسِرَ ) الكفار ( الَّذِينَ قَتَلُوا أَوْلادَهُمْ ) خوف العار أو الفقر أو للنذر ـ فقد كانوا ينذرون قتل الأولاد ـ ( سَفَهاً ) أي جهلا وسفاهة ، فإنهم اشتروا بذلك النار ( بِغَيْرِ عِلْمٍ ) بما يعملون ، فإنهم كانوا يزعمون صحة عملهم هذا ( وَحَرَّمُوا ما رَزَقَهُمُ اللهُ افْتِراءً عَلَى اللهِ قَدْ ضَلُّوا وَما كانُوا مُهْتَدِينَ (140) وَهُوَ الَّذِي أَنْشَأَ جَنَّاتٍ مَعْرُوشاتٍ وَغَيْرَ مَعْرُوشاتٍ وَالنَّخْلَ وَالزَّرْعَ مُخْتَلِفاً أُكُلُهُ وَالزَّيْتُونَ وَالرُّمَّانَ مُتَشابِهاً وَغَيْرَ مُتَشابِهٍ كُلُوا مِنْ ثَمَرِهِ إِذا أَثْمَرَ وَآتُوا حَقَّهُ يَوْمَ حَصادِهِ وَلا تُسْرِفُوا ما رَزَقَهُمُ اللهُ ) أي خسروا بتحريمهم قسما من الأنعام والحرث الذي زعموا أنه حجر لأصنامهم ( افْتِراءً عَلَى اللهِ ) حيث كانوا ينسبون ذلك إليه سبحانه ( قَدْ ضَلُّوا ) الطريق المستقيم ( وَما كانُوا مُهْتَدِينَ ) في تلك الأعمال.` },
            { text: "قَدْ خَسِرَ ٱلَّذِينَ قَتَلُوٓا۟ أَوْلَٰدَهُمْ سَفَهًۢا بِغَيْرِ عِلْمٍ وَحَرَّمُوا۟ مَا رَزَقَهُمُ ٱللَّهُ ٱفْتِرَآءً عَلَى ٱللَّهِ قَدْ ضَلُّوا۟ وَمَا كَانُوا۟ مُهْتَدِينَ", tafsir: `` },
            { text: "وَهُوَ ٱلَّذِىٓ أَنشَأَ جَنَّٰتٍ مَّعْرُوشَٰتٍ وَغَيْرَ مَعْرُوشَٰتٍ وَٱلنَّخْلَ وَٱلزَّرْعَ مُخْتَلِفًا أُكُلُهُۥ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهًا وَغَيْرَ مُتَشَٰبِهٍ كُلُوا۟ مِن ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَءَاتُوا۟ حَقَّهُۥ يَوْمَ حَصَادِهِۦ وَلَا تُسْرِفُوٓا۟ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ", tafsir: `الله ( الَّذِي أَنْشَأَ ) أي خلق وأبدع ( جَنَّاتٍ ) أي بساتين ( مَعْرُوشاتٍ ) أي مجعولات لها عروش من الكروم ( وَغَيْرَ مَعْرُوشاتٍ ) من الأشجار التي لا تحتاج إلى العروش بل هي قائمة على ساقها ( وَ ) أنشأ ( النَّخْلَ ) للتمر ( وَالزَّرْعَ ) من مختلف المزروعات في حال كون جميع ذلك ( مُخْتَلِفاً أُكُلُهُ ) أي ثمره الذي يؤكل ، والاختلاف في اللون والطعم والشكل والخواص ( وَ ) أنشأ ( الزَّيْتُونَ وَالرُّمَّانَ ) وذكرهما لكثرتهما في هذه البلاد في حال كون ذلك كله ، أو الأخيرين ( مُتَشابِهاً ) يشبه بعضه بعضا ( وَغَيْرَ مُتَشابِهٍ ) من حيث اللون والورق والشجر وغيرها ( كُلُوا ) أيها البشر ( مِنْ ثَمَرِهِ ) أي ثمر هذا المنشأ ( إِذا أَثْمَرَ ) فإن ذلك مباح لكم ( وَآتُوا حَقَّهُ ) أي الحق المجعول عليه ، وهو إعطاء الفقراء منه شيئا ، حفنة حفنة ، أو كفا كفا ( يَوْمَ حَصادِهِ ) أي جنيه وقطعه ( وَلا تُسْرِفُوا ) في باب ما رزقناكم ، إِنَّهُ لا يُحِبُّ الْمُسْرِفِينَ (141) وَمِنَ الْأَنْعامِ حَمُولَةً وَفَرْشاً كُلُوا مِمَّا رَزَقَكُمُ اللهُ وَلا تَتَّبِعُوا خُطُواتِ الشَّيْطانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ (142) ثَمانِيَةَ أَزْواجٍ مِنَ الضَّأْنِ اثْنَيْنِ وَمِنَ الْمَعْزِ اثْنَيْنِ قُلْ آلذَّكَرَيْنِ بأن تعطوا الجميع ، أو تصرفوه فيما لا يعني ، أو ما أشبه ( إِنَّهُ ) سبحانه ( لا يُحِبُّ الْمُسْرِفِينَ ) أي يكرههم.` },
            { text: "وَمِنَ ٱلْأَنْعَٰمِ حَمُولَةً وَفَرْشًا كُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ", tafsir: `أنشأ ( مِنَ الْأَنْعامِ ) الإبل والبقر والغنم ( حَمُولَةً ) هي الإبل التي يحمل عليها ، أو كل ما يحمل من الخيل والبغال والحمير والإبل ( وَفَرْشاً ) أي ما يفترش من جلودها كالغنم ، أو المراد بالفرش صغارها قبل أن تكون صالحة للحمل ، ( كُلُوا ) أيها البشر ( مِمَّا رَزَقَكُمُ اللهُ ) ولا تحرموا شيئا منها كما كان أهل الجاهلية يحرمون بعض الطيبات ( وَلا تَتَّبِعُوا خُطُواتِ الشَّيْطانِ ) كأن العاصي يضع قدمه حيث وضع الشيطان قدمه ( إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ ) أي واضح العداوة ، لأنه يسبب ذهاب دنياكم وآخرتكم. [144] ثم بيّن سبحانه أن ليس في شيء من الأنعام محرما ، وإنما ذلك اختلاق من الجهال ، إنه سبحانه أنشأ ( ثَمانِيَةَ أَزْواجٍ ) من الأنعام الثلاثة ، و « الزوج » يقع على الواحد الذي يقع معه الآخر ، وعلى الاثنين ، فالرجل زوج والمرأة زوج ، كما أن كليهما زوج ( مِنَ الضَّأْنِ ) وهي الشاة ( اثْنَيْنِ ) ذكر وأنثى و « اثنين » بدل من « ثمانية » ( وَمِنَ الْمَعْزِ ) وهي السخل ( اثْنَيْنِ ) ذكر وأنثى ( قُلْ ) يا رسول الله لهؤلاء الذين يحرمون بعض هذه الأقسام : ( آلذَّكَرَيْنِ ) دخلت همزة حَرَّمَ أَمِ الْأُنْثَيَيْنِ أَمَّا اشْتَمَلَتْ عَلَيْهِ أَرْحامُ الْأُنْثَيَيْنِ نَبِّئُونِي بِعِلْمٍ إِنْ كُنْتُمْ صادِقِينَ (143) وَمِنَ الْإِبِلِ اثْنَيْنِ وَمِنَ الْبَقَرِ اثْنَيْنِ قُلْ آلذَّكَرَيْنِ حَرَّمَ أَمِ الْأُنْثَيَيْنِ أَمَّا اشْتَمَلَتْ عَلَيْهِ أَرْحامُ الْأُنْثَيَيْنِ أَمْ كُنْتُمْ شُهَداءَ إِذْ وَصَّاكُمُ اللهُ بِهذا الاستفهام على همزة الوصل وفصل بينهما بالألف ، ولم تسقط همزة الوصل لئلّا يلتبس الاستفهام بالخبر وإن جاز الحذف لقرينة « أم » أي : هل أحد الذكرين من الضأن والمعز ( حَرَّمَ ) الله ( أَمِ ) إحدى ( الْأُنْثَيَيْنِ ) منها أم حرّم سبحانه ما ( اشْتَمَلَتْ عَلَيْهِ أَرْحامُ الْأُنْثَيَيْنِ ) ؟ أي الجنين الذي اشتمل عليه رحم الضأن والمعز ، فإنهم كانوا يقولون : إن ما في بطون هذه الأنعام محرم على الإناث وخالص للذكور ( نَبِّئُونِي ) أي : أخبروني أيها الكفار المحرمون لبعض هذه الأقسام ( بِعِلْمٍ ) أي : عن دليل عملي ، لا الأوهام والظنون ( إِنْ كُنْتُمْ صادِقِينَ ) في تحريم الله سبحانه لهذه الأقسام.` },
            { text: "ثَمَٰنِيَةَ أَزْوَٰجٍ مِّنَ ٱلضَّأْنِ ٱثْنَيْنِ وَمِنَ ٱلْمَعْزِ ٱثْنَيْنِ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ نَبِّـُٔونِى بِعِلْمٍ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `` },
            { text: "وَمِنَ ٱلْإِبِلِ ٱثْنَيْنِ وَمِنَ ٱلْبَقَرِ ٱثْنَيْنِ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ أَمْ كُنتُمْ شُهَدَآءَ إِذْ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَا فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا لِّيُضِلَّ ٱلنَّاسَ بِغَيْرِ عِلْمٍ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ", tafsir: `ذكر وأنثى ، وهو عطف على ( « مِنَ الضَّأْنِ اثْنَيْنِ » وَمِنَ الْبَقَرِ اثْنَيْنِ ) ذكر وأنثى ، وهذا تمام الثمانية ( قُلْ ) يا رسول الله لهؤلاء : ( آلذَّكَرَيْنِ ) أي : هل أن واحدا من الذكرين ( حَرَّمَ ) الله سبحانه ( أَمِ ) إحدى ( الْأُنْثَيَيْنِ ) من الإبل والبقر ؟ ( أَمَّا اشْتَمَلَتْ عَلَيْهِ أَرْحامُ الْأُنْثَيَيْنِ ) ؟ من الجنسين ـ كما تقدم ـ ( أَمْ كُنْتُمْ شُهَداءَ ) أي : حضورا ـ مقابل « نبئوني بعلم » ـ أي : هل علمتم أو حضرتم التحريم ؟ ( إِذْ وَصَّاكُمُ اللهُ بِهذا ) التحريم ، وإذ لا دليل لكم لا سماعا ولا فَمَنْ أَظْلَمُ مِمَّنِ افْتَرى عَلَى اللهِ كَذِباً لِيُضِلَّ النَّاسَ بِغَيْرِ عِلْمٍ إِنَّ اللهَ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ (144) قُلْ لا أَجِدُ فِي ما أُوحِيَ إِلَيَّ مُحَرَّماً عَلى طاعِمٍ يَطْعَمُهُ إِلاَّ أَنْ يَكُونَ مَيْتَةً أَوْ دَماً مَسْفُوحاً أَوْ لَحْمَ خِنزِيرٍ فَإِنَّهُ رِجْسٌ أَوْ فِسْقاً حضورا ( فَمَنْ أَظْلَمُ مِمَّنِ افْتَرى عَلَى اللهِ كَذِباً ) فإن من ينسب إلى الله سبحانه حكما بالكذب هو أظلم الناس لنفسه. وقد تقدم أن التفضيل هنا نسبي لا واقعي ( لِيُضِلَّ النَّاسَ بِغَيْرِ عِلْمٍ ) فيوقع الناس في الضلالة ، ولا علم له بصحة عمله ، بل يعلم بطلانه أو يظن ما يقوله ظنا ( إِنَّ اللهَ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ ) بل يتركهم وشأنهم حتى يتمادوا في غيهم وضلالهم.` },
            { text: "قُل لَّآ أَجِدُ فِى مَآ أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِمٍ يَطْعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيْتَةً أَوْ دَمًا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍ فَإِنَّهُۥ رِجْسٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ رَبَّكَ غَفُورٌ رَّحِيمٌ", tafsir: `يا رسول الله لهؤلاء الكفار : ( لا أَجِدُ فِي ما أُوحِيَ إِلَيَ ) أي ما أوحى به الله سبحانه في باب تحريم هذه الأشياء التي تتناولونها أنتم والتي تحرمونها ( مُحَرَّماً عَلى طاعِمٍ يَطْعَمُهُ ) أي على آكل يأكله ، فكل ما تذكرون تحريمه باطل ، بل هو حلال طيب ( إِلَّا أَنْ يَكُونَ مَيْتَةً ) غير مذكّى شرعا ( أَوْ دَماً مَسْفُوحاً ) أي مصبوبا ، وإنما خص المسفوح بالذكر ، لأن ما اختلط باللحم مما يعسر تخليصه منه محلل مباح ( أَوْ لَحْمَ خِنزِيرٍ ) ومن المعلوم أن ذكر اللحم من باب المثال ، وإلا فشحمه وسائر أجزائه أيضا حرام ( فَإِنَّهُ ) أي كل واحد من هذه المحرمات ، أو خصوص لحم الخنزير ( رِجْسٌ ) أي قذر منفور منه ( أَوْ فِسْقاً ) عطف على « ميتة » أي لحما يكون أكله فسقا ، لأنه خلاف إباحة الله ، وذلك أُهِلَّ لِغَيْرِ اللهِ بِهِ فَمَنِ اضْطُرَّ غَيْرَ باغٍ وَلا عادٍ فَإِنَّ رَبَّكَ غَفُورٌ رَحِيمٌ (145) وَعَلَى الَّذِينَ هادُوا حَرَّمْنا كُلَّ ذِي ظُفُرٍ وَمِنَ الْبَقَرِ وَالْغَنَمِ حَرَّمْنا عَلَيْهِمْ شُحُومَهُما إِلاَّ ما حَمَلَتْ ظُهُورُهُما أَوِ الْحَوايا أَوْ مَا اخْتَلَطَ بِعَظْمٍ ذلِكَ جَزَيْناهُمْ بِبَغْيِهِمْ فيما ( أُهِلَّ لِغَيْرِ اللهِ بِهِ ) أي : ذكر عليه اسم الأصنام حين القتل ، ولم يذكر عليه اسم الله ( فَمَنِ اضْطُرَّ ) إلى تناول أحد هذه المحرمات ( غَيْرَ باغٍ ) في أكله ( وَلا عادٍ ) من التعدي ، بأن لم يكن طالبا لأكل الحرام ، ومتعديا حد سدّ الرمق ـ وقد تقدم المعنى في سورة المائدة ـ ( فَإِنَّ رَبَّكَ ) يا رسول الله ( غَفُورٌ ) يغفر لمن تناول مضطرا ( رَحِيمٌ ) بالعباد حيث رخّص لهم ذلك ، وقد تقدم عدم المنافاة بين عدم المعصية والغفران. [147] كان هذا الحكم بالنسبة إلى غير اليهود ( وَ ) أما ( عَلَى الَّذِينَ هادُوا ) فقد ( حَرَّمْنا كُلَّ ذِي ظُفُرٍ ) من دابة ليست مشقوقة الرجل كالإبل والنّعام ، أو الطير كالإوز والبط ( وَمِنَ الْبَقَرِ وَالْغَنَمِ حَرَّمْنا عَلَيْهِمْ شُحُومَهُما ) كل شحم في بدنهما ( إِلَّا ما حَمَلَتْ ظُهُورُهُما ) أي الشحم الذي كان على ظهرهما ( أَوِ ) ما حملته ( الْحَوايا ) من الشحم ، وهي : جمع « حاوية » ، والمراد به الأمعاء ، وهو الشحم الملتف بالأمعاء ( أَوْ مَا اخْتَلَطَ بِعَظْمٍ ) كشحم الجنب والإلية ونحوهما ( ذلِكَ ) التحريم عليهم لم يكن لأجل ضرر في المحرمات عليهم بل جزيناهم بسبب بغيهم أي ظلمهم حيث كانوا يكفرون بآيات وَإِنَّا لَصادِقُونَ (146) فَإِنْ كَذَّبُوكَ فَقُلْ رَبُّكُمْ ذُو رَحْمَةٍ واسِعَةٍ وَلا يُرَدُّ بَأْسُهُ عَنِ الْقَوْمِ الْمُجْرِمِينَ (147) سَيَقُولُ الَّذِينَ أَشْرَكُوا لَوْ شاءَ اللهُ ما أَشْرَكْنا وَلا آباؤُنا وَلا حَرَّمْنا مِنْ شَيْءٍ كَذلِكَ كَذَّبَ الَّذِينَ مِنْ قَبْلِهِمْ حَتَّى ذاقُوا بَأْسَنا الله ويقتلون الأنبياء بغير حق ( وَإِنَّا لَصادِقُونَ ) في إخبارنا عن بني إسرائيل وما فعلوا وما فعلنا بهم ، وذلك بخلاف كثير من الأعداء حيث يلفّقون أخبارا مكذوبة على أعدائهم لحطّهم في أعين الناس.` },
            { text: "وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا كُلَّ ذِى ظُفُرٍ وَمِنَ ٱلْبَقَرِ وَٱلْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَآ إِلَّا مَا حَمَلَتْ ظُهُورُهُمَآ أَوِ ٱلْحَوَايَآ أَوْ مَا ٱخْتَلَطَ بِعَظْمٍ ذَٰلِكَ جَزَيْنَٰهُم بِبَغْيِهِمْ وَإِنَّا لَصَٰدِقُونَ", tafsir: `` },
            { text: "فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٍ وَٰسِعَةٍ وَلَا يُرَدُّ بَأْسُهُۥ عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ", tafsir: `يا رسول الله فيما ذكرت للمشركين من التحريم والتحليل ، حيث قالوا : إن حرام الله وحلاله كما نقول ، أو فيما ذكرت عن اليهود من تحريم الله عليهم المذكورات بسبب بغيهم ( فَقُلْ ) لهم : ( رَبُّكُمْ ذُو رَحْمَةٍ واسِعَةٍ ) يرحم جميع ذوي الروح ، ولذا لا يعاجلكم بالعقوبة لكي تتوبوا ( وَ ) لكن مع ذلك ( لا يُرَدُّ بَأْسُهُ ) أي : لا يدفع عذابه إذا جاء وقته ( عَنِ الْقَوْمِ الْمُجْرِمِينَ ) الذين ارتكبوا الجرائم.` },
            { text: "سَيَقُولُ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكْنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن شَىْءٍ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُوا۟ بَأْسَنَا قُلْ هَلْ عِندَكُم مِّنْ عِلْمٍ فَتُخْرِجُوهُ لَنَآ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ أَنتُمْ إِلَّا تَخْرُصُونَ", tafsir: `واتخذوا شريكا لله سبحانه ، للدفاع عن أنفسهم ، وتبرير شركهم ( لَوْ شاءَ اللهُ ) أن لا نشرك ( ما أَشْرَكْنا ) نحن ( وَلا ) أشرك ( آباؤُنا ) من قبل ( وَلا حَرَّمْنا مِنْ شَيْءٍ ) فإذا أشركنا وحرمنا وسكت الله عنا فهو يرضى بذلك ويريد شركنا وتحريمنا ( كَذلِكَ ) أي كتكذيب هؤلاء لك يا رسول الله في قولك : إن الله لا يرضى بالشرك ولم يحرّم ما حرّمتموه ( كَذَّبَ الَّذِينَ مِنْ قَبْلِهِمْ ) أنبياءهم ( حَتَّى ذاقُوا بَأْسَنا ) أي : حتى نالوا عذابنا ونكالنا قُلْ هَلْ عِنْدَكُمْ مِنْ عِلْمٍ فَتُخْرِجُوهُ لَنا إِنْ تَتَّبِعُونَ إِلاَّ الظَّنَّ وَإِنْ أَنْتُمْ إِلاَّ تَخْرُصُونَ (148) قُلْ فَلِلَّهِ الْحُجَّةُ الْبالِغَةُ فَلَوْ شاءَ لَهَداكُمْ أَجْمَعِينَ (149) قُلْ هَلُمَّ شُهَداءَكُمُ الَّذِينَ يَشْهَدُونَ أَنَّ اللهَ حَرَّمَ هذا فَإِنْ شَهِدُوا فَلا تَشْهَدْ مَعَهُمْ ( قُلْ ) يا رسول الله لهم ، ردّا على حجتهم ( هَلْ عِنْدَكُمْ ) أيها المشركون ( مِنْ عِلْمٍ ) بأن الله يريد شرككم وتحريمكم للمحللات ( فَتُخْرِجُوهُ لَنا ) وإذ ليس لكم دليل فكلامكم خال عن الحجة ( إِنْ تَتَّبِعُونَ ) أي ما تتبعون في أقوالكم وأعمالكم ( إِلَّا الظَّنَ ) فإنكم تظنون ما تقولونه لما اعتدتم عليه ( وَإِنْ أَنْتُمْ ) أي : ما أنتم ( إِلَّا تَخْرُصُونَ ) الخرص ، هو : التخمين.` },
            { text: "قُلْ فَلِلَّهِ ٱلْحُجَّةُ ٱلْبَٰلِغَةُ فَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ", tafsir: `يا رسول الله لهم : إنكم إذا عجزتم عن إقامة الدليل على عقيدتكم ومدّعاكم ( فَلِلَّهِ الْحُجَّةُ الْبالِغَةُ ) التي بلّغتكم ، بأنه لا يريد الشرك ، ولم يحرّم المذكورات ( فَلَوْ شاءَ لَهَداكُمْ أَجْمَعِينَ ) بالجبر والإكراه ، لكنه لا يشاء ذلك حتّى يجري الاختيار والاختبار.` },
            { text: "قُلْ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشْهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَا فَإِن شَهِدُوا۟ فَلَا تَشْهَدْ مَعَهُمْ وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ", tafsir: `يا رسول الله لهؤلاء الذين حرموا الأمور المذكورة : ( هَلُمَ ) أي : أحضروا ( شُهَداءَكُمُ الَّذِينَ يَشْهَدُونَ أَنَّ اللهَ حَرَّمَ هذا ) الذي ذكرتم حرمته من أقسام الحيوان والزرع ، إنه طالبهم بالعلم فلم يكن عندهم ، ثم طالبهم بالشاهد ، لكنه لا شاهد عندهم ، ولكنهم قد يأتون بشهود زور ( فَإِنْ شَهِدُوا فَلا تَشْهَدْ ) يا رسول الله ( مَعَهُمْ ) فإن شهادتهم باطلة. وإن قيل : كيف دعاهم إلى الشهادة ، ثم لم يقبل شهادتهم ؟ وَلا تَتَّبِعْ أَهْواءَ الَّذِينَ كَذَّبُوا بِآياتِنا وَالَّذِينَ لا يُؤْمِنُونَ بِالْآخِرَةِ وَهُمْ بِرَبِّهِمْ يَعْدِلُونَ (150) قُلْ تَعالَوْا أَتْلُ ما حَرَّمَ رَبُّكُمْ عَلَيْكُمْ أَلاَّ تُشْرِكُوا بِهِ شَيْئاً وَبِالْوالِدَيْنِ إِحْساناً قلنا : إنه دعاهم إلى أن يأتوا بالشهود العدول لا من أنفسهم ، وإلّا فالمدعي لا يكون شاهدا ، فإن شهدوا بأنفسهم لم تقبل شهادتهم. ( وَلا تَتَّبِعْ ) يا رسول الله ( أَهْواءَ الَّذِينَ كَذَّبُوا بِآياتِنا ) أي هوى أنفسهم ، فإن من لا يعمل بالحق لا بد وأن يكون متبعا لهواه ، وحيث يرشده الهوى إليه ( وَ ) لا تتبع أهواء ( الَّذِينَ لا يُؤْمِنُونَ بِالْآخِرَةِ ) كالكفار الذين كانوا ينكرون البعث. ومن المعلوم أن الكفار كانوا على قسمين : منهم من يؤمن بالآخرة كأهل الكتاب ، ومنهم من لا يؤمن بها كالدهرية ( وَهُمْ بِرَبِّهِمْ يَعْدِلُونَ ) أي : يجعلون له عدلا وشريكا. [152] وبعد استنكار ما حرمه المشركون على أنفسهم ، واستنكار استحلالهم لبعض المحرمات ، يأتي السياق لبيان المحرمات الواقعية التي حرّمها الله سبحانه ( قُلْ ) يا رسول الله لهؤلاء المشركين : ( تَعالَوْا ) أي أقبلوا واحضروا ( أَتْلُ ) أي أقرأ ( ما حَرَّمَ رَبُّكُمْ عَلَيْكُمْ ) « ما » مفعول « أتل » ( أَلَّا تُشْرِكُوا بِهِ ) أي بالله ( شَيْئاً ) أي لا تجعلوا له سبحانه شريكا. والجملة في تأويل المصدر ، فيكون بدلا من « ما حرم » أي أتل تحريم الشرك. فلا يقال : إن النفي في النفي يفيد الإثبات. ( وَبِالْوالِدَيْنِ إِحْساناً ) أي أوصاكم بهما إحسانا ، إذ في « حرّم » معنى الإيصاء ، و « إحسانا » منصوب بفعل مقدّر ، تقديره : « أحسنوا وَلا تَقْتُلُوا أَوْلادَكُمْ مِنْ إِمْلاقٍ نَحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ وَلا تَقْرَبُوا الْفَواحِشَ ما ظَهَرَ مِنْها وَما بَطَنَ وَلا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللهُ إِلاَّ بِالْحَقِّ ذلِكُمْ وَصَّاكُمْ بِهِ لَعَلَّكُمْ تَعْقِلُونَ (151) بالوالدين إحسانا » . ومن المعلوم أن ترك كل واجب حرام ، ولذا صحّ تعداده في جملة « ما حرم » ( وَلا تَقْتُلُوا أَوْلادَكُمْ ) بنين وبنات ( مِنْ إِمْلاقٍ ) هو الفقر ، أي من جهة الفقر ، فقد كان المشركون يقتلون أولادهم ، خوف أن يفتقروا فلا يجدوا مؤونتهم. ( نَحْنُ نَرْزُقُكُمْ ) أنتم أيها الآباء ( وَإِيَّاهُمْ ) أي الأبناء ، فليس رزقهم عليكم ، ثم إن من المعلوم أن الرزق يحتاج إلى جدّ وتعب فليس المراد برزقه إياهم أنه ينزله من السماء في الدلو ( وَلا تَقْرَبُوا الْفَواحِشَ ) جمع فاحشة ، صفة للمقدر أي « الصفة الفاحشة » ( ما ظَهَرَ مِنْها ) للناس ( وَما بَطَنَ ) أي أتي به سرا ، وهذا يشمل جميع المحرمات غير المذكورة بالنص ( وَلا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللهُ ) من المسلم والمعاهد ( إِلَّا بِالْحَقِ ) وقد تقدم أن مثل هذه الاستثناءات من أصل الكلام ، لا من قيده ، أي لا تقتلوا النفس إلّا بالحق ، والحق في القتل في موارد خاصة ، كالجهاد ، والزاني المحصن ، والمرتد الفطري ، والمهاجم والقصاص ، وما أشبه. ( ذلِكُمْ ) المذكور في الآية من المحرمات ( وَصَّاكُمْ ) الله ( بِهِ ) أي أمركم به ، فإن الوصية بمعنى الأمر ( لَعَلَّكُمْ ) أيها البشر ( تَعْقِلُونَ ) أي تحكّمون عقولكم في المحرم والمحلل ، فلا تقولوا شيئا اعتباطا. وَلا تَقْرَبُوا مالَ الْيَتِيمِ إِلاَّ بِالَّتِي هِيَ أَحْسَنُ حَتَّى يَبْلُغَ أَشُدَّهُ وَأَوْفُوا الْكَيْلَ وَالْمِيزانَ بِالْقِسْطِ لا نُكَلِّفُ نَفْساً إِلاَّ وُسْعَها` },
            { text: "قُلْ تَعَالَوْا۟ أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ أَلَّا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا وَلَا تَقْتُلُوٓا۟ أَوْلَٰدَكُم مِّنْ إِمْلَٰقٍ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ وَلَا تَقْرَبُوا۟ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَعْقِلُونَ", tafsir: `` },
            { text: "وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ وَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ بِٱلْقِسْطِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا وَإِذَا قُلْتُمْ فَٱعْدِلُوا۟ وَلَوْ كَانَ ذَا قُرْبَىٰ وَبِعَهْدِ ٱللَّهِ أَوْفُوا۟ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَذَكَّرُونَ", tafsir: `وهو من فقد الأب والجد ، أو الأعم منه ومن فقد الأم ، وكلمة « لا تقربوا » للمبالغة في الاجتناب ، وتخصيص اليتيم بالذكر ، مع عدم جواز التصرف في مال كل أحد بدون رضاه ، لأجل أن اليتيم لا يقدر على الدفاع عن نفسه ( إِلَّا بِالَّتِي هِيَ أَحْسَنُ ) أي بالطريقة التي هي أحسن من سائر الطرق ، بأن يحفظ له ماله إلا بمقدار ضروري لمعاش اليتيم حيث ينفق عليه ( حَتَّى يَبْلُغَ أَشُدَّهُ ) « الأشد » : جمع « شد » نحو : أضر ، جمع : ضر ، والشد : القوة ، وهو استحكام قوة الشباب ، أي حتى يبلغ إلى قوة شبابه ، وهو إنما يحصل بالبلوغ والرشد ، والبلوغ في الولد كمال خمس عشرة سنة ، أو الإنبات ، أو الاحتلام ، وفي البنت غالبا كمال التسعة والدخول في العاشرة ( وَأَوْفُوا الْكَيْلَ وَالْمِيزانَ ) فلا تنقصوا الكيل والميزان عند البيع ، ولا تزيدوهما عند الشراء ( بِالْقِسْطِ ) أي بالعدل ، فلا إفراط ولا تفريط. ( لا نُكَلِّفُ نَفْساً إِلَّا وُسْعَها ) أي بالمقدار الذي يسعها ، ولا يوجب ضيقا وحرجا عليها ، فهذه التكاليف السابقة ، لا حرج فيها على النفس ، أو المراد أن الوفاء بالكيل والوزن حسب المتعارف ، لا الدقة العقلية حتى يوجب عسرا وحرجا. ولا يقال : فكيف كلّف الإنسان بالجهاد ؟ لأنا نقول : إن الجهاد خارج عن هذا العموم ، فإنه لإرساء قواعد وَإِذا قُلْتُمْ فَاعْدِلُوا وَلَوْ كانَ ذا قُرْبى وَبِعَهْدِ اللهِ أَوْفُوا ذلِكُمْ وَصَّاكُمْ بِهِ لَعَلَّكُمْ تَذَكَّرُونَ (152) وَأَنَّ هذا صِراطِي مُسْتَقِيماً فَاتَّبِعُوهُ وَلا تَتَّبِعُوا السُّبُلَ الإسلام ، والعموم إنما هو في مقابل التكاليف في سائر الشرائع ـ المنحرفة ـ والقوانين المرهقة ، فإنه يريد بيان سهولة أحكام الإسلام وسماحتها. ( وَإِذا قُلْتُمْ ) شيئا ( فَاعْدِلُوا ) في القول ، والعدل فيه أن لا يميل القائل نحو الباطل. فالغيبة ، والسبّ ، والقضاء بغير الحق ، وما أشبهها ، ظلم ، ليس بعدل ( وَلَوْ كانَ ) المقول فيه ( ذا قُرْبى ) فإن الناس غالبا يقولون الباطل لصالح ذوي قرباهم ، ولذا يأمرهم سبحانه بالعدل بالنسبة إليهم ( وَبِعَهْدِ اللهِ أَوْفُوا ) والمراد جميع معاهداته ، كما قال : ( أَوْفُوا بِعَهْدِي أُوفِ بِعَهْدِكُمْ ) (1) ، فالمراد الإتيان بالواجبات وترك المحرمات ( ذلِكُمْ ) الذي تقدم ذكره من الأحكام ( وَصَّاكُمْ بِهِ ) على طريق اللزوم والحتم ( لَعَلَّكُمْ تَذَكَّرُونَ ) أي لكي تتذكروا وتأخذوا به ، والتذكّر باعتبار ما هو كامن في الفطرة من حسن هذه الأشياء ، كما سبق.` },
            { text: "وَأَنَّ هَٰذَا صِرَٰطِى مُسْتَقِيمًا فَٱتَّبِعُوهُ وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَتَّقُونَ", tafsir: `وصّاكم سبحانه ( أَنَّ هذا صِراطِي مُسْتَقِيماً ) أي أن الأحكام التي أنزلتها توصل إلى السعادة ، فهي طريق إليها بالاستقامة ، لا كسائر الطرق الملتوية ، التي قد لا توصل ، وقد توصل بالتواء وعناء ( فَاتَّبِعُوهُ ) أي سيروا عليه وانتهجوه ( وَلا تَتَّبِعُوا السُّبُلَ ) الأخرى من سبل الكفر والبدع ( 1) البقرة : 41. فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ ذلِكُمْ وَصَّاكُمْ بِهِ لَعَلَّكُمْ تَتَّقُونَ (153) ثُمَّ آتَيْنا مُوسَى الْكِتابَ تَماماً عَلَى الَّذِي أَحْسَنَ وَتَفْصِيلاً لِكُلِّ شَيْءٍ وَهُدىً وَرَحْمَةً لَعَلَّهُمْ بِلِقاءِ رَبِّهِمْ يُؤْمِنُونَ (154) وَهذا كِتابٌ أَنْزَلْناهُ مُبارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ (155) والشبهات ( فَتَفَرَّقَ ) أي تتفرق تلك السبل ( بِكُمْ عَنْ سَبِيلِهِ ) فتشتّتكم ، وتلهيكم عن طريقه سبحانه ( ذلِكُمْ ) الاتباع لسبيله ( وَصَّاكُمْ ) الله ( بِهِ ) إلزاما ( لَعَلَّكُمْ تَتَّقُونَ ) أي لكي تتقوا عقابه وتحذروا الخسران. [155] إن هذا الصراط كان قديما قبل موسى وعيسى ومحمد عليهم‌السلام ، وإن الجميع كانوا مأمورين باتباعه ( ثُمَ ) بعد سبق هذا الصراط عند الأنبياء السابقين ( آتَيْنا مُوسَى الْكِتابَ ) أي أعطيناه التوراة ( تَماماً عَلَى الَّذِي أَحْسَنَ ) أي لأجل إتمام عمل موسى عليه‌السلام الحسن الذي أدّاه ؛ من القيام بالتبشير والهداية ، أو لأجل إتمام النعمة على موسى الذي أحسن الخدمة لله سبحانه ، فإن إنزال الكتاب على النبي من أعظم المفاخر بالنسبة إليه ( وَتَفْصِيلاً لِكُلِّ شَيْءٍ ) مما يحتاج إليه الناس ( وَهُدىً ) أي دلالة على الحق ( وَرَحْمَةً ) يرحم الله بسببه على عباده حيث ينقذهم من الشقاء إلى السعادة ( لَعَلَّهُمْ ) أي لعل الناس ( بِلِقاءِ رَبِّهِمْ ) أي بملاقاة جزائه وثوابه وعقابه ( يُؤْمِنُونَ ) فيسعدون.` },
            { text: "ثُمَّ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ تَمَامًا عَلَى ٱلَّذِىٓ أَحْسَنَ وَتَفْصِيلًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لَّعَلَّهُم بِلِقَآءِ رَبِّهِمْ يُؤْمِنُونَ", tafsir: `` },
            { text: "وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌ فَٱتَّبِعُوهُ وَٱتَّقُوا۟ لَعَلَّكُمْ تُرْحَمُونَ", tafsir: `القرآن ( كِتابٌ أَنْزَلْناهُ مُبارَكٌ ) له بركة يأتي منه الخير الكثير ( فَاتَّبِعُوهُ ) أيها الناس ( وَاتَّقُوا ) معاصي الله سبحانه ، ومخالفة كتابه ( لَعَلَّكُمْ تُرْحَمُونَ ) أي لكي تشملكم الرحمة. أَنْ تَقُولُوا إِنَّما أُنْزِلَ الْكِتابُ عَلى طائِفَتَيْنِ مِنْ قَبْلِنا وَإِنْ كُنَّا عَنْ دِراسَتِهِمْ لَغافِلِينَ (156) أَوْ تَقُولُوا لَوْ أَنَّا أُنْزِلَ عَلَيْنَا الْكِتابُ لَكُنَّا أَهْدى مِنْهُمْ فَقَدْ جاءَكُمْ بَيِّنَةٌ مِنْ رَبِّكُمْ وَهُدىً وَرَحْمَةٌ فَمَنْ أَظْلَمُ مِمَّنْ كَذَّبَ بِآياتِ اللهِ وَصَدَفَ عَنْها سَنَجْزِي الَّذِينَ يَصْدِفُونَ عَنْ [157] وإنما أنزلنا هذا الكتاب ( أَنْ تَقُولُوا ) أي لئلّا تقولوا : ( إِنَّما أُنْزِلَ الْكِتابُ ) من قبل الله سبحانه ( عَلى طائِفَتَيْنِ ) اليهود والنصارى ( مِنْ قَبْلِنا ) ولم يرتبط الكتاب بنا حتى نؤمن به ( وَإِنْ كُنَّا ) « إن » مخففة من المثقلة ، أي أنه كنّا نحن العرب ( عَنْ دِراسَتِهِمْ ) أي دراسة أولئك الطوائف المنزلة عليهم الكتب ، أي لغتهم ( لَغافِلِينَ ) فلم نعرف ما في كتبهم حتى نؤمن بها ، فقد أنزلنا إليكم الكتاب حتى لا يكون لكم عذرا في عدم الإيمان.` },
            { text: "أَن تَقُولُوٓا۟ إِنَّمَآ أُنزِلَ ٱلْكِتَٰبُ عَلَىٰ طَآئِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَٰفِلِينَ", tafsir: `` },
            { text: "أَوْ تَقُولُوا۟ لَوْ أَنَّآ أُنزِلَ عَلَيْنَا ٱلْكِتَٰبُ لَكُنَّآ أَهْدَىٰ مِنْهُمْ فَقَدْ جَآءَكُم بَيِّنَةٌ مِّن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ فَمَنْ أَظْلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنْهَا سَنَجْزِى ٱلَّذِينَ يَصْدِفُونَ عَنْ ءَايَٰتِنَا سُوٓءَ ٱلْعَذَابِ بِمَا كَانُوا۟ يَصْدِفُونَ", tafsir: `الذي نفهمه ( لَكُنَّا أَهْدى مِنْهُمْ ) أي أكثر هداية في التمسك والعمل على طبق الكتاب لأنا ألين عريكة ، وأكثر تمسكا بالمعتقدات ( فَقَدْ جاءَكُمْ ) أيتها الأمة المعاصرة للرسول ( بَيِّنَةٌ ) أي دلالة واضحة ( مِنْ رَبِّكُمْ ) وهو القرآن ( وَهُدىً ) يهتدى به إلى الحق ( وَرَحْمَةٌ ) يرحم بها الله من تمسّك به ، إذ يسعده في الدنيا والآخرة. ( فَمَنْ أَظْلَمُ ) أي من يكون أكثر ظلما لنفسه ( مِمَّنْ كَذَّبَ بِآياتِ اللهِ ) ؟! وهو القرآن ( وَصَدَفَ ) أي أعرض ( عَنْها ) أي عن الآيات ( سَنَجْزِي ) في الآخرة ، أو الأعم منها ومن الدنيا ( الَّذِينَ يَصْدِفُونَ عَنْ آياتِنا سُوءَ الْعَذابِ بِما كانُوا يَصْدِفُونَ (157) هَلْ يَنْظُرُونَ إِلاَّ أَنْ تَأْتِيَهُمُ الْمَلائِكَةُ أَوْ يَأْتِيَ رَبُّكَ أَوْ يَأْتِيَ بَعْضُ آياتِ رَبِّكَ يَوْمَ يَأْتِي بَعْضُ آياتِ رَبِّكَ لا يَنْفَعُ نَفْساً إِيمانُها لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمانِها خَيْراً قُلِ انْتَظِرُوا إِنَّا مُنْتَظِرُونَ (158) آياتِنا سُوءَ الْعَذابِ ) أي العذاب الشديد ( بِما كانُوا يَصْدِفُونَ ) أي بسبب إعراضهم عن الحق والآيات. [159] ما ينتظر هؤلاء الكفار بعد نزول القرآن ؟ ( هَلْ يَنْظُرُونَ ) أي هل ينتظرون للإيمان ( إِلَّا أَنْ تَأْتِيَهُمُ الْمَلائِكَةُ ) وذلك لا يمكن في دار التكليف ( أَوْ يَأْتِيَ رَبُّكَ ) وذلك مستحيل لأن الله لا مكان له ولا حركة ( أَوْ يَأْتِيَ بَعْضُ آياتِ رَبِّكَ ) أي العذاب ، حتى يروا العذاب فيؤمنوا ( يَوْمَ يَأْتِي بَعْضُ آياتِ رَبِّكَ ) يا رسول الله ( لا يَنْفَعُ نَفْساً إِيمانُها لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ ) فإن العذاب إذا نزل لا تقبل التوبة ، لأن العذاب لا ينزل إلا بعد تمام الحجة والمخالفة ، وحين ذاك قد تم الاختبار وصار موعد المجازاة ( أَوْ كَسَبَتْ فِي إِيمانِها خَيْراً ) عطف على « لم تكن آمنت » ، والمعنى : أنه لا ينفع في ذلك اليوم إيمان نفس إذا لم تكن آمنت قبل ذلك اليوم ، أو ضمت إلى إيمانها أفعال الخير ، فإنها إذا آمنت فقد نفعها إيمانها ، وكذلك إذا ضمت إلى الإيمان طاعة لنفعها أيضا ، فلا ينفع إيمان الكافر ، ولا طاعة المؤمن عند حلول العذاب ، وإنما النافع الإيمان السابق ، والطاعة السابقة ( قُلِ ) يا رسول الله لهؤلاء : ( انْتَظِرُوا ) إتيان بعض آيات الله ف ( إِنَّا مُنْتَظِرُونَ ) ذلك إِنَّ الَّذِينَ فَرَّقُوا دِينَهُمْ وَكانُوا شِيَعاً لَسْتَ مِنْهُمْ فِي شَيْءٍ إِنَّما أَمْرُهُمْ إِلَى اللهِ ثُمَّ يُنَبِّئُهُمْ بِما كانُوا يَفْعَلُونَ ( 159) حتى يرى كل واحد منّا جزاءه العادل وما قدم لنفسه. [160] ثم يقرّر سبحانه أن الإسلام إنما هو دين واحد لا تفرقة فيه ، فالذين يتفرقون ليسوا من الإسلام ، كما أن من أشرك ليس من الإسلام ( إِنَّ الَّذِينَ فَرَّقُوا دِينَهُمْ ) تفريقا بالأهواء كالكفار المختلفين ، أو بالأديان كاليهود والنصارى وفرقهم ، أو بالضلالة والشبهات ولو في دين الإسلام ، كالفرق المبتدعة ، فإن الذين يفعلون ذلك ( وَكانُوا شِيَعاً ) جمع « شيعة » أي طوائف مختلفة ( لَسْتَ ) يا رسول الله ( مِنْهُمْ فِي شَيْءٍ ) فلا ربط بينكما أبدا ، وإنما هم في جهة وأنت في جهة. وليس معنى أن الجميع على باطل ، بل المعنى أن ما ليس فيه الرسول باطل ، وإلّا فالحق دائما مع إحدى الطوائف ( إِنَّما أَمْرُهُمْ ) أي أمر هؤلاء الذين فرّقوا دينهم وكانوا شيعا ( إِلَى اللهِ ) فهو الذي يجازيهم لسوء أفعالهم ( ثُمَّ يُنَبِّئُهُمْ ) أي يخبرهم ( بِما كانُوا يَفْعَلُونَ ) من الأعمال. وهذا تهديد ، كقولك : « لأعلمنك غدا » لمن خالف أمرك ، تريد أنك تعاقبه بفعله. وهنا سؤال : إذا علمنا نحن المسلمين بطلان سائر المذاهب والطوائف ، فما ذا نفعل بهذا الاختلاف بين المسلمين أنفسهم ؟ والجواب : إن الكتاب والسنّة يأمراننا باتباع علي وأهل بيته الأئمة الأحد عشر عليهم‌السلام ، وبعد ذلك فقد عيّن الفقهاء الراشدون لمرجعية الأمة ، في قوله عليه‌السلام : « من كان من الفقهاء صائنا لنفسه ، حافظا لدينه ، مَنْ جاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثالِها وَمَنْ جاءَ بِالسَّيِّئَةِ فَلا مخالفا لهواه مطيعا لأمر مولاه ، فللعوام أن يقلدوه » (1) . و قوله عليه‌السلام : « أما الحوادث الواقعة فارجعوا فيها إلى رواة حديثنا ، فإنهم حجتي عليكم وأنا حجة الله » (2) . أما الاختلاف بين الفقهاء في بعض الفروع فليس ذلك اختلافا يذكر ، بل هو كالاختلاف بين كل مهندسين ، أو طبيبين ، أو حاكمين ، مع إخلاص كل منهما واتحاد منهجهما. ثم إنه قد يستغرب : كيف يكون مصير هذه الكثرة من الناس الذين ليسوا بمسلمين ، وكثير من المسلمين المنحرفين ، النار ، ومن يبقى للجنة إذا ؟ والجواب : إن ما يستفاد من الآيات والروايات أن الخلود في النار إنما هو للمعاند ، ولا دليل على أنه لا يمتحن القاصر من البشر في الآخرة ليدخل الجنة ، بل دلّ الدليل على ذلك ، كما هو مذكور في علم الكلام. ومن المعلوم عدم كون أكثر الناس مقصرين معاندين ، إذا فليس بالبعيد دخول كثرة هائلة من البشر الجنة ، للإيمان وحسن العمل في الدنيا ، أو حسن الامتحان في الآخرة. [161] وإذ تقدم الكلام حول الجزاء يقرر السياق القاعدة العامة له وأنه ( مَنْ جاءَ بِالْحَسَنَةِ ) التاء إما للمبالغة ، وإما للتأنيث أي طاعة حسنة ( فَلَهُ ) من الثواب ( عَشْرُ أَمْثالِها ) على الأقل وإلا فقد يبلغ الثواب إلى ( سَبْعَ سَنابِلَ فِي كُلِّ سُنْبُلَةٍ مِائَةُ حَبَّةٍ وَاللهُ يُضاعِفُ لِمَنْ يَشاءُ ) (3) ، ( وَمَنْ جاءَ بِالسَّيِّئَةِ ) في التاء القولان ، وإذا كانت للتأنيث فهي صفة « خصلة » ( فَلا ( 1) تفسير الإمام العسكري : ص 299. ( 2) وسائل الشيعة : ج 27 ص 140. ( 3) البقرة : 262. يُجْزى إِلاَّ مِثْلَها وَهُمْ لا يُظْلَمُونَ (160) قُلْ إِنَّنِي هَدانِي رَبِّي إِلى صِراطٍ مُسْتَقِيمٍ دِيناً قِيَماً مِلَّةَ إِبْراهِيمَ حَنِيفاً وَما كانَ مِنَ الْمُشْرِكِينَ (161) قُلْ إِنَّ صَلاتِي يُجْزى إِلَّا مِثْلَها ) سيئة واحدة وإن كانت عظيمة جدا ، فلا يقال : ما فائدة « الواحدة » فيما لو كانت أعظم من المعصية ككذبة واحدة جزاؤها سنة في النار ـ مثلا ـ؟ فمثلا جزاء من يسب الملك بلفظة مائة سوط ، وهو جزاء واحد ، وإن كان عظيما في نفسه ( وَهُمْ لا يُظْلَمُونَ ) في مقدار ما استحقوا من السيئات بل جزاء وفاقا.` },
            { text: "هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَٰٓئِكَةُ أَوْ يَأْتِىَ رَبُّكَ أَوْ يَأْتِىَ بَعْضُ ءَايَٰتِ رَبِّكَ يَوْمَ يَأْتِى بَعْضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفْسًا إِيمَٰنُهَا لَمْ تَكُنْ ءَامَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِىٓ إِيمَٰنِهَا خَيْرًا قُلِ ٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًا لَّسْتَ مِنْهُمْ فِى شَىْءٍ إِنَّمَآ أَمْرُهُمْ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُوا۟ يَفْعَلُونَ", tafsir: `` },
            { text: "مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ عَشْرُ أَمْثَالِهَا وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ", tafsir: `` },
            { text: "قُلْ إِنَّنِى هَدَىٰنِى رَبِّىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ دِينًا قِيَمًا مِّلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ", tafsir: `يا رسول الله لهؤلاء الكفار : ( إِنَّنِي هَدانِي رَبِّي ) أي أرشدني ( إِلى صِراطٍ مُسْتَقِيمٍ ) والمراد : الصراط الموصل للإنسان إلى الحقائق والسعادة في الدنيا والآخرة ، بالنسبة إلى كل شيء من الأمور ( دِيناً ) منصوب على تقدير هداني ، أي هداني دينا ، أو على الحال أي أن الصراط في حال كونه دينا ( قِيَماً ) أي مستقيما ، وهو مصدر ، ك « الصغر والكبر » ( مِلَّةَ إِبْراهِيمَ ) بدل من « دينا » والملة : هي الشريعة ، مأخوذة من « الإملاء » لأن الشرع يمليه الرسول على أمته ، وإنما نسب الدين إلى إبراهيم عليه‌السلام لاتفاق جميع الأديان على جلالته عليه‌السلام وصحة دينه ، وقد كانت الأديان كلها دينا واحدا فلا مانع أن ينسب اللاحق إلى السابق ( حَنِيفاً ) أي في حال كون تلك الملة مائلة عن الباطل إلى الحق ، من « حنف » بمعنى « مال » ( وَما كانَ ) إبراهيم عليه‌السلام ( مِنَ الْمُشْرِكِينَ ) فلم يكن مشركا كمشركي مكة ولا يهوديا ولا نصرانيا ، فكلاهما مشركان.` },
            { text: "قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ", tafsir: `يا رسول الله لهؤلاء : ( إِنَّ صَلاتِي ) وهي الصلوات التي يأتيها وَنُسُكِي وَمَحْيايَ وَمَماتِي لِلَّهِ رَبِّ الْعالَمِينَ (162) لا شَرِيكَ لَهُ وَبِذلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ (163) قُلْ أَ غَيْرَ اللهِ أَبْغِي رَبًّا وَهُوَ رَبُّ كُلِّ شَيْءٍ وَلا تَكْسِبُ كُلُّ نَفْسٍ إِلاَّ عَلَيْها وَلا تَزِرُ وازِرَةٌ وِزْرَ أُخْرى الإنسان واجبة أو مندوبة ( وَنُسُكِي ) النسك : العبادة ، يقال : رجل ناسك أي متعبد ، ويقال للأضحية : النسكية ، للتقرب بها إلى الله ، فهي عبادة ( وَمَحْيايَ وَمَماتِي ) أي حياتي وموتي ( لِلَّهِ رَبِّ الْعالَمِينَ ) فإن عبادتي له وحده بلا شريك ، وأموالي ملكه وبقدرته لا بشركة أحد معه.` },
            { text: "لَا شَرِيكَ لَهُۥ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا۠ أَوَّلُ ٱلْمُسْلِمِينَ", tafsir: `لا أشرك أحدا به في العبادة ، ولا أزعم أن له شريكا في حياتي وموتي ( وَبِذلِكَ ) أي بالتوحيد ( أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ ) من هذه الأمة ، أو المراد رتبة إسلامي من أول الرتب.` },
            { text: "قُلْ أَغَيْرَ ٱللَّهِ أَبْغِى رَبًّا وَهُوَ رَبُّ كُلِّ شَىْءٍ وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ", tafsir: `يا رسول الله لهؤلاء : ( أَ غَيْرَ اللهِ أَبْغِي ) أي أطلب ( رَبًّا ) وإلها ( وَهُوَ رَبُّ كُلِّ شَيْءٍ ) الاستفهام للإنكار ، أي كيف أتخذ غير الله إلها ـ بالاستقلال أو بالشركة ـ والحال أنه تعالى رب كل شيء لا رب سواه ولا إله إلا هو ؟ ( وَلا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْها ) فإذا اكتسبت المعصية بالشرك ، لحقني جزائي السيئ ، ( وَلا تَزِرُ ) أي لا تحمل من « وزر » بمعنى حمل الإثم ( وازِرَةٌ ) أي نفس حاملة ( وِزْرَ ) أي معصية نفس ( أُخْرى ) بل عصيان كل أحد على نفسه وهو يحمل تبعته. قيل : إن الكفار قالوا للنبي صلى‌الله‌عليه‌وآله‌وسلم : اتبعنا وعلينا وزرك إن كان خطأ ، فأنزل الله هذه الآية. ثُمَّ إِلى رَبِّكُمْ مَرْجِعُكُمْ فَيُنَبِّئُكُمْ بِما كُنْتُمْ فِيهِ تَخْتَلِفُونَ (164) وَهُوَ الَّذِي جَعَلَكُمْ خَلائِفَ الْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍ دَرَجاتٍ لِيَبْلُوَكُمْ فِي ما آتاكُمْ إِنَّ رَبَّكَ سَرِيعُ الْعِقابِ وَإِنَّهُ لَغَفُورٌ رَحِيمٌ (165) ( ثُمَّ إِلى رَبِّكُمْ مَرْجِعُكُمْ ) أي إلى حسابه مصيركم أيها المشركون ، أو أيها البشر ( فَيُنَبِّئُكُمْ ) أي يخبركم ( بِما ) أي بالشيء الذي ( كُنْتُمْ فِيهِ تَخْتَلِفُونَ ) ليجازي كل إنسان وما عمله من إحسان وإساءة.` },
            { text: "وَهُوَ ٱلَّذِى جَعَلَكُمْ خَلَٰٓئِفَ ٱلْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍ دَرَجَٰتٍ لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ إِنَّ رَبَّكَ سَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌۢ", tafsir: `` }
        ]
    }
});
